8	// Default engine constants (extend R.CONFIG if not already set)
9	// ---------------------------------------------------------------------------
10	R.CONFIG = R.CONFIG || {};
11	R.CONFIG.CANVAS_WIDTH        = R.CONFIG.CANVAS_WIDTH        || 1280;
