16	R.CONFIG.FINISH_DELAY        = R.CONFIG.FINISH_DELAY        || 5;      // seconds before restart allowed
17	R.CONFIG.COUNTDOWN_DURATION  = R.CONFIG.COUNTDOWN_DURATION  || 3;      // seconds
