41	// ---------------------------------------------------------------------------
42	// Built-in keyboard fallback — guarantees R.input._keys exists even if the
43	// input module is not loaded.  initInput() may override/extend this.
44	// ---------------------------------------------------------------------------
45	
46	function _attachBuiltinInput() {
47	  if (R._inputAttached) return;
48	  R._inputAttached = true;
49	
50	  R.input = R.input || { throttle: 0, brake: 0, steer: 0, boost: 0, _keys: {} };
51	
52	  window.addEventListener('keydown', function (e) {
53	    R.input._keys[e.code] = true;
54	    // Prevent default for game keys so the page doesn't scroll
55	    if (e.code === 'ArrowUp'   || e.code === 'ArrowDown' ||
56	        e.code === 'ArrowLeft' || e.code === 'ArrowRight' ||
57	        e.code === 'Space'     || e.code === 'Enter') {
58	      e.preventDefault();
59	    }
60	    // Map arrows directly to driving inputs
61	    if (e.code === 'ArrowUp')    { R.input.throttle = 1; }
62	    if (e.code === 'ArrowDown')  { R.input.brake    = 1; }
63	    if (e.code === 'ArrowLeft')  { R.input.steer    = -1; }
64	    if (e.code === 'ArrowRight') { R.input.steer    =  1; }
65	  });
66	
67	  window.addEventListener('keyup', function (e) {
68	    R.input._keys[e.code] = false;
69	    if (e.code === 'ArrowUp')    { R.input.throttle = 0; }
70	    if (e.code === 'ArrowDown')  { R.input.brake    = 0; }
71	    if (e.code === 'ArrowLeft' || e.code === 'ArrowRight') { R.input.steer = 0; }
72	  });
73	}
