79	/**
80	 * Create the canvas element (1280×720), append to document.body, get 2d
81	 * context, initialise all subsystems, and start the game loop.
82	 *
83	 * Safe to call multiple times — subsequent calls are ignored.
84	 *
85	 * Usage:
86	 *   window.addEventListener('DOMContentLoaded', function () { R.init(); });
87	 */
88	R.init = function () {
89	  if (R._initialised) return;
90	  R._initialised = true;
91	
92	  // --- canvas element ---------------------------------------------------
93	  var canvas = document.createElement('canvas');
94	  canvas.id            = 'gameCanvas';
95	  canvas.width         = R.CONFIG.CANVAS_WIDTH;
96	  canvas.height        = R.CONFIG.CANVAS_HEIGHT;
97	  canvas.style.display     = 'block';
98	  canvas.style.margin      = '0 auto';
99	  canvas.style.background  = '#000';
100	  canvas.style.maxWidth    = '100%';
101	  canvas.style.maxHeight   = '100vh';
102	  canvas.style.touchAction = 'manipulation';
103	
104	  document.body.style.margin          = '0';
105	  document.body.style.overflow        = 'hidden';
106	  document.body.style.backgroundColor = '#111';
107	  document.body.style.display         = 'flex';
108	  document.body.style.alignItems      = 'center';
109	  document.body.style.justifyContent  = 'center';
110	  document.body.style.minHeight       = '100vh';
111	  document.body.appendChild(canvas);
112	
113	  R.canvas = canvas;
114	  R.ctx    = canvas.getContext('2d');
115	
116	  // --- game state -------------------------------------------------------
117	  R.state = {
118	    phase:           'menu',          // 'menu' | 'countdown' | 'racing' | 'finished'
119	    time:            0,               // wall-clock elapsed seconds
120	    countdownTimer:  R.CONFIG.COUNTDOWN_DURATION,
121	    raceTime:        0,               // seconds since race start
122	    bestLap:         Infinity,
123	    finishTimer:     0,
124	    playerLap:       0,
125	    playerFinished:  false
126	  };
127	
128	  // --- camera -----------------------------------------------------------
129	  R.camera = R.camera || { x: 0, y: 0, zoom: 1 };
130	
131	  // --- built-in keyboard support ----------------------------------------
132	  _attachBuiltinInput();
133	
134	  // --- bootstrap subsystems (each call is a no-op if the module is not loaded)
135	  _callIfExists('initInput');
136	  _callIfExists('initAudio');
137	  _callIfExists('initTrack');
138	  _callIfExists('initPlayer');
139	  _callIfExists('initAI');
140	  _callIfExists('initHUD');
141	  _callIfExists('initEffects');
142	  _callIfExists('initScenery');
143	
144	  // --- responsive canvas scaling ----------------------------------------
145	  window.addEventListener('resize', _onResize);
146	  _onResize();
147	
148	  // --- launch -----------------------------------------------------------
149	  R._lastTimestamp = undefined;
150	  requestAnimationFrame(R.loop);
151	};
