153	/**
154	 * Scale the canvas CSS size to fit the viewport while keeping the internal
155	 * resolution fixed at CANVAS_WIDTH × CANVAS_HEIGHT.
156	 */
157	function _onResize() {
158	  var c = R.canvas;
159	  if (!c) return;
160	  var ratio = R.CONFIG.CANVAS_WIDTH / R.CONFIG.CANVAS_HEIGHT;
161	  var w, h;
162	  if (window.innerWidth / window.innerHeight > ratio) {
163	    h = window.innerHeight;
164	    w = h * ratio;
165	  } else {
166	    w = window.innerWidth;
167	    h = w / ratio;
168	  }
169	  c.style.width  = Math.floor(w) + 'px';
170	  c.style.height = Math.floor(h) + 'px';
171	}
