173	// ---------------------------------------------------------------------------
174	// R.loop(timestamp) — Main game loop
175	// ---------------------------------------------------------------------------
176	
177	/**
178	 * Called every frame via requestAnimationFrame.
179	 * Calculates dt (capped at MAX_DT ms), runs all update and render passes,
180	 * then re-queues itself for the next frame.
181	 *
182	 * @param {DOMHighResTimeStamp} timestamp RAF timestamp in ms
183	 */
184	R.loop = function (timestamp) {
185	  // --- delta-time with spiral-of-death protection -----------------------
186	  if (R._lastTimestamp === undefined) {
187	    R._lastTimestamp = timestamp;
188	  }
189	  var rawDt = timestamp - R._lastTimestamp;
190	  R._lastTimestamp = timestamp;
191	  var dt = Math.min(rawDt, R.CONFIG.MAX_DT) / 1000; // ms → seconds
192	
193	  // --- update phase -----------------------------------------------------
194	  _callIfExists('updateInput');
195	
196	  R.updateStateMachine(dt);
197	
198	  var racing = R.state.phase === 'racing';
199	
200	  if (racing) {
201	    if (typeof R.updatePlayer === 'function') { R.updatePlayer(dt); }
202	    if (typeof R.updateAI === 'function')     { R.updateAI(dt); }
203	  }
204	
205	  if (typeof R.updateCamera === 'function')  { R.updateCamera(dt); }
206	  if (typeof R.updateEffects === 'function') { R.updateEffects(dt); }
207	  if (typeof R.updateHUD === 'function')     { R.updateHUD(dt); }
208	
209	  // --- render phase -----------------------------------------------------
210	  R.render();
211	
212	  // --- schedule next frame ----------------------------------------------
213	  requestAnimationFrame(R.loop);
214	};
