216	// ---------------------------------------------------------------------------
217	// R.updateStateMachine(dt) — Phase transitions
218	// ---------------------------------------------------------------------------
219	
220	/**
221	 * Advances the game state machine one tick.
222	 *
223	 *   'menu'      — wait for Enter/Space → countdown
224	 *   'countdown' — tick down to 0 → racing
225	 *   'racing'    — raceTime increments; when playerFinished → finished
226	 *   'finished'  — hold FINISH_DELAY seconds, then Enter/Space → menu
227	 *
228	 * @param {number} dt Delta-time in seconds
229	 */
230	R.updateStateMachine = function (dt) {
231	  var input = R.input;
232	  var state = R.state;
233	  if (!input || !state) return;
234	
235	  switch (state.phase) {
236	
237	    // ---- menu ----------------------------------------------------------
238	    case 'menu':
239	      if (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) {
240	        state.phase          = 'countdown';
241	        state.countdownTimer = R.CONFIG.COUNTDOWN_DURATION;
242	        state.raceTime       = 0;
243	        state.playerLap      = 0;
244	        state.playerFinished = false;
245	        state.bestLap        = Infinity;
246	        // Consume keys so a held key doesn't skip the countdown
247	        input._keys['Enter'] = false;
248	        input._keys[' ']     = false;
249	        input._keys['Space'] = false;
250	      }
251	      break;
252	
253	    // ---- countdown -----------------------------------------------------
254	    case 'countdown':
255	      state.countdownTimer -= dt;
256	      if (state.countdownTimer <= 0) {
257	        state.countdownTimer = 0;
258	        state.phase          = 'racing';
259	        state.raceTime       = 0;
260	        state.playerLap      = 0;
261	        state.playerFinished = false;
262	        state.bestLap        = Infinity;
263	      }
264	      break;
265	
266	    // ---- racing --------------------------------------------------------
267	    case 'racing':
268	      state.raceTime += dt;
269	
270	      // Check finish condition
271	      if (state.playerFinished) {
272	        state.phase       = 'finished';
273	        state.finishTimer = 0;
274	      }
275	      break;
276	
277	    // ---- finished ------------------------------------------------------
278	    case 'finished':
279	      state.finishTimer += dt;
280	      if (state.finishTimer >= R.CONFIG.FINISH_DELAY) {
281	        if (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) {
282	          state.phase          = 'menu';
283	          state.finishTimer    = 0;
284	          state.raceTime       = 0;
285	          state.playerLap      = 0;
286	          state.playerFinished = false;
287	          state.bestLap        = Infinity;
288	          input._keys['Enter'] = false;
289	          input._keys[' ']     = false;
290	          input._keys['Space'] = false;
291	        }
292	      }
293	      break;
294	
295	    default:
296	      // Unknown phase — reset to menu
297	      state.phase = 'menu';
298	      break;
299	  }
300	};
