302	// ---------------------------------------------------------------------------
303	// R.render() — Render pipeline
304	// ---------------------------------------------------------------------------
305	
306	/**
307	 * Clears the canvas and runs the full ordered render pass:
308	 *   sky → track → scenery → cars → effects → HUD → overlay
309	 *
310	 * Applies camera transform for world-space layers and restores it before
311	 * screen-space HUD/overlay layers.
312	 */
313	R.render = function () {
314	  var ctx = R.ctx;
315	  if (!ctx) return;
316	
317	  ctx.save();
318	
319	  // Clear the full canvas
320	  ctx.clearRect(0, 0, R.CONFIG.CANVAS_WIDTH, R.CONFIG.CANVAS_HEIGHT);
321	
322	  // --- world-space layers (camera-relative) -----------------------------
323	  _applyCameraTransform(ctx);
324	
325	  if (typeof R.renderSky     === 'function') { R.renderSky(ctx); }
326	  if (typeof R.renderTrack   === 'function') { R.renderTrack(ctx); }
327	  if (typeof R.renderScenery === 'function') { R.renderScenery(ctx); }
328	  if (typeof R.renderCars    === 'function') { R.renderCars(ctx); }
329	  if (typeof R.renderEffects === 'function') { R.renderEffects(ctx); }
330	
331	  // --- screen-space layers ----------------------------------------------
332	  ctx.restore();
333	  ctx.save();
334	
335	  if (typeof R.renderHUD     === 'function') { R.renderHUD(ctx); }
336	  if (typeof R.renderOverlay === 'function') { R.renderOverlay(ctx); }
337	
338	  ctx.restore();
339	};
340	
341	/**
342	 * Apply the camera translation and zoom to the canvas context.
343	 * World-space render calls should happen between apply and restore.
344	 * @param {CanvasRenderingContext2D} ctx
345	 */
346	function _applyCameraTransform(ctx) {
347	  var cam = R.camera;
348	  if (!cam) return;
349	  ctx.translate(R.CONFIG.CANVAS_WIDTH / 2, R.CONFIG.CANVAS_HEIGHT / 2);
350	  ctx.scale(cam.zoom || 1, cam.zoom || 1);
351	  ctx.translate(-cam.x, -cam.y);
352	}
353	
354	// ---------------------------------------------------------------------------
355	// R.updateCamera(dt) — Smooth camera follow
356	// ---------------------------------------------------------------------------
357	
358	/**
359	 * Lerp the camera toward the player car for smooth following.
360	 *
361	 * Uses a frame-rate-independent lerp so the feel is consistent at any FPS:
362	 *   t = 1 - (1 - CAMERA_SMOOTH) ^ (dt * 60)
363	 *   camera.x += (player.x - camera.x) * t
364	 *   camera.y += (player.y + CAMERA_OFFSET_Y - camera.y) * t
365	 *
366	 * @param {number} dt Delta-time in seconds
367	 */
368	R.updateCamera = function (dt) {
369	  var player = R.player;
370	  if (!player) return;
371	
372	  var cam    = R.camera;
373	  var smooth = R.CONFIG.CAMERA_SMOOTH;
374	  var offY   = R.CONFIG.CAMERA_OFFSET_Y;
375	
376	  // Frame-rate-independent lerp factor
377	  var t = 1 - Math.pow(1 - smooth, dt * 60);
378	
379	  // Snap on first frame (camera not yet positioned)
380	  if (cam.x === undefined || cam.y === undefined) {
381	    cam.x = player.x;
382	    cam.y = player.y + offY;
383	    return;
384	  }
385	
386	  cam.x += (player.x - cam.x) * t;
387	  cam.y += (player.y + offY - cam.y) * t;
388	};
