390	// ---------------------------------------------------------------------------
391	// Math utilities
392	// ---------------------------------------------------------------------------
393	
394	/**
395	 * Linear interpolation between a and b.
396	 * @param {number} a Start value
397	 * @param {number} b End value
398	 * @param {number} t Interpolation factor [0, 1]
399	 * @returns {number} Interpolated value
400	 */
401	R.lerp = function (a, b, t) {
402	  return a + (b - a) * t;
403	};
404	
405	/**
406	 * Clamp a value between lo and hi (inclusive).
407	 * @param {number} v  Value to clamp
408	 * @param {number} lo Lower bound
409	 * @param {number} hi Upper bound
410	 * @returns {number} Clamped value
411	 */
412	R.clamp = function (v, lo, hi) {
413	  return v < lo ? lo : v > hi ? hi : v;
414	};
415	
416	/**
417	 * Euclidean distance between two 2D points.
418	 * @param {number} x1 First point x
419	 * @param {number} y1 First point y
420	 * @param {number} x2 Second point x
421	 * @param {number} y2 Second point y
422	 * @returns {number} Distance
423	 */
424	R.dist = function (x1, y1, x2, y2) {
425	  var dx = x2 - x1;
426	  var dy = y2 - y1;
427	  return Math.sqrt(dx * dx + dy * dy);
428	};
429	
430	/**
431	 * Random float in [min, max).
432	 * @param {number} min Lower bound (inclusive)
433	 * @param {number} max Upper bound (exclusive)
434	 * @returns {number} Random value
435	 */
436	R.randomRange = function (min, max) {
437	  return min + Math.random() * (max - min);
438	};
