9	
10	R.input = R.input || {};
11	R.input.throttle = R.input.throttle ?? 0;
12	R.input.brake    = R.input.brake    ?? 0;
13	R.input.steer    = R.input.steer    ?? 0;
14	R.input.boost    = R.input.boost    ?? 0;
15	R.input.confirm  = R.input.confirm  ?? false;
16	R.input.pause    = R.input.pause    ?? false;
