18	// ---------------------------------------------------------------------------
19	// Internal key-state tracker — holds key down state for continuous actions
20	// ---------------------------------------------------------------------------
21	
22	const _keysDown = {};        // e.code → true/false
23	const _gameKeys = new Set(); // keys we care about (for fast lookup)
24	let   _touchActive = false;  // whether a touch is currently held
25	let   _touchStartX  = 0;
26	let   _touchStartY  = 0;
27	let   _touchStartTime = 0;
28	let   _touchCurrentX = 0;
29	let   _touchCurrentY = 0;
30	let   _touchMoved   = false; // has the finger moved beyond a tap threshold
31	let   _edgeTriggeredConfirm = false;
32	let   _edgeTriggeredPause   = false;
33	let   _gamepadIndex   = -1;  // detected gamepad index, -1 if none
34	let   _gamepadActive  = false;
35	
36	// Tap / swipe thresholds (in px)
37	const TAP_DISTANCE    = 30;  // max movement to count as tap
38	const SWIPE_DISTANCE  = 60;  // min movement to count as swipe
39	const TAP_MAX_TIME    = 300; // ms — max duration for tap
40	
41	// Game keys we intercept with preventDefault
42	const GAME_KEY_CODES = [
43	  'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
44	  'KeyW', 'KeyA', 'KeyS', 'KeyD',
45	  'ShiftLeft', 'ShiftRight', 'Space',
46	  'Enter', 'Escape', 'KeyP'
