52	// ---------------------------------------------------------------------------
53	// Keyboard state → R.input mapping (called each frame)
54	// ---------------------------------------------------------------------------
55	
56	function _syncKeyboardState() {
57	  // Steering — left takes priority over right when both held
58	  const left  = _keysDown['ArrowLeft']  || _keysDown['KeyA'] || false;
59	  const right = _keysDown['ArrowRight'] || _keysDown['KeyD'] || false;
60	  if (left && !right) {
61	    R.input.steer = -1;
62	  } else if (right && !left) {
63	    R.input.steer = 1;
64	  } else if (left && right) {
65	    R.input.steer = 0; // both held → cancel (rare)
66	  } else {
67	    R.input.steer = 0;
68	  }
69	
70	  // Throttle
71	  R.input.throttle = (_keysDown['ArrowUp'] || _keysDown['KeyW']) ? 1 : 0;
72	
73	  // Brake
74	  R.input.brake = (_keysDown['ArrowDown'] || _keysDown['KeyS']) ? 1 : 0;
75	
76	  // Boost
77	  R.input.boost = (_keysDown['ShiftLeft'] || _keysDown['ShiftRight'] || _keysDown['Space']) ? 1 : 0;
78	}
79	
80	// ---------------------------------------------------------------------------
81	// Touch state → R.input mapping (called each frame)
82	// ---------------------------------------------------------------------------
83	
84	function _syncTouchState() {
85	  if (!_touchActive) {
86	    // No finger down — clear touch-driven input unless keyboard is handling it
87	    return;
88	  }
89	  if (!_touchMoved) {
90	    // Finger hasn't moved enough for a swipe — no steering/throttle/brake yet
91	    return;
92	  }
93	
94	  const dx = _touchCurrentX - _touchStartX;
95	  const dy = _touchCurrentY - _touchStartY;
96	  const absDx = Math.abs(dx);
97	  const absDy = Math.abs(dy);
98	
99	  // Only override if touch actually provides meaningful input
100	  if (absDx < TAP_DISTANCE && absDy < TAP_DISTANCE) return;
101	
102	  // Steer: horizontal position on screen
103	  const halfW = R.canvas.width * 0.5;
104	  if (_touchCurrentX < halfW - 30) {
105	    // Left half → steer left (proportional)
106	    const zone = halfW - 30;
107	    R.input.steer = -Math.min(1, (zone - _touchCurrentX) / zone);
108	  } else if (_touchCurrentX > halfW + 30) {
109	    // Right half → steer right (proportional)
110	    const zone = halfW - 30;
111	    R.input.steer = Math.min(1, (_touchCurrentX - halfW - 30) / zone);
112	  }
113	
114	  // Swipe up → throttle, swipe down → brake (dominant vertical direction)
115	  if (absDy > absDx && absDy > SWIPE_DISTANCE) {
116	    if (dy < 0) {
117	      R.input.throttle = 1;
118	      R.input.brake    = 0;
119	    } else {
120	      R.input.brake    = 1;
121	      R.input.throttle = 0;
122	    }
123	  }
124	}
125	
126	// ---------------------------------------------------------------------------
127	// Gamepad state → R.input mapping (called each frame when gamepad is active)
128	// ---------------------------------------------------------------------------
129	
130	function _syncGamepadState() {
131	  if (!_gamepadActive || _gamepadIndex < 0) return;
132	
133	  const gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
134	  const gp = gamepads[_gamepadIndex];
135	  if (!gp) {
136	    _gamepadActive = false;
137	    _gamepadIndex = -1;
138	    return;
139	  }
140	
141	  // Left stick horizontal → steering (axis 0)
142	  // Apply a small deadzone to avoid drift
143	  const rawSteer = gp.axes[0] || 0;
144	  if (Math.abs(rawSteer) < 0.15) {
145	    R.input.steer = 0;
146	  } else {
147	    R.input.steer = Math.max(-1, Math.min(1, rawSteer));
148	  }
149	
150	  // Right trigger → throttle (axis 5 on standard mapping, 0..1)
151	  // Left trigger → brake (axis 4 on standard mapping, 0..1)
152	  // Some controllers map triggers to buttons 6/7 — we handle both
153	  if (gp.buttons[7] && typeof gp.buttons[7].value === 'number') {
154	    R.input.throttle = gp.buttons[7].value; // right trigger as button
155	  } else {
156	    R.input.throttle = (gp.axes[5] !== undefined) ? (gp.axes[5] + 1) * 0.5 : 0;
157	  }
158	  if (gp.buttons[6] && typeof gp.buttons[6].value === 'number') {
159	    R.input.brake = gp.buttons[6].value; // left trigger as button
160	  } else {
161	    R.input.brake = (gp.axes[4] !== undefined) ? (gp.axes[4] + 1) * 0.5 : 0;
162	  }
163	
164	  // A button (index 0) → boost
165	  R.input.boost = gp.buttons[0] && gp.buttons[0].pressed ? 1 : 0;
166	
167	  // Start button (index 9) → pause (edge-triggered)
168	  if (gp.buttons[9] && gp.buttons[9].pressed) {
169	    _edgeTriggeredPause = true;
170	  }
171	
172	  // Confirm via A button or Start (edge-triggered in updateInput)
173	  if (gp.buttons[0] && gp.buttons[0].pressed) {
174	    _edgeTriggeredConfirm = true;
175	  }
176	}
