178	// ---------------------------------------------------------------------------
179	// Keyboard event handlers
180	// ---------------------------------------------------------------------------
181	
182	function _onKeyDown(e) {
183	  if (!_gameKeys.has(e.code)) return; // not a game key — ignore
184	
185	  e.preventDefault(); // prevent scrolling / default browser action
186	
187	  // Edge-triggered actions (set flag once per press)
188	  if (e.code === 'Enter') {
189	    _edgeTriggeredConfirm = true;
190	    return;
191	  }
192	  if (e.code === 'Escape' || e.code === 'KeyP') {
193	    _edgeTriggeredPause = true;
194	    return;
195	  }
196	
197	  // Continuous actions — just track key down
198	  _keysDown[e.code] = true;
199	}
200	
201	function _onKeyUp(e) {
202	  if (!_gameKeys.has(e.code)) return;
203	
204	  e.preventDefault();
205	
206	  // Edge-triggered keys don't need up handling
207	  if (e.code === 'Enter' || e.code === 'Escape' || e.code === 'KeyP') return;
208	
209	  _keysDown[e.code] = false;
210	}
