212	// ---------------------------------------------------------------------------
213	// Touch event handlers
214	// ---------------------------------------------------------------------------
215	
216	function _onTouchStart(e) {
217	  e.preventDefault(); // prevent scrolling / pinch-zoom
218	
219	  const t = e.changedTouches[0];
220	  if (!t) return;
221	
222	  _touchActive    = true;
223	  _touchStartX    = t.clientX;
224	  _touchStartY    = t.clientY;
225	  _touchStartTime = Date.now();
226	  _touchCurrentX  = t.clientX;
227	  _touchCurrentY  = t.clientY;
228	  _touchMoved     = false;
229	
230	  // Set boost on touch start if it's a quick double-tap pattern (handled per-frame)
231	}
232	
233	function _onTouchMove(e) {
234	  e.preventDefault();
235	
236	  if (!_touchActive) return;
237	
238	  const t = e.changedTouches[0];
239	  if (!t) return;
240	
241	  const prevX = _touchCurrentX;
242	  const prevY = _touchCurrentY;
243	  _touchCurrentX = t.clientX;
244	  _touchCurrentY = t.clientY;
245	
246	  // Mark as moved if beyond tap threshold
247	  const totalDx = _touchCurrentX - _touchStartX;
248	  const totalDy = _touchCurrentY - _touchStartY;
249	  if (Math.abs(totalDx) > TAP_DISTANCE || Math.abs(totalDy) > TAP_DISTANCE) {
250	    _touchMoved = true;
251	  }
252	}
253	
254	function _onTouchEnd(e) {
255	  e.preventDefault();
256	
257	  if (!_touchActive) return;
258	
259	  const t = e.changedTouches[0];
260	  if (!t) { _resetTouch(); return; }
261	
262	  const endX = t.clientX;
263	  const endY = t.clientY;
264	  const dx   = endX - _touchStartX;
265	  const dy   = endY - _touchStartY;
266	  const dist = Math.sqrt(dx * dx + dy * dy);
267	  const elapsed = Date.now() - _touchStartTime;
268	
269	  // Tap detection: small movement + short duration
270	  if (dist < TAP_DISTANCE && elapsed < TAP_MAX_TIME) {
271	    // Tap center 40% of screen → confirm
272	    const centerX = R.canvas.width  * 0.5;
273	    const centerY = R.canvas.height * 0.5;
274	    const tapRadius = R.canvas.width * 0.2; // center 40% in width
275	    if (Math.abs(endX - centerX) < tapRadius && Math.abs(endY - centerY) < tapRadius) {
276	      _edgeTriggeredConfirm = true;
277	    }
278	  }
279	
280	  _resetTouch();
281	}
282	
283	function _onTouchCancel(e) {
284	  _resetTouch();
285	}
286	
287	function _resetTouch() {
288	  _touchActive    = false;
289	  _touchStartX    = 0;
290	  _touchStartY    = 0;
291	  _touchStartTime = 0;
292	  _touchCurrentX  = 0;
293	  _touchCurrentY  = 0;
294	  _touchMoved     = false;
295	}
