301	/**
302	 * R.initInput()
303	 * Bind all input event listeners (keyboard, touch).
304	 * Safe to call multiple times — removes previous listeners first.
305	 * Call once during game initialization.
306	 */
307	R.initInput = function () {
308	  // Remove old listeners if re-initializing
309	  if (R._inputListenersBound) {
310	    R.destroyInput();
311	  }
312	
313	  // Keyboard
314	  window.addEventListener('keydown', _onKeyDown, { passive: false });
315	  window.addEventListener('keyup',   _onKeyUp,   { passive: false });
316	
317	  // Touch (only if touch-capable, but safe to bind regardless)
318	  const cvs = R.canvas;
319	  if (cvs) {
320	    cvs.addEventListener('touchstart', _onTouchStart,  { passive: false });
321	    cvs.addEventListener('touchmove',  _onTouchMove,   { passive: false });
322	    cvs.addEventListener('touchend',   _onTouchEnd,    { passive: false });
323	    cvs.addEventListener('touchcancel',_onTouchCancel, { passive: false });
324	  }
325	
326	  // Visibility change — clear all keys if tab loses focus
327	  window.addEventListener('blur', function () {
328	    // Clear all held keys on blur to prevent stuck inputs
329	    for (var k in _keysDown) {
330	      if (_keysDown.hasOwnProperty(k)) _keysDown[k] = false;
331	    }
332	    _resetTouch();
333	    R.input.throttle = 0;
334	    R.input.brake    = 0;
335	    R.input.steer    = 0;
336	    R.input.boost    = 0;
337	  });
338	
339	  R._inputListenersBound = true;
340	};
341	
342	/**
343	 * R.destroyInput()
344	 * Remove all input event listeners. Call before shutdown or re-init.
345	 */
346	R.destroyInput = function () {
347	  window.removeEventListener('keydown', _onKeyDown);
348	  window.removeEventListener('keyup',   _onKeyUp);
349	
350	  const cvs = R.canvas;
351	  if (cvs) {
352	    cvs.removeEventListener('touchstart',  _onTouchStart);
353	    cvs.removeEventListener('touchmove',   _onTouchMove);
354	    cvs.removeEventListener('touchend',    _onTouchEnd);
355	    cvs.removeEventListener('touchcancel', _onTouchCancel);
356	  }
357	
358	  R._inputListenersBound = false;
359	};
