361	/**
362	 * R.updateInput()
363	 * Called every frame. Syncs raw input state to R.input and clears
364	 * edge-triggered flags that were consumed.
365	 */
366	R.updateInput = function () {
367	  // 1. Sync keyboard continuous state
368	  _syncKeyboardState();
369	
370	  // 2. Sync touch state
371	  _syncTouchState();
372	
373	  // 3. Sync gamepad (if active)
374	  if (_gamepadActive) {
375	    _syncGamepadState();
376	  }
377	
378	  // 4. Edge-triggered flags — transfer from internal to R.input
379	  //    These are set by event handlers and consumed once by the state machine.
380	  //    We do NOT reset them here — they persist until consumeConfirm/consumePause
381	  //    is called. But we must NOT double-set them either.
382	  if (_edgeTriggeredConfirm) {
383	    R.input.confirm = true;
384	    _edgeTriggeredConfirm = false;
385	  }
386	  if (_edgeTriggeredPause) {
387	    R.input.pause = true;
388	    _edgeTriggeredPause = false;
389	  }
390	};
