392	/**
393	 * R.consumeConfirm()
394	 * Called by the state machine after reading R.input.confirm.
395	 * Resets the flag so it fires only once per press.
396	 */
397	R.consumeConfirm = function () {
398	  R.input.confirm = false;
399	};
