414	/**
415	 * R.initGamepad()
416	 * Detect the first connected gamepad and begin polling.
417	 * Gamepad state is read each frame inside updateInput() via _syncGamepadState().
418	 * Re-checks for gamepad connection on every call (safe to call each frame
419	 * or on-demand).
420	 *
421	 * Mapping (standard):
422	 *   Left stick X  → steer
423	 *   Right trigger → throttle
424	 *   Left trigger  → brake
425	 *   A button      → boost
426	 *   Start button  → pause
427	 */
428	R.initGamepad = function () {
429	  // If we already have an active gamepad, verify it's still connected
430	  if (_gamepadActive && _gamepadIndex >= 0) {
431	    var gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
432	    if (gamepads[_gamepadIndex]) return; // still connected
433	    // Disconnected — fall through to re-detect
434	    _gamepadActive = false;
435	    _gamepadIndex = -1;
436	  }
437	
438	  // Detect first connected gamepad
439	  var gamepads = navigator.getGamepads ? navigator.getGamepads() : [];
440	  for (var i = 0; i < gamepads.length; i++) {
441	    if (gamepads[i] && gamepads[i].connected) {
442	      _gamepadIndex = i;
443	      _gamepadActive = true;
444	      return;
445	    }
446	  }
447	
448	  // No gamepad found
449	  _gamepadIndex = -1;
450	  _gamepadActive = false;
451	};
