80	/**
81	 * Normalise an angle to the range [-PI, PI].
82	 * @param {number} a Angle in radians
83	 * @returns {number} Normalised angle
84	 */
85	function _normAngle(a) {
86	  while (a >  Math.PI) a -= Math.PI * 2;
87	  while (a < -Math.PI) a += Math.PI * 2;
88	  return a;
89	}
90	
91	/**
92	 * Catmull-Rom spline interpolation between four 2D control points.
93	 * Produces a smooth curve passing through p1 and p2, guided by p0 and p3.
94	 * @param {{x:number,z:number}} p0 Previous control point
95	 * @param {{x:number,z:number}} p1 Start control point
96	 * @param {{x:number,z:number}} p2 End control point
97	 * @param {{x:number,z:number}} p3 Next control point
98	 * @param {number} t Interpolation factor [0, 1]
99	 * @returns {{x:number,z:number}} Interpolated point
100	 */
101	function _catmullRom(p0, p1, p2, p3, t) {
102	  var t2 = t * t;
103	  var t3 = t2 * t;
104	  return {
105	    x: 0.5 * (
106	      (2 * p1.x) +
107	      (-p0.x + p2.x) * t +
108	      (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 +
109	      (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3
110	    ),
111	    z: 0.5 * (
112	      (2 * p1.z) +
113	      (-p0.z + p2.z) * t +
114	      (2 * p0.z - 5 * p1.z + 4 * p2.z - p3.z) * t2 +
115	      (-p0.z + 3 * p1.z - 3 * p2.z + p3.z) * t3
116	    )
117	  };
118	}
119	
120	/**
121	 * Direction angle (radians) from point a to point b in the XZ plane.
122	 * Angle 0 = +Z direction; increases clockwise when viewed from above (+Y).
123	 * @param {{x:number,z:number}} a
124	 * @param {{x:number,z:number}} b
125	 * @returns {number} Angle in radians
126	 */
127	function _angleTo(a, b) {
128	  return Math.atan2(b.x - a.x, b.z - a.z);
129	}
130	
131	/**
132	 * Euclidean distance between two 2D points in XZ space.
133	 * @param {{x:number,z:number}} a
134	 * @param {{x:number,z:number}} b
135	 * @returns {number}
136	 */
137	function _distXZ(a, b) {
138	  var dx = a.x - b.x;
139	  var dz = a.z - b.z;
140	  return Math.sqrt(dx * dx + dz * dz);
141	}
142	
143	/**
144	 * Compute forward distance from camera to a segment, handling the closed-loop
145	 * wrap so that the shorter arc is always used.
146	 * @param {number} segDist Cumulative distance of the segment
147	 * @param {number} camDist Camera's cumulative track distance
148	 * @param {number} totalLen Total track length
149	 * @returns {number} Signed forward distance (positive = ahead, negative = behind)
150	 */
151	function _forwardDist(segDist, camDist, totalLen) {
152	  var dz = segDist - camDist;
153	  if (dz >  totalLen / 2) dz -= totalLen;
154	  if (dz < -totalLen / 2) dz += totalLen;
155	  return dz;
156	}
