158	/* ==========================================================================
159	   R.initTrack() — Generate a closed-loop racing circuit
160	   ========================================================================== */
161	
162	/**
163	 * Generates a closed-loop racing track using Catmull-Rom spline interpolation
164	 * through stochastically-placed control points on a distorted circle.
165	 *
166	 * Each segment stores:
167	 *   { worldX, worldY, worldZ, width, curvature, elevation, type, dist, angle }
168	 *
169	 * After generation populates:
170	 *   R.track.segments[], R.track.totalLength, R.track.startX, R.track.startZ,
171	 *   R.track.startAngle
172	 */
173	R.initTrack = function () {
174	  var cfg  = R.CONFIG;
175	  var nCP  = cfg.TRACK_CONTROL_POINTS;
176	  var nSeg = cfg.TRACK_SEGMENTS_PER_CP;
177	
178	  // ── Step 1: Generate control points on a distorted circle ───────────
179	  var cps = [];
180	  var baseR = cfg.TRACK_BASE_RADIUS;
181	  for (var i = 0; i < nCP; i++) {
182	    var angle = (i / nCP) * Math.PI * 2;
183	    var r = baseR
184	          + Math.sin(angle * 2) * cfg.TRACK_RADIUS_VAR1
185	          + Math.cos(angle * 3) * cfg.TRACK_RADIUS_VAR2
186	          + Math.sin(angle * 5) * cfg.TRACK_RADIUS_VAR3;
187	    // Random jitter (use seed if provided, otherwise Math.random)
188	    var jitter = cfg.TRACK_SEED != null
189	      ? (_pseudoRandom(i) - 0.5) * cfg.TRACK_RADIUS_JITTER * 2
190	      : (Math.random() - 0.5) * cfg.TRACK_RADIUS_JITTER * 2;
191	    // Apply jitter proportionally so the shape doesn't self-intersect
192	    var rFinal = r + jitter;
193	    if (rFinal < 300) rFinal = 300; // prevent collapsing to centre
194	    cps.push({ x: Math.cos(angle) * rFinal, z: Math.sin(angle) * rFinal });
195	  }
196	
197	  // ── Step 2: Interpolate segments via Catmull-Rom ────────────────────
198	  var samples  = []; // intermediate dense samples {x, z}
199	  var totalCP  = cps.length;
200	  for (var ci = 0; ci < totalCP; ci++) {
201	    var p0 = cps[(ci - 1 + totalCP) % totalCP];
202	    var p1 = cps[ci];
203	    var p2 = cps[(ci + 1) % totalCP];
204	    var p3 = cps[(ci + 2) % totalCP];
205	    for (var si = 0; si < nSeg; si++) {
206	      var t = si / nSeg;
207	      var pt = _catmullRom(p0, p1, p2, p3, t);
208	      samples.push(pt);
209	    }
210	  }
211	
212	  // ── Step 3: Build segment objects ───────────────────────────────────
213	  var segs    = [];
214	  var nSamples = samples.length;
215	  // Temporaries for curvature calculation
216	  var angles  = new Array(nSamples);
217	  var segDists = new Array(nSamples); // Euclidean distance between consecutive samples
218	
219	  // First pass: compute angles and segment lengths (distance between consecutive samples)
220	  for (var s = 0; s < nSamples; s++) {
221	    var curr  = samples[s];
222	    var next  = samples[(s + 1) % nSamples];
223	    var prev  = samples[(s - 1 + nSamples) % nSamples];
224	    segDists[s] = _distXZ(curr, next);
225	    // Smooth angle using central difference (wrapping)
226	    var anglePrev = _angleTo(prev, curr);
227	    var angleNext = _angleTo(curr, next);
228	    // Average the two half-angles for a smoother direction at this point
229	    angles[s] = _normAngle((anglePrev + angleNext) / 2);
230	  }
231	
232	  // Compute curvature as angle change per unit distance
233	  var curvatures = new Array(nSamples);
234	  // Find maximum absolute curvature for width-ramping
235	  var maxAbsCurv = 0;
236	  for (var s2 = 0; s2 < nSamples; s2++) {
237	    var aCurr  = angles[s2];
238	    var aNext  = angles[(s2 + 1) % nSamples];
239	    var deltaA = _normAngle(aNext - aCurr);
240	    var d      = segDists[s2];
241	    curvatures[s2] = d > 0.01 ? deltaA / d : 0;
242	    var ac = Math.abs(curvatures[s2]);
243	    if (ac > maxAbsCurv) maxAbsCurv = ac;
244	  }
245	  // Guard against zero max curvature (perfect circle)
246	  if (maxAbsCurv < 0.0001) maxAbsCurv = 0.0001;
247	
248	  // Cumulative distance
249	  var cumDist = 0;
250	  for (var s3 = 0; s3 < nSamples; s3++) {
251	    var absCurv      = Math.abs(curvatures[s3]);
252	    var widthFraction = absCurv / maxAbsCurv; // 0 on straights, 1 on tightest curve
253	    if (widthFraction > 1) widthFraction = 1;
254	
255	    var roadW = cfg.ROAD_WIDTH + (cfg.ROAD_WIDTH_MIN - cfg.ROAD_WIDTH) * widthFraction;
256	
257	    // Classification
258	    var stype = 'straight';
259	    if (absCurv > maxAbsCurv * 0.15) stype = 'curve';
260	    if (absCurv > maxAbsCurv * 0.55) stype = 'tight_curve';
261	
262	    // Elevation
263	    var d   = cumDist;
264	    var elev = Math.sin(d * cfg.HILL_FREQ_A)          * cfg.HILL_AMPLITUDE_A
265	             + Math.sin(d * cfg.HILL_FREQ_B + cfg.HILL_PHASE_B) * cfg.HILL_AMPLITUDE_B;
266	
267	    // Check for hill
268	    if (cfg.HILL_AMPLITUDE_A > 0 || cfg.HILL_AMPLITUDE_B > 0) {
269	      var nextD  = cumDist + segDists[s3];
270	      var nextEl = Math.sin(nextD * cfg.HILL_FREQ_A)          * cfg.HILL_AMPLITUDE_A
271	                 + Math.sin(nextD * cfg.HILL_FREQ_B + cfg.HILL_PHASE_B) * cfg.HILL_AMPLITUDE_B;
272	      if (Math.abs(nextEl - elev) / Math.max(segDists[s3], 1) > 0.015) {
273	        stype = 'hill';
274	      }
275	    }
276	
277	    segs.push({
278	      worldX:    samples[s3].x,
279	      worldY:    elev,
280	      worldZ:    samples[s3].z,
281	      width:     roadW,
282	      curvature: curvatures[s3],
283	      elevation: elev,
284	      type:      stype,
285	      dist:      cumDist,
286	      angle:     angles[s3],
287	      segDist:   segDists[s3]  // distance to next segment
288	    });
289	
290	    cumDist += segDists[s3];
291	  }
292	
293	  // ── Step 4: Store to R.track ────────────────────────────────────────
294	  R.track = {
295	    segments:    segs,
296	    totalLaps:   cfg.TOTAL_LAPS,
297	    totalLength: cumDist,
298	    startX:      segs[0].worldX,
299	    startY:      segs[0].worldY,
300	    startZ:      segs[0].worldZ,
301	    startAngle:  segs[0].angle,
302	    checkpointCount: cfg.LAP_CHECKPOINT_COUNT || 4
303	  };
304	
305	  // Distribute checkpoints evenly
306	  R.track.checkpoints = [];
307	  var cpCount = R.track.checkpointCount;
308	  for (var c = 0; c < cpCount; c++) {
309	    var cpDist = (c / cpCount) * R.track.totalLength;
310	    var cpPos  = R.getTrackPosition(cpDist);
311	    R.track.checkpoints.push({
312	      dist: cpDist,
313	      x:    cpPos.x,
314	      z:    cpPos.z,
315	      width: cpPos.width
316	    });
317	  }
318	
319	  // ── Step 5: Ensure camera Z is initialised ──────────────────────────
320	  if (R.camera) {
321	    R.camera.worldZ = segs[0].worldZ;
322	    R.camera.trackDist = 0;
323	  }
324	};
