326	/**
327	 * Simple deterministic pseudo-random generator for seeded tracks.
328	 * Returns a value in [0, 1) based on index.
329	 * @param {number} idx Integer index
330	 * @returns {number} Pseudo-random value
331	 */
332	function _pseudoRandom(idx) {
333	  var x = Math.sin(idx * 127.1 + 311.7) * 43758.5453;
334	  return x - Math.floor(x);
335	}
