337	/* ==========================================================================
338	   R.getTrackPosition(worldZ) — Interpolated position lookup by distance
339	   ========================================================================== */
340	
341	/**
342	 * Given a cumulative distance along the track, returns the interpolated
343	 * position and properties at that point. Wraps around for closed circuit.
344	 *
345	 * @param {number} dist Cumulative distance (wraps modulo totalLength)
346	 * @returns {{x:number, y:number, z:number, angle:number, curvature:number, width:number, dist:number, index:number}}
347	 */
348	R.getTrackPosition = function (dist) {
349	  var segs   = R.track.segments;
350	  var total  = R.track.totalLength;
351	  var n      = segs.length;
352	
353	  // Wrap distance
354	  var d = dist % total;
355	  if (d < 0) d += total;
356	
357	  // Binary search for the segment just before d
358	  var lo = 0;
359	  var hi = n - 1;
360	  while (lo < hi) {
361	    var mid = (lo + hi + 1) >> 1;
362	    if (segs[mid].dist <= d) {
363	      lo = mid;
364	    } else {
365	      hi = mid - 1;
366	    }
367	  }
368	
369	  var idx = lo;
370	  var seg = segs[idx];
371	  var nextIdx = (idx + 1) % n;
372	  var nextSeg = segs[nextIdx];
373	
374	  // Handle wrap: the next segment's dist may be less than current if we wrapped
375	  var segEndDist = nextSeg.dist;
376	  if (segEndDist <= seg.dist) segEndDist += total; // wrapped
377	
378	  var t = 0;
379	  var span = segEndDist - seg.dist;
380	  if (span > 0.0001) {
381	    var localD = d;
382	    if (localD < seg.dist) localD += total;
383	    t = (localD - seg.dist) / span;
384	  }
385	  if (t < 0) t = 0;
386	  if (t > 1) t = 1;
387	
388	  return {
389	    x:          R.lerp(seg.worldX, nextSeg.worldX, t),
390	    y:          R.lerp(seg.worldY, nextSeg.worldY, t),
391	    z:          R.lerp(seg.worldZ, nextSeg.worldZ, t),
392	    angle:      _normAngle(R.lerp(seg.angle, nextSeg.angle, t)),
393	    curvature:  R.lerp(seg.curvature, nextSeg.curvature, t),
394	    width:      R.lerp(seg.width, nextSeg.width, t),
395	    dist:       d,
396	    index:      idx
397	  };
398	};
