400	/* ==========================================================================
401	   R.isOnTrack(worldX, worldZ) — Collision detection
402	   ========================================================================== */
403	
404	/**
405	 * Checks whether a given world position (X, Z) is on the track surface.
406	 * Finds the nearest segment by track distance, computes lateral offset
407	 * from the road centre-line, and compares to the segment's half-width.
408	 *
409	 * @param {number} wx World X coordinate to test
410	 * @param {number} wz World Z coordinate to test
411	 * @returns {{onTrack:boolean, distFromCenter:number, segmentIndex:number, halfWidth:number}}
412	 */
413	R.isOnTrack = function (wx, wz) {
414	  var segs  = R.track.segments;
415	  var n     = segs.length;
416	  var total = R.track.totalLength;
417	
418	  // Spiral search: start from last known nearest segment and expand outward
419	  // Fall back to full scan on first call
420	  var bestIdx    = -1;
421	  var bestDist2  = Infinity;
422	
423	  // Scan all segments — 200-240 is cheap enough per call
424	  for (var i = 0; i < n; i++) {
425	    var seg = segs[i];
426	    var dx  = seg.worldX - wx;
427	    var dz  = seg.worldZ - wz;
428	    var d2  = dx * dx + dz * dz;
429	    if (d2 < bestDist2) {
430	      bestDist2 = d2;
431	      bestIdx   = i;
432	    }
433	  }
434	
435	  if (bestIdx < 0) {
436	    return { onTrack: false, distFromCenter: Infinity, segmentIndex: -1, halfWidth: 0 };
437	  }
438	
439	  var seg       = segs[bestIdx];
440	  var segAngle  = seg.angle;
441	
442	  // Compute lateral (perpendicular) distance from road centre-line
443	  // Vector from segment centre to test point
444	  var dx = wx - seg.worldX;
445	  var dz = wz - seg.worldZ;
446	  // Project onto perpendicular direction: left = (cos(angle), -sin(angle))
447	  var lateralDist = dx * Math.cos(segAngle) - dz * Math.sin(segAngle);
448	  // Take absolute value for distance from centre
449	  var absLat = Math.abs(lateralDist);
450	  var halfW  = seg.width / 2;
451	
452	  return {
453	    onTrack:        absLat <= halfW,
454	    distFromCenter: absLat,
455	    segmentIndex:   bestIdx,
456	    halfWidth:      halfW
457	  };
458	};
