460	/* ==========================================================================
461	   R.worldToScreen(wx, wy, wz) — World-to-screen projection
462	   ========================================================================== */
463	
464	/**
465	 * Converts world coordinates to screen coordinates using perspective projection.
466	 * wz controls depth-based scaling: larger wz = farther away = smaller on screen.
467	 *
468	 * The camera position (R.camera.x, R.camera.y) defines the screen centre.
469	 * If R.camera.worldZ is set, wz is treated as relative to the camera's Z
470	 * (for proper perspective during racing). Otherwise wz is used as-is.
471	 *
472	 * @param {number} wx World X coordinate
473	 * @param {number} wy World Y coordinate (elevation)
474	 * @param {number} wz World Z coordinate (depth / forward distance)
475	 * @returns {{x:number, y:number, scale:number}}
476	 */
477	R.worldToScreen = function (wx, wy, wz) {
478	  var cam    = R.camera;
479	  var camZ   = (cam.worldZ !== undefined) ? cam.worldZ : 0;
480	  var relZ   = wz - camZ;
481	  var coeff  = R.CONFIG.PERSPECTIVE_COEFF;
482	
483	  // Use absolute value for scale denominator so things behind camera don't
484	  // flip, but preserve sign in relZ for screen-Y computation
485	  var absRelZ = relZ < 0 ? -relZ : relZ;
486	  var scale = cam.zoom / (1 + absRelZ * coeff);
487	
488	  var sx = R.CONFIG.CANVAS_WIDTH  / 2 + (wx - cam.x) * scale;
489	  var sy = R.CONFIG.CANVAS_HEIGHT / 2 + (wy - cam.y) * scale;
490	
491	  return { x: sx, y: sy, scale: scale };
492	};
