494	/* ==========================================================================
495	   R.renderSky(ctx) — Sky gradient and horizon
496	   ========================================================================== */
497	
498	/**
499	 * Draws a full-screen sky gradient from a darker top colour to a lighter
500	 * horizon colour, followed by a narrow ground/horizon strip.
501	 *
502	 * Operates in screen space: saves the current transform, resets to identity,
503	 * draws the sky, and restores.
504	 *
505	 * @param {CanvasRenderingContext2D} ctx
506	 */
507	R.renderSky = function (ctx) {
508	  var W = R.CONFIG.CANVAS_WIDTH;
509	  var H = R.CONFIG.CANVAS_HEIGHT;
510	  var horizonY = R.CONFIG.HORIZON_Y || 200;
511	
512	  ctx.save();
513	  ctx.setTransform(1, 0, 0, 1, 0, 0);
514	
515	  // ── Sky gradient ─────────────────────────────────────────────────────
516	  var skyTop    = R.CONFIG.SKY_TOP_COLOR    || '#1a1a2e';
517	  var skyBottom = R.CONFIG.SKY_BOTTOM_COLOR || '#87CEEB';
518	  var grad = ctx.createLinearGradient(0, 0, 0, horizonY + 40);
519	  grad.addColorStop(0,    skyTop);
520	  grad.addColorStop(0.65, '#4a6fa5');
521	  grad.addColorStop(1,    skyBottom);
522	  ctx.fillStyle = grad;
523	  ctx.fillRect(0, 0, W, horizonY + 40);
524	
525	  // ── Horizon glow ─────────────────────────────────────────────────────
526	  var glowGrad = ctx.createLinearGradient(0, horizonY - 20, 0, horizonY + 40);
527	  glowGrad.addColorStop(0, 'rgba(255,255,255,0)');
528	  glowGrad.addColorStop(0.5, 'rgba(255,255,255,0.15)');
529	  glowGrad.addColorStop(1, 'rgba(255,255,255,0)');
530	  ctx.fillStyle = glowGrad;
531	  ctx.fillRect(0, horizonY - 20, W, 60);
532	
533	  // ── Ground strip below horizon ───────────────────────────────────────
534	  var groundGrad = ctx.createLinearGradient(0, horizonY + 20, 0, H);
535	  groundGrad.addColorStop(0,    '#6b8c5c');  // distant green-brown
536	  groundGrad.addColorStop(0.15, '#5a7a4a');
537	  groundGrad.addColorStop(0.5,  R.CONFIG.TRACK_BG_COLOR || '#3a5a2c');
538	  groundGrad.addColorStop(1,    '#2a4a1c');
539	  ctx.fillStyle = groundGrad;
540	  ctx.fillRect(0, horizonY + 20, W, H - horizonY - 20);
541	
542	  // ── Horizon line ─────────────────────────────────────────────────────
543	  ctx.strokeStyle = 'rgba(255,255,255,0.25)';
544	  ctx.lineWidth   = 1;
545	  ctx.beginPath();
546	  ctx.moveTo(0, horizonY + 20);
547	  ctx.lineTo(W, horizonY + 20);
548	  ctx.stroke();
549	
550	  ctx.restore();
551	};
