553	/* ==========================================================================
554	   R.renderTrack(ctx) — Main track rendering
555	   ========================================================================== */
556	
557	/**
558	 * Renders the racing track with pseudo-3D perspective.
559	 *
560	 * Drawing order: back-to-front (far segments first) for correct occlusion.
561	 * For each consecutive segment pair, draws:
562	 *   1. Road surface trapezoid
563	 *   2. Edge lines (solid white)
564	 *   3. Centre dashed lane markings
565	 *   4. Red/white curbs on tight curves
566	 *
567	 * Operates in screen space: saves the camera transform, resets to identity,
568	 * does perspective projection via worldToScreen, then restores.
569	 *
570	 * @param {CanvasRenderingContext2D} ctx
571	 */
572	R.renderTrack = function (ctx) {
573	  var segs   = R.track.segments;
574	  var n      = segs.length;
575	  var total  = R.track.totalLength;
576	  var cam    = R.camera;
577	  var cfg    = R.CONFIG;
578	  var W      = cfg.CANVAS_WIDTH;
579	  var H      = cfg.CANVAS_HEIGHT;
580	
581	  if (!n) return;
582	
583	  // ── Update camera track position from player ────────────────────────
584	  if (R.player) {
585	    cam.worldZ = R.player.z;
586	    // Compute camera's approximate track distance for forward-distance calc
587	    var playerSegIdx = 0;
588	    var bestD2 = Infinity;
589	    for (var pidx = 0; pidx < n; pidx++) {
590	      var pseg = segs[pidx];
591	      var pdx  = pseg.worldX - R.player.x;
592	      var pdz  = pseg.worldZ - R.player.z;
593	      var pd2  = pdx * pdx + pdz * pdz;
594	      if (pd2 < bestD2) { bestD2 = pd2; playerSegIdx = pidx; }
595	    }
596	    cam.trackDist = segs[playerSegIdx].dist;
597	  } else {
598	    cam.worldZ    = cam.worldZ || 0;
599	    cam.trackDist = cam.trackDist || 0;
600	  }
601	
602	  // ── Save canvas state, reset to identity for screen-space drawing ───
603	  ctx.save();
604	  ctx.setTransform(1, 0, 0, 1, 0, 0);
605	
606	  var renderDist = cfg.RENDER_DISTANCE;
607	  var horY       = cfg.HORIZON_Y;
608	  var camDist    = cam.trackDist;
609	
610	  // ── Collect visible segments with computed screen positions ──────────
611	  var visible = [];
612	  for (var i = 0; i < n; i++) {
613	    var seg = segs[i];
614	    var dz  = _forwardDist(seg.dist, camDist, total);
615	
616	    // Cull segments too far behind or ahead
617	    if (dz < -renderDist || dz > renderDist * 1.4) continue;
618	
619	    // Compute screen position via perspective projection
620	    var proj = _projectSegment(seg, dz, cam, cfg, W, H);
621	
622	    // Cull segments off-screen
623	    if (proj.y > H + 100 || proj.y < -100) continue;
624	
625	    visible.push({
626	      index: i,
627	      seg:   seg,
628	      dz:    dz,
629	      sx:    proj.x,
630	      sy:    proj.y,
631	      scale: proj.scale,
632	      lx:    proj.lx,
633	      rx:    proj.rx
634	    });
635	  }
636	
637	  if (visible.length === 0) { ctx.restore(); return; }
638	
639	  // Sort far-to-near (back-to-front) for painter's algorithm
640	  visible.sort(function (a, b) { return b.dz - a.dz; });
641	
642	  // ── Draw terrain / grass beneath the road ─────────────────────────────
643	  // (A solid fill from horizon down, over which the road trapezoids sit)
644	  ctx.fillStyle = cfg.TRACK_BG_COLOR || '#3a5a2c';
645	  ctx.fillRect(0, horY + 20, W, H - horY - 20);
646	
647	  // ── Build a set of visible indices for fast pair-check ────────────────
648	  var visSet = {};
649	  for (var vi = 0; vi < visible.length; vi++) {
650	    visSet[visible[vi].index] = vi;
651	  }
652	
653	  // ── Track drawn-pair set to avoid double-drawing ─────────────────────
654	  var drawnPairs = {};
655	
656	  // ── Pass 1: Road surface trapezoids ──────────────────────────────────
657	  for (var vi2 = 0; vi2 < visible.length; vi2++) {
658	    var cur  = visible[vi2];
659	    var idx  = cur.index;
660	    var nextIdx = (idx + 1) % n;
661	
662	    // Only draw if the next segment is also visible
663	    if (!(nextIdx in visSet)) continue;
664	
665	    // Avoid double-draw: each pair is drawn when processing the farther segment
666	    var pairKey = idx + '_' + nextIdx;
667	    if (drawnPairs[pairKey]) continue;
668	    drawnPairs[pairKey] = true;
669	
670	    var nxtVis = visible[visSet[nextIdx]];
671	    // Use the stored screen coordinates
672	    var clx = cur.lx, crx = cur.rx, csy = cur.sy;
673	    var nlx = nxtVis.lx, nrx = nxtVis.rx, nsy = nxtVis.sy;
674	
675	    // ── Road surface colour (slight variation per segment) ─────────────
676	    var baseColor = cfg.ROAD_COLOR || '#555';
677	    var colorVar  = ((idx * 17) & 7) - 3; // pseudo-random ±3 per segment
678	    var rgb = _adjustBrightness(baseColor, colorVar);
679	    ctx.fillStyle = rgb;
680	
681	    // Draw the trapezoid: (clx,csy) → (crx,csy) → (nrx,nsy) → (nlx,nsy)
682	    ctx.beginPath();
683	    ctx.moveTo(clx, csy);
684	    ctx.lineTo(crx, csy);
685	    ctx.lineTo(nrx, nsy);
686	    ctx.lineTo(nlx, nsy);
687	    ctx.closePath();
688	    ctx.fill();
689	
690	    // ── Edge lines ─────────────────────────────────────────────────────
691	    ctx.strokeStyle = cfg.LINE_COLOR || '#fff';
692	    ctx.lineWidth   = Math.max(cur.scale * 2.5, 1);
693	    ctx.beginPath();
694	    ctx.moveTo(clx, csy);
695	    ctx.lineTo(nlx, nsy);
696	    ctx.stroke();
697	
698	    ctx.beginPath();
699	    ctx.moveTo(crx, csy);
700	    ctx.lineTo(nrx, nsy);
701	    ctx.stroke();
702	
703	    // ── Curbs on tight curves ──────────────────────────────────────────
704	    if (Math.abs(cur.seg.curvature) > (cfg.CURB_CURVATURE_THRESH || 0.0012)) {
705	      var curbW  = cfg.RUMBLE_WIDTH || 6;
706	      var curbScale = Math.max(cur.scale * curbW, 1);
707	      var isOuterRight = cur.seg.curvature < 0; // negative curvature = right turn, outer = left
708	
709	      if (isOuterRight) {
710	        // Outer curb is on the left edge (outside of a right turn)
711	        _drawCurbSegment(ctx, clx, csy, nlx, nsy, curbScale, cur.dz, cfg);
712	      } else {
713	        // Outer curb is on the right edge (outside of a left turn)
714	        _drawCurbSegment(ctx, crx, csy, nrx, nsy, curbScale, cur.dz, cfg);
715	      }
716	    }
717	  }
718	
719	  // ── Pass 2: Centre lane markings ─────────────────────────────────────
720	  _drawLaneMarkings(ctx, visible, cfg, total);
721	
722	  ctx.restore();
723	};
724	
725	/* ==========================================================================
726	   RENDERING HELPERS
727	   ========================================================================== */
728	
729	/**
730	 * Projects a single track segment to screen coordinates.
731	 * Returns the centre screen position plus left/right edge positions.
732	 *
733	 * @param {Object} seg Segment object
734	 * @param {number} dz  Forward distance from camera (signed)
735	 * @param {Object} cam Camera object
736	 * @param {Object} cfg CONFIG object
737	 * @param {number} W   Canvas width
738	 * @param {number} H   Canvas height
739	 * @returns {{x:number, y:number, scale:number, lx:number, rx:number}}
740	 */
741	function _projectSegment(seg, dz, cam, cfg, W, H) {
742	  var coeff    = cfg.PERSPECTIVE_COEFF;
743	  var absDz    = dz < 0 ? -dz : dz;
744	  var scale    = cam.zoom / (1 + absDz * coeff);
745	
746	  // Screen centre X — horizontal displacement from camera
747	  var dx   = seg.worldX - cam.x;
748	  var sx   = W / 2 + dx * scale;
749	
750	  // Screen centre Y — incorporates elevation and forward distance
751	  // dz > 0 (ahead) → smaller sy (higher on screen, toward horizon)
752	  // dz < 0 (behind) → larger sy (lower on screen)
753	  var dy   = seg.worldY - cam.y;
754	  var sy   = H / 2 + dy * scale - dz * cfg.ROAD_V_OFFSET * scale;
755	
756	  // Left/right edge screen positions
757	  var halfW = seg.width / 2;
758	  // Left edge: offset perpendicular to segment direction
759	  var cosA = Math.cos(seg.angle);
760	  var sinA = Math.sin(seg.angle);
761	  // Left = direction * halfWidth rotated 90° counter-clockwise
762	  var leftDx  = dx + cosA * halfW;
763	  var rightDx = dx - cosA * halfW;
764	  // Screen X for edges (same Y as centre, same scale)
765	  var lx = W / 2 + leftDx  * scale;
766	  var rx = W / 2 + rightDx * scale;
767	
768	  return { x: sx, y: sy, scale: scale, lx: lx, rx: rx };
769	}
770	
771	/**
772	 * Draws a single curb stripe segment between two screen-space points.
773	 * Alternates red/white based on distance along the track.
774	 *
775	 * @param {CanvasRenderingContext2D} ctx
776	 * @param {number} x1  Start X on screen
777	 * @param {number} y1  Start Y on screen
778	 * @param {number} x2  End X on screen
779	 * @param {number} y2  End Y on screen
780	 * @param {number} w   Curb width in screen pixels
781	 * @param {number} dz  Forward distance (for stripe index)
782	 * @param {Object} cfg CONFIG
783	 */
784	function _drawCurbSegment(ctx, x1, y1, x2, y2, w, dz, cfg) {
785	  var stripeLen = 25; // world units per stripe
786	  var idx = Math.floor(Math.abs(dz) / stripeLen);
787	  var color = (idx % 2 === 0) ? (cfg.RUMBLE_COLOR_A || '#ff0000')
788	                              : (cfg.RUMBLE_COLOR_B || '#ffffff');
789	  ctx.strokeStyle = color;
790	  ctx.lineWidth   = Math.max(w, 1.5);
791	  ctx.beginPath();
792	  ctx.moveTo(x1, y1);
793	  ctx.lineTo(x2, y2);
794	  ctx.stroke();
795	}
796	
797	/**
798	 * Draws dashed centre-line markings across visible road segments.
799	 *
800	 * @param {CanvasRenderingContext2D} ctx
801	 * @param {Array}  visible Array of visible segment entries (sorted far→near)
802	 * @param {Object} cfg     CONFIG
803	 * @param {number} total   Total track length
804	 */
805	function _drawLaneMarkings(ctx, visible, cfg, total) {
806	  var dashLen  = cfg.LANE_MARKER_DASH || 40;
807	  var gapLen   = cfg.LANE_MARKER_GAP  || 30;
808	  var cycleLen = dashLen + gapLen;
809	
810	  ctx.strokeStyle = cfg.LANE_MARKER_COLOR || '#ccc';
811	
812	  for (var vi = 0; vi < visible.length; vi++) {
813	    var cur = visible[vi];
814	    var seg = cur.seg;
815	    var d   = seg.dist;
816	
817	    // Determine if this segment is in a dash or gap
818	    var cyclePos = d % cycleLen;
819	    if (cyclePos < 0) cyclePos += cycleLen;
820	    if (cyclePos >= dashLen) continue; // gap — skip
821	
822	    var lineW = Math.max(cur.scale * (cfg.LANE_MARKER_WIDTH || 1.5), 0.6);
823	    ctx.lineWidth = lineW;
824	
825	    // Draw from centre position of this segment toward next
826	    // Use a short dash at the segment centre
827	    var dashScreenLen = Math.max(cur.scale * dashLen * 0.3, 3);
828	    var angle = seg.angle;
829	    var cosA  = Math.cos(angle);
830	    var sinA  = Math.sin(angle);
831	    // Forward direction in screen space (from the centre point)
832	    var fx = sinA * cur.scale * 8; // forward component projected to screen X
833	    var fy = -cfg.ROAD_V_OFFSET * cur.scale * 8; // forward component in screen Y
834	
835	    ctx.beginPath();
836	    ctx.moveTo(cur.sx - fx, cur.sy - fy);
837	    ctx.lineTo(cur.sx + fx, cur.sy + fy);
838	    ctx.stroke();
839	  }
