842	/**
843	 * Adjusts a hex colour string's brightness by a signed integer amount.
844	 * Preserves the colour format (#xxx or #xxxxxx).
845	 *
846	 * @param {string} hex    Hex colour (e.g. '#555')
847	 * @param {number} amount Signed adjustment (-255 to 255)
848	 * @returns {string} Adjusted hex colour
849	 */
850	function _adjustBrightness(hex, amount) {
851	  if (hex.charAt(0) === '#') hex = hex.slice(1);
852	  if (hex.length === 3) {
853	    hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
854	  }
855	  var r = Math.min(255, Math.max(0, parseInt(hex.slice(0, 2), 16) + amount));
856	  var g = Math.min(255, Math.max(0, parseInt(hex.slice(2, 4), 16) + amount));
857	  var b = Math.min(255, Math.max(0, parseInt(hex.slice(4, 6), 16) + amount));
858	  return '#' + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
859	}
