863	   ========================================================================== */
864	
865	/**
866	 * Returns the cumulative track distance of the nearest point on the track
867	 * centre-line to the given world position. Useful for AI lap tracking.
868	 *
869	 * @param {number} wx World X coordinate
870	 * @param {number} wz World Z coordinate
871	 * @returns {number} Track distance at nearest centre-line point
872	 */
873	R.getTrackDistanceAt = function (wx, wz) {
874	  var segs  = R.track.segments;
875	  var n     = segs.length;
876	  var bestIdx   = 0;
877	  var bestDist2 = Infinity;
878	  for (var i = 0; i < n; i++) {
879	    var dx = segs[i].worldX - wx;
880	    var dz = segs[i].worldZ - wz;
881	    var d2 = dx * dx + dz * dz;
882	    if (d2 < bestDist2) {
883	      bestDist2 = d2;
884	      bestIdx   = i;
885	    }
886	  }
887	  return segs[bestIdx].dist;
888	};
