890	/* ==========================================================================
891	   R.getSegmentAtDistance(dist) — Direct segment access
892	   ========================================================================== */
893	
894	/**
895	 * Returns the segment object at a given track distance (no interpolation).
896	 * Wraps around for closed circuit.
897	 *
898	 * @param {number} dist Cumulative track distance
899	 * @returns {Object} The segment at that distance
900	 */
901	R.getSegmentAtDistance = function (dist) {
902	  var segs  = R.track.segments;
903	  var total = R.track.totalLength;
904	  var n     = segs.length;
905	  var d     = dist % total;
906	  if (d < 0) d += total;
907	
908	  var lo = 0, hi = n - 1;
909	  while (lo < hi) {
910	    var mid = (lo + hi + 1) >> 1;
911	    if (segs[mid].dist <= d) lo = mid;
912	    else hi = mid - 1;
913	  }
914	  return segs[lo];
915	};
