918	   R.getTrackWidth(dist) — Quick width lookup (AI avoidance)
919	   ========================================================================== */
920	
921	/**
922	 * Returns the interpolated road width at a given track distance.
923	 * Convenience wrapper for AI / collision systems.
924	 *
925	 * @param {number} dist Cumulative track distance
926	 * @returns {number} Road width in world units
927	 */
928	R.getTrackWidth = function (dist) {
929	  var pos = R.getTrackPosition(dist);
930	  return pos.width;
