936	
937	/**
938	 * Extended on-track check that also verifies elevation proximity.
939	 * Useful for respawn logic or when cars go airborne (future).
940	 * Falls back to 2D check if worldY is unavailable.
941	 *
942	 * @param {number} wx World X
943	 * @param {number} wy World Y (elevation)
944	 * @param {number} wz World Z
945	 * @returns {{onTrack:boolean, distFromCenter:number, segmentIndex:number, elevationOk:boolean}}
946	 */
947	R.isOnTrackExtended = function (wx, wy, wz) {
948	  var result = R.isOnTrack(wx, wz);
949	
950	  if (!result.onTrack) return result;
951	
952	  // Check elevation proximity
953	  var seg       = R.track.segments[result.segmentIndex];
954	  var elevDiff  = Math.abs(wy - seg.worldY);
955	  var elevOk    = elevDiff < 80; // within 80 world units of segment elevation
956	
957	  return {
958	    onTrack:        result.onTrack && elevOk,
959	    distFromCenter: result.distFromCenter,
960	    segmentIndex:   result.segmentIndex,
961	    halfWidth:      result.halfWidth,
962	    elevationOk:    elevOk
963	  };
964	};
