185	/* ==========================================================================
186	   R.updatePlayer(dt) — Full car physics simulation
187	   dt = delta time in seconds (unscaled)
188	   ========================================================================== */
189	R.updatePlayer = function updatePlayer(dt) {
190	  const p  = R.player;
191	  if (!p || p.finished) return;
192	
193	  const cfg  = R.CONFIG;
194	  const inp  = R.input;
195	
196	  // Clamp dt to avoid huge jumps (tab-away recovery)
197	  const dtClamped = Math.min(dt, 0.05);
198	  // Scale factor: physics tuned at 60 fps, so multiply by dt*60
199	  const f = dtClamped * 60;
200	
201	  // ── 1. STEERING ──────────────────────────────────────────────────
202	  const steerInput = inp.steer || 0;               // -1..0..1
203	
204	  // Speed-sensitive steering (tighter at low speed, wider at high)
205	  const speedRatio = p.speed / p.maxSpeed;
206	  const steerResponse = cfg.HANDLING * (1 + speedRatio * 0.5);
207	  p.steerAngle += steerInput * steerResponse * f;
208	
209	  // Self-centering (stronger when no input)
210	  if (Math.abs(steerInput) < 0.05) {
211	    p.steerAngle *= Math.pow(cfg.STEER_CENTER_RATE, f);
212	  } else {
213	    p.steerAngle *= Math.pow(cfg.STEER_CENTER_RATE * 0.97, f);
214	  }
215	
216	  // Clamp
217	  if (p.steerAngle > cfg.MAX_STEER) p.steerAngle = cfg.MAX_STEER;
218	  if (p.steerAngle < -cfg.MAX_STEER) p.steerAngle = -cfg.MAX_STEER;
219	
220	  // ── 2. ACCELERATION / BRAKING ────────────────────────────────────
221	  const throttle = inp.throttle || 0;
222	  const brake    = inp.brake    || 0;
223	  const boost    = inp.boost    || 0;
224	
225	  // Boost activation
226	  if (boost && !p.boosting && p.boostCooldown <= 0 && p.speed > 0.5) {
227	    p.boosting     = true;
228	    p.boostTimer   = cfg.BOOST_DURATION;
229	    p.boostCooldown = cfg.BOOST_COOLDOWN + cfg.BOOST_DURATION;
230	  }
231	
232	  // Boost timer
233	  if (p.boosting) {
234	    p.boostTimer -= dt;
235	    if (p.boostTimer <= 0) {
236	      p.boosting   = false;
237	      p.boostTimer = 0;
238	    }
239	  }
240	
241	  // Boost cooldown
242	  if (p.boostCooldown > 0 && !p.boosting) {
243	    p.boostCooldown -= dt;
244	    if (p.boostCooldown < 0) p.boostCooldown = 0;
245	  }
246	
247	  // Apply acceleration
248	  if (throttle && !brake) {
249	    let accel = p.acceleration * f;
250	    if (p.boosting) accel *= cfg.BOOST_MULTIPLIER;
251	    p.speed += accel;
252	
253	    // Low-speed extra torque for startup feel
254	    if (p.speed < 1.0) {
255	      p.speed += accel * 0.5;
256	    }
257	  }
258	
259	  if (brake) {
260	    p.speed -= p.braking * f;
261	  }
262	
263	  // Friction (natural deceleration)
264	  p.speed *= Math.pow(cfg.FRICTION, f);
265	
266	  // Clamp speed (allow slight overshoot from boost)
267	  const maxNow = p.boosting ? p.maxSpeed * cfg.BOOST_MULTIPLIER : p.maxSpeed;
268	  if (p.speed < 0)    p.speed = 0;
269	  if (p.speed > maxNow) p.speed = maxNow;
270	
271	  // ── 3. DRIFT ─────────────────────────────────────────────────────
272	  const lateralForce = p.speed * p.steerAngle * 0.3 * f;
273	  p.driftFactor += (lateralForce - p.driftFactor) * 0.1 * f;
274	  const driftMagnitude = Math.abs(p.driftFactor);
275	  const wasDrifting = p.isDrifting;
276	  p.isDrifting = driftMagnitude > cfg.DRIFT_THRESHOLD;
277	
278	  // ── 4. POSITION UPDATE ───────────────────────────────────────────
279	  const effectiveAngle = p.angle + p.driftFactor * 0.5;
280	  const forwardFriction = p.isDrifting
281	    ? Math.pow(cfg.DRIFT_FACTOR, f)
282	    : 1.0;
283	
284	  p.x += Math.cos(p.angle) * p.speed * Math.cos(p.driftFactor) * forwardFriction * f;
285	  p.y += Math.sin(p.angle) * p.speed * Math.cos(p.driftFactor) * forwardFriction * f;
286	  p.angle += p.steerAngle * p.speed * 0.03 * f;
287	
288	  // Keep angle in [0, 2π)
289	  while (p.angle < 0)            p.angle += Math.PI * 2;
290	  while (p.angle >= Math.PI * 2) p.angle -= Math.PI * 2;
291	
292	  // Accumulate wheel rotation (for visual)
293	  p.wheelRot += p.speed * 0.06 * f;
294	
295	  // ── 5. TRACK CHECK ───────────────────────────────────────────────
296	  if (R.isOnTrack && typeof R.isOnTrack === 'function') {
297	    if (!R.isOnTrack(p.x, p.z)) {
298	      p.speed *= Math.pow(cfg.OFFROAD_FRICTION, f);
299	    }
300	  }
301	
302	  // ── 6. LAP / CHECKPOINT LOGIC ────────────────────────────────────
303	  if (R.track && R.track.segments && R.track.segments.length) {
304	    const segs = R.track.segments;
305	    const totalCheckpoints = segs.length;
306	
307	    // Current checkpoint target
308	    const targetSeg = segs[p.checkpointIdx % totalCheckpoints];
309	    if (targetSeg) {
310	      const dx = p.x - (targetSeg.worldX || 0);
311	      const dy = p.y - (targetSeg.worldY || 0);
312	      const dist = Math.sqrt(dx * dx + dy * dy);
313	
314	      if (dist < cfg.CHECKPOINT_PROXIMITY) {
315	        p.checkpointIdx++;
316	
317	        // Completed a full lap?
318	        if (p.checkpointIdx >= totalCheckpoints) {
319	          p.lap++;
320	          p.checkpointIdx = 0;
321	
322	          if (p.lap >= cfg.TOTAL_LAPS) {
323	            p.finished = true;
324	            p.speed = 0;
325	            R.state.phase = 'finished';
326	          }
327	        }
328	      }
329	    }
330	  }
331	
332	  // ── 7. Store z as total distance traveled ────────────────────────
333	  p.z += p.speed * f;
334	
335	  // ── 8. Drift marks (spawn every few pixels when drifting) ────────
336	  if (p.isDrifting && p.speed > 1.0) {
337	    const rearX = p.x - Math.cos(p.angle) * cfg.CAR_LENGTH * 0.4;
338	    const rearY = p.y - Math.sin(p.angle) * cfg.CAR_LENGTH * 0.4;
339	    const perpX = Math.cos(p.angle + Math.PI / 2);
340	    const perpY = Math.sin(p.angle + Math.PI / 2);
341	
342	    const trackOffset = cfg.CAR_WIDTH * 0.35;
343	    // Left rear
344	    spawnDriftMark(
345	      rearX + perpX * trackOffset,
346	      rearY + perpY * trackOffset
347	    );
348	    // Right rear
349	    spawnDriftMark(
350	      rearX - perpX * trackOffset,
351	      rearY - perpY * trackOffset
352	    );
353	  }
354	
355	  // ── 9. Exhaust particles ─────────────────────────────────────────
356	  if (throttle && p.speed > 0.3) {
357	    const rearX = p.x - Math.cos(p.angle) * cfg.CAR_LENGTH * 0.5;
358	    const rearY = p.y - Math.sin(p.angle) * cfg.CAR_LENGTH * 0.5;
359	    // Per-tick rate: more particles at higher speed / boost
360	    const rate = p.boosting ? 0.55 : 0.3;
361	    if (Math.random() < rate * f) {
362	      spawnExhaustParticle(rearX, rearY, p.angle);
363	    }
364	  }
365	
366	  // ── 10. Update drift marks (age / fade) ──────────────────────────
367	  for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) {
368	    const m = driftMarks[i];
369	    if (!m.alive) continue;
370	    m.age += dt;
371	    if (m.age > cfg.DRIFT_MARK_LIFETIME) {
372	      m.alive = false;
373	    } else {
374	      m.alpha = 0.55 * (1 - m.age / cfg.DRIFT_MARK_LIFETIME);
375	    }
376	  }
377	
378	  // ── 11. Update exhaust particles ─────────────────────────────────
379	  for (let i = 0; i < EXHAUST_CAPACITY; i++) {
380	    const ep = exhaustParticles[i];
381	    if (!ep.alive) continue;
382	    ep.life -= dt;
383	    if (ep.life <= 0) {
384	      ep.alive = false;
385	    } else {
386	      ep.x += ep.vx * f;
387	      ep.y += ep.vy * f;
388	    }
389	  }
390	
391	  // ── 12. Update bounce markers ────────────────────────────────────
392	  for (let i = 0; i < BOUNCE_CAPACITY; i++) {
393	    const bm = bounceMarkers[i];
394	    if (!bm.alive) continue;
395	    bm.alpha -= dt * 2.5;
396	    bm.radius += dt * 60;
397	    if (bm.alpha <= 0) bm.alive = false;
398	  }
399	};
