401	/* ==========================================================================
402	   R.playerCollide(obstacleX, obstacleY, obstacleRadius)
403	   Called by collision system. Bounces player and spawns visual marker.
404	   Returns true if collision was processed.
405	   ========================================================================== */
406	R.playerCollide = function playerCollide(ox, oy, oRadius) {
407	  const p = R.player;
408	  if (!p) return false;
409	
410	  spawnBounceMarker(p.x, p.y);
411	
412	  // Push player away from obstacle center
413	  const dx = p.x - ox;
414	  const dy = p.y - oy;
415	  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
416	  const pushDist = (oRadius || 30) + R.CONFIG.CAR_WIDTH * 0.6;
417	  p.x = ox + (dx / dist) * pushDist;
418	  p.y = oy + (dy / dist) * pushDist;
419	
420	  // Kill speed
421	  p.speed *= 0.4;
422	  p.driftFactor *= 0.5;
423	
424	  return true;
425	};
