427	/* ==========================================================================
428	   WORLD → SCREEN HELPERS
429	   ========================================================================== */
430	
431	/**
432	 * Convert world coordinates to screen coordinates using camera.
433	 * @param {number} wx - world x
434	 * @param {number} wy - world y
435	 * @returns {{ sx: number, sy: number }}
436	 */
437	function worldToScreen(wx, wy) {
438	  const cam = R.camera || { x: 0, y: 0, zoom: 1 };
439	  const W = (R.canvas && R.canvas.width)  || 1280;
440	  const H = (R.canvas && R.canvas.height) || 720;
441	  return {
442	    sx: (wx - cam.x) * cam.zoom + W / 2,
443	    sy: (wy - cam.y) * cam.zoom + H / 2,
444	  };
445	}
