447	/* ==========================================================================
448	   R.renderPlayerCar() — Detailed top-down car rendering
449	   Uses canvas transform stack (save/translate/rotate/restore).
450	   ========================================================================== */
451	R.renderPlayerCar = function renderPlayerCar() {
452	  const p = R.player;
453	  if (!p) return;
454	
455	  const cfg = R.CONFIG;
456	  const ctx = R.ctx;
457	  const cam = R.camera || { x: 0, y: 0, zoom: 1 };
458	  const zoom = cam.zoom;
459	
460	  // Convert world position to screen
461	  const screen = worldToScreen(p.x, p.y);
462	  const sx = screen.sx;
463	  const sy = screen.sy;
464	
465	  // Culling: skip if far off screen
466	  const W = (R.canvas && R.canvas.width)  || 1280;
467	  const H = (R.canvas && R.canvas.height) || 720;
468	  const margin = 200;
469	  if (sx < -margin || sx > W + margin || sy < -margin || sy > H + margin) return;
470	
471	  const carLen   = cfg.CAR_LENGTH   * zoom;
472	  const carHalfW = cfg.CAR_WIDTH    * 0.5 * zoom;
473	  const wheelLen = cfg.WHEEL_LENGTH * zoom;
474	  const wheelW   = cfg.WHEEL_WIDTH  * zoom;
475	  const wheelBase = cfg.WHEELBASE   * zoom;
476	
477	  ctx.save();
478	  ctx.translate(sx, sy);
479	  ctx.rotate(p.angle);
480	
481	  // ── 1. SHADOW ────────────────────────────────────────────────────
482	  const shadowOx = cfg.SHADOW_OFFSET_X * zoom;
483	  const shadowOy = cfg.SHADOW_OFFSET_Y * zoom;
484	  ctx.save();
485	  ctx.translate(shadowOx, shadowOy);
486	  ctx.fillStyle = `rgba(0, 0, 0, ${cfg.SHADOW_ALPHA})`;
487	  ctx.beginPath();
488	  ctx.ellipse(0, 0, carLen * 0.52, carHalfW * 1.15, 0, 0, Math.PI * 2);
489	  ctx.fill();
490	  ctx.restore();
491	
492	  // ── 2. CAR BODY ──────────────────────────────────────────────────
493	  // Main body — rounded rectangle
494	  const bodyFront  =  carLen * 0.5;
495	  const bodyRear   = -carLen * 0.5;
496	  const bodyRadius =  carHalfW * 0.55;
497	
498	  ctx.fillStyle = p.color;
499	  ctx.strokeStyle = p.accentColor;
500	  ctx.lineWidth = 2 * zoom;
501	  ctx.beginPath();
502	  roundedRect(ctx, bodyRear, -carHalfW, carLen, carHalfW * 2, bodyRadius);
503	  ctx.fill();
504	  ctx.stroke();
505	
506	  // Body panel lines — hood cut
507	  ctx.strokeStyle = 'rgba(255,255,255,0.12)';
508	  ctx.lineWidth = 1 * zoom;
509	  ctx.beginPath();
510	  ctx.moveTo(bodyFront * 0.65, -carHalfW * 0.85);
511	  ctx.lineTo(bodyFront * 0.65,  carHalfW * 0.85);
512	  ctx.stroke();
513	
514	  // ── 3. WINDSHIELD ────────────────────────────────────────────────
515	  const wsFront =  carLen * 0.5  - carLen * 0.06;
516	  const wsRear  =  carLen * 0.5  - carLen * cfg.WINDSHIELD_RATIO;
517	  ctx.fillStyle = 'rgba(20, 40, 60, 0.7)';
518	  ctx.beginPath();
519	  ctx.moveTo(wsFront, -carHalfW * 0.84);
520	  ctx.lineTo(wsRear,  -carHalfW * 0.88);
521	  ctx.lineTo(wsRear,   carHalfW * 0.88);
522	  ctx.lineTo(wsFront,  carHalfW * 0.84);
523	  ctx.closePath();
524	  ctx.fill();
525	
526	  // Windshield highlight
527	  ctx.fillStyle = 'rgba(180, 210, 255, 0.25)';
528	  ctx.beginPath();
529	  ctx.moveTo(wsFront * 0.85 + wsRear * 0.15, -carHalfW * 0.35);
530	  ctx.lineTo(wsRear * 0.7 + wsFront * 0.3,  -carHalfW * 0.55);
531	  ctx.lineTo(wsRear * 0.7 + wsFront * 0.3,  -carHalfW * 0.15);
532	  ctx.closePath();
533	  ctx.fill();
534	
535	  // ── 4. REAR WINDOW ───────────────────────────────────────────────
536	  const rwFront = -carLen * 0.5 + carLen * cfg.REAR_WINDOW_RATIO;
537	  const rwRear  = -carLen * 0.5 + carLen * 0.05;
538	  ctx.fillStyle = 'rgba(20, 35, 55, 0.6)';
539	  ctx.beginPath();
540	  ctx.moveTo(rwRear,  -carHalfW * 0.82);
541	  ctx.lineTo(rwFront, -carHalfW * 0.85);
542	  ctx.lineTo(rwFront,  carHalfW * 0.85);
543	  ctx.lineTo(rwRear,   carHalfW * 0.82);
544	  ctx.closePath();
545	  ctx.fill();
546	
547	  // ── 5. RACING STRIPE ─────────────────────────────────────────────
548	  const stripeW = cfg.STRIPE_WIDTH * 0.5 * zoom;
549	  ctx.fillStyle = p.accentColor;
550	  ctx.fillRect(-carLen * 0.44, -stripeW, carLen * 0.88, stripeW * 2);
551	
552	  // Thin pinstripe either side of center
553	  ctx.fillStyle = 'rgba(255,255,255,0.2)';
554	  const pinY = stripeW * 2.5;
555	  ctx.fillRect(-carLen * 0.42, -pinY, carLen * 0.84, 0.8 * zoom);
556	  ctx.fillRect(-carLen * 0.42,  pinY, carLen * 0.84, 0.8 * zoom);
557	
558	  // ── 6. HEADLIGHTS ────────────────────────────────────────────────
559	  ctx.fillStyle = '#ffffcc';
560	  ctx.shadowColor = 'rgba(255, 255, 180, 0.6)';
561	  ctx.shadowBlur = 4 * zoom;
562	  ctx.fillRect(bodyFront - 2 * zoom, -carHalfW * 0.72, 5 * zoom, 4 * zoom);
563	  ctx.fillRect(bodyFront - 2 * zoom,  carHalfW * 0.72 - 4 * zoom, 5 * zoom, 4 * zoom);
564	  ctx.shadowColor = 'transparent';
565	  ctx.shadowBlur = 0;
566	
567	  // ── 7. TAILLIGHTS ────────────────────────────────────────────────
568	  // Glow brighter when braking
569	  const brakeGlow = (R.input && R.input.brake) ? 1 : 0.4;
570	  ctx.fillStyle = `rgba(255, 30, 30, ${0.6 + brakeGlow * 0.4})`;
571	  ctx.shadowColor = `rgba(255, 0, 0, ${0.7 * brakeGlow})`;
572	  ctx.shadowBlur = 6 * zoom * brakeGlow;
573	  ctx.fillRect(bodyRear + 0.5 * zoom, -carHalfW * 0.72, 4.5 * zoom, 3.5 * zoom);
574	  ctx.fillRect(bodyRear + 0.5 * zoom,  carHalfW * 0.72 - 3.5 * zoom, 4.5 * zoom, 3.5 * zoom);
575	  ctx.shadowColor = 'transparent';
576	  ctx.shadowBlur = 0;
577	
578	  // ── 8. WHEELS ────────────────────────────────────────────────────
579	  // Steering rotation for front wheels only
580	  const steerVis = p.steerAngle * 0.65; // visual steer reduced for readability
581	
582	  // Wheel positions (local coords)
583	  const wheelPositions = [
584	    { x:  wheelBase * 0.5,  y: -carHalfW - wheelW * 0.2, steer: steerVis, tag: 'FL' },
585	    { x:  wheelBase * 0.5,  y:  carHalfW + wheelW * 0.2, steer: steerVis, tag: 'FR' },
586	    { x: -wheelBase * 0.5,  y: -carHalfW - wheelW * 0.2, steer: 0,        tag: 'RL' },
587	    { x: -wheelBase * 0.5,  y:  carHalfW + wheelW * 0.2, steer: 0,        tag: 'RR' },
588	  ];
589	
590	  for (const wp of wheelPositions) {
591	    ctx.save();
592	    ctx.translate(wp.x, wp.y);
593	    ctx.rotate(wp.steer);
594	
595	    // Tire rubber
596	    ctx.fillStyle = '#1a1a1a';
597	    ctx.fillRect(-wheelLen * 0.5, -wheelW * 0.5, wheelLen, wheelW);
598	
599	    // Tire tread lines
600	    ctx.strokeStyle = '#2a2a2a';
601	    ctx.lineWidth = 0.7 * zoom;
602	    for (let t = -wheelLen * 0.35; t <= wheelLen * 0.35; t += wheelLen * 0.25) {
603	      ctx.beginPath();
604	      ctx.moveTo(t, -wheelW * 0.5);
605	      ctx.lineTo(t,  wheelW * 0.5);
606	      ctx.stroke();
607	    }
608	
609	    // Hub cap (center)
610	    ctx.fillStyle = '#444';
611	    ctx.beginPath();
612	    ctx.arc(0, 0, wheelW * 0.28, 0, Math.PI * 2);
613	    ctx.fill();
614	
615	    // Hub detail (rotating spoke)
616	    const spokeAngle = p.wheelRot * (wp.tag[1] === 'L' ? 1 : -1);
617	    ctx.strokeStyle = '#666';
618	    ctx.lineWidth = 1 * zoom;
619	    ctx.beginPath();
620	    ctx.moveTo(
621	      Math.cos(spokeAngle) * wheelW * 0.2,
622	      Math.sin(spokeAngle) * wheelW * 0.2
623	    );
624	    ctx.lineTo(
625	      Math.cos(spokeAngle + Math.PI) * wheelW * 0.2,
626	      Math.sin(spokeAngle + Math.PI) * wheelW * 0.2
627	    );
628	    ctx.stroke();
629	
630	    ctx.restore();
631	  }
632	
633	  // ── 9. DOOR LINE ─────────────────────────────────────────────────
634	  ctx.strokeStyle = 'rgba(255,255,255,0.08)';
635	  ctx.lineWidth = 1 * zoom;
636	  const doorX = bodyFront - carLen * cfg.DOOR_LINE_OFFSET;
637	  ctx.beginPath();
638	  ctx.moveTo(doorX, -carHalfW * 0.86);
639	  ctx.lineTo(doorX,  carHalfW * 0.86);
640	  ctx.stroke();
641	
642	  // ── 10. EXHAUST FLAME ────────────────────────────────────────────
643	  const throttleOn = R.input && R.input.throttle;
644	  if (throttleOn && p.speed > 0.3) {
645	    const exhX = bodyRear - 2 * zoom;
646	    const exhBaseW = cfg.EXHAUST_BASE_WIDTH * zoom;
647	    const exhLen    = cfg.EXHAUST_LENGTH * zoom;
648	
649	    // Flame flicker
650	    const flicker = 0.7 + Math.random() * 0.3;
651	    const flameLen = exhLen * flicker * (p.boosting ? 1.8 : 1);
652	
653	    // Two exhaust pipes
654	    for (const side of [-1, 1]) {
655	      const exhY = side * carHalfW * 0.5;
656	
657	      // Outer glow
658	      ctx.fillStyle = 'rgba(255, 120, 20, 0.3)';
659	      ctx.beginPath();
660	      ctx.moveTo(exhX, exhY - exhBaseW * 0.5);
661	      ctx.lineTo(exhX - flameLen * 0.4, exhY - exhBaseW * 0.3);
662	      ctx.lineTo(exhX - flameLen, exhY);
663	      ctx.lineTo(exhX - flameLen * 0.4, exhY + exhBaseW * 0.3);
664	      ctx.lineTo(exhX, exhY + exhBaseW * 0.5);
665	      ctx.closePath();
666	      ctx.fill();
667	
668	      // Inner flame (brighter core)
669	      ctx.fillStyle = 'rgba(255, 220, 60, 0.7)';
670	      ctx.beginPath();
671	      ctx.moveTo(exhX, exhY - exhBaseW * 0.22);
672	      ctx.lineTo(exhX - flameLen * 0.55, exhY);
673	      ctx.lineTo(exhX, exhY + exhBaseW * 0.22);
674	      ctx.closePath();
675	      ctx.fill();
676	    }
677	
678	    // Boost glow ring at rear
679	    if (p.boosting) {
680	      ctx.fillStyle = 'rgba(100, 180, 255, 0.4)';
681	      ctx.beginPath();
682	      ctx.arc(bodyRear, 0, carHalfW * 0.9, 0, Math.PI * 2);
683	      ctx.fill();
684	    }
685	  }
686	
687	  ctx.restore();
688	
689	  // ── 11. DRIFT MARKS (world-space, not car-relative) ──────────────
690	  renderDriftMarks();
691	
692	  // ── 12. EXHAUST PARTICLES (world-space) ──────────────────────────
693	  renderExhaustParticles();
694	
695	  // ── 13. BOUNCE MARKERS (world-space) ─────────────────────────────
696	  renderBounceMarkers();
697	};
698	
699	/* ==========================================================================
700	   Drift mark rendering (world-space, called from renderPlayerCar)
701	   ========================================================================== */
702	function renderDriftMarks() {
703	  const ctx = R.ctx;
704	  for (let i = 0; i < DRIFT_MARK_CAPACITY; i++) {
705	    const m = driftMarks[i];
706	    if (!m.alive) continue;
707	    const sc = worldToScreen(m.x, m.y);
708	    ctx.fillStyle = `rgba(180, 180, 180, ${m.alpha.toFixed(3)})`;
709	    ctx.beginPath();
710	    ctx.arc(sc.sx, sc.sy, 2.5 * (R.camera ? R.camera.zoom : 1), 0, Math.PI * 2);
711	    ctx.fill();
712	  }
713	}
714	
715	/* ==========================================================================
716	   Exhaust particle rendering
717	   ========================================================================== */
718	function renderExhaustParticles() {
719	  const ctx = R.ctx;
720	  const cam = R.camera || { zoom: 1 };
721	  for (let i = 0; i < EXHAUST_CAPACITY; i++) {
722	    const ep = exhaustParticles[i];
723	    if (!ep.alive) continue;
724	    const sc = worldToScreen(ep.x, ep.y);
725	    const lifeRatio = ep.life / ep.maxLife;
726	    const alpha = lifeRatio * 0.7;
727	    const size = ep.size * lifeRatio * cam.zoom;
728	
729	    ctx.fillStyle = `rgba(255, ${Math.floor(140 + lifeRatio * 80)}, 20, ${alpha.toFixed(3)})`;
730	    ctx.beginPath();
731	    ctx.arc(sc.sx, sc.sy, size, 0, Math.PI * 2);
732	    ctx.fill();
733	  }
734	}
735	
736	/* ==========================================================================
737	   Bounce marker rendering
738	   ========================================================================== */
739	function renderBounceMarkers() {
740	  const ctx = R.ctx;
741	  const cam = R.camera || { zoom: 1 };
742	  for (let i = 0; i < BOUNCE_CAPACITY; i++) {
743	    const bm = bounceMarkers[i];
744	    if (!bm.alive) continue;
745	    const sc = worldToScreen(bm.x, bm.y);
746	    ctx.strokeStyle = `rgba(255, 255, 255, ${bm.alpha.toFixed(3)})`;
747	    ctx.lineWidth = 2 * cam.zoom;
748	    ctx.beginPath();
749	    ctx.arc(sc.sx, sc.sy, bm.radius * cam.zoom, 0, Math.PI * 2);
750	    ctx.stroke();
751	
752	    // Expanding ring
753	    ctx.strokeStyle = `rgba(255, 200, 80, ${(bm.alpha * 0.5).toFixed(3)})`;
754	    ctx.lineWidth = 1 * cam.zoom;
755	    ctx.beginPath();
756	    ctx.arc(sc.sx, sc.sy, bm.radius * cam.zoom * 1.4, 0, Math.PI * 2);
757	    ctx.stroke();
758	  }
759	}
