761	/* ==========================================================================
762	   R.renderPlayerHUD() — Render HUD elements for player state
763	   Speedometer, lap counter, boost gauge.
764	   ========================================================================== */
765	R.renderPlayerHUD = function renderPlayerHUD() {
766	  const p = R.player;
767	  if (!p) return;
768	  const ctx = R.ctx;
769	  const cfg = R.CONFIG;
770	  const W = (R.canvas && R.canvas.width)  || 1280;
771	  const H = (R.canvas && R.canvas.height) || 720;
772	
773	  ctx.save();
774	
775	  // ── Speedometer (bottom-right) ───────────────────────────────────
776	  const speedoX = W - 160;
777	  const speedoY = H - 110;
778	  const speedKmh = Math.round(p.speed * 20); // px/frame → km/h-ish
779	
780	  // Background panel
781	  ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
782	  ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
783	  ctx.lineWidth = 2;
784	  ctx.beginPath();
785	  roundedRect(ctx, speedoX, speedoY, 140, 90, 10);
786	  ctx.fill();
787	  ctx.stroke();
788	
789	  // Speed number
790	  ctx.fillStyle = '#ffffff';
791	  ctx.font = 'bold 36px "Segoe UI", "PingFang SC", sans-serif';
792	  ctx.textAlign = 'right';
793	  ctx.fillText(speedKmh, speedoX + 120, speedoY + 42);
794	
795	  // KM/H label
796	  ctx.fillStyle = 'rgba(255,255,255,0.5)';
797	  ctx.font = '12px "Segoe UI", "PingFang SC", sans-serif';
798	  ctx.fillText('KM/H', speedoX + 120, speedoY + 62);
799	
800	  // Speed bar
801	  const barX = speedoX + 15;
802	  const barW = 110;
803	  const barY = speedoY + 52;
804	  const barH = 5;
805	  const speedPct = p.speed / p.maxSpeed;
806	
807	  ctx.fillStyle = 'rgba(255,255,255,0.12)';
808	  ctx.fillRect(barX, barY, barW, barH);
809	
810	  const barColor = p.boosting ? '#4488ff' : '#00ff88';
811	  ctx.fillStyle = barColor;
812	  ctx.fillRect(barX, barY, barW * speedPct, barH);
813	
814	  // ── Lap Counter (top-right) ──────────────────────────────────────
815	  const lapX = W - 50;
816	  const lapY = 40;
817	
818	  ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
819	  ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
820	  ctx.lineWidth = 2;
821	  ctx.beginPath();
822	  roundedRect(ctx, lapX - 85, lapY - 5, 75, 50, 8);
823	  ctx.fill();
824	  ctx.stroke();
825	
826	  ctx.fillStyle = 'rgba(255,255,255,0.5)';
827	  ctx.font = '11px "Segoe UI", "PingFang SC", sans-serif';
828	  ctx.textAlign = 'right';
829	  ctx.fillText('LAP', lapX, lapY + 14);
830	
831	  ctx.fillStyle = '#ffffff';
832	  ctx.font = 'bold 24px "Segoe UI", "PingFang SC", sans-serif';
833	  const lapDisplay = Math.min(p.lap + 1, cfg.TOTAL_LAPS);
834	  ctx.fillText(lapDisplay + '/' + cfg.TOTAL_LAPS, lapX, lapY + 40);
835	
836	  // ── Boost Gauge (bottom-right, above speedo) ─────────────────────
837	  const boostX = W - 160;
838	  const boostY = speedoY - 45;
839	  const boostReady = p.boostCooldown <= 0 && !p.boosting;
840	
841	  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
842	  ctx.strokeStyle = boostReady ? 'rgba(100, 180, 255, 0.7)' : 'rgba(255,255,255,0.12)';
843	  ctx.lineWidth = boostReady ? 2 : 1;
844	  ctx.beginPath();
845	  roundedRect(ctx, boostX, boostY, 140, 28, 6);
846	  ctx.fill();
847	  ctx.stroke();
848	
849	  if (p.boosting) {
850	    // Active boost — pulsing bar
851	    const pulse = 0.6 + Math.sin(R.state.time * 20) * 0.4;
852	    const boostPct = p.boostTimer / R.CONFIG.BOOST_DURATION;
853	    ctx.fillStyle = `rgba(68, 136, 255, ${pulse.toFixed(2)})`;
854	    ctx.fillRect(boostX + 3, boostY + 3, 134 * boostPct, 22);
855	    ctx.fillStyle = '#ffffff';
856	    ctx.font = 'bold 13px "Segoe UI", "PingFang SC", sans-serif';
857	    ctx.textAlign = 'center';
858	    ctx.fillText('BOOST!', boostX + 70, boostY + 19);
859	  } else if (!boostReady) {
860	    // Cooldown
861	    const cdPct = 1 - (p.boostCooldown / (R.CONFIG.BOOST_COOLDOWN + R.CONFIG.BOOST_DURATION));
862	    ctx.fillStyle = 'rgba(100, 100, 120, 0.6)';
863	    ctx.fillRect(boostX + 3, boostY + 3, 134 * cdPct, 22);
864	    ctx.fillStyle = 'rgba(255,255,255,0.5)';
865	    ctx.font = '11px "Segoe UI", "PingFang SC", sans-serif';
866	    ctx.textAlign = 'center';
867	    ctx.fillText(Math.ceil(p.boostCooldown) + 's', boostX + 70, boostY + 18);
868	  } else {
869	    ctx.fillStyle = 'rgba(255,255,255,0.45)';
870	    ctx.font = '12px "Segoe UI", "PingFang SC", sans-serif';
871	    ctx.textAlign = 'center';
872	    ctx.fillText('BOOST READY', boostX + 70, boostY + 18);
873	  }
874	
875	  // ── Drift indicator ──────────────────────────────────────────────
876	  if (p.isDrifting) {
877	    const driftX = W / 2;
878	    const driftY = H - 60;
879	    ctx.fillStyle = 'rgba(255, 150, 30, 0.8)';
880	    ctx.font = 'bold italic 16px "Segoe UI", "PingFang SC", sans-serif';
881	    ctx.textAlign = 'center';
882	    ctx.fillText('DRIFT', driftX, driftY);
883	  }
884	
885	  ctx.restore();
886	};
