960	/**
961	 * Draw a rounded rectangle path on the current context.
962	 * @param {CanvasRenderingContext2D} ctx
963	 * @param {number} x - left
964	 * @param {number} y - top
965	 * @param {number} w - width
966	 * @param {number} h - height
967	 * @param {number} r - corner radius
968	 */
969	function roundedRect(ctx, x, y, w, h, r) {
970	  r = Math.min(r, w / 2, h / 2);
971	  ctx.moveTo(x + r, y);
972	  ctx.lineTo(x + w - r, y);
973	  ctx.arcTo(x + w, y, x + w, y + r, r);
974	  ctx.lineTo(x + w, y + h - r);
975	  ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
976	  ctx.lineTo(x + r, y + h);
977	  ctx.arcTo(x, y + h, x, y + h - r, r);
978	  ctx.lineTo(x, y + r);
979	  ctx.arcTo(x, y, x + r, y, r);
980	  ctx.closePath();
981	}
