146	  /**
147	   * Get the track segment at a given worldZ position.
148	   * Segments are assumed to be ordered by worldZ (increasing).
149	   * @param {number} worldZ
150	   * @returns {{ segment: object, index: number }|null}
151	   */
152	  function getSegmentAtZ(worldZ) {
153	    const segs = R.track.segments;
154	    if (!segs || segs.length === 0) return null;
155	    /* Binary-ish search for the segment containing this z */
156	    /**
157	     * Track segments define the road ahead. We find the segment whose
158	     * cumulative z range contains worldZ. Assumes segments are sequential.
159	     */
160	    let cumulativeZ = 0;
161	    for (let i = 0; i < segs.length; i++) {
162	      const seg = segs[i];
163	      const segLength = seg.length || 200; // default segment length
164	      if (worldZ >= cumulativeZ && worldZ < cumulativeZ + segLength) {
165	        return { segment: seg, index: i, localZ: worldZ - cumulativeZ, segStartZ: cumulativeZ };
166	      }
167	      cumulativeZ += segLength;
168	    }
169	    /* Wrap around for looping track */
170	    if (segs.length > 0) {
171	      cumulativeZ = 0;
172	      for (let i = 0; i < segs.length; i++) {
173	        const seg = segs[i];
174	        const segLength = seg.length || 200;
175	        cumulativeZ += segLength;
176	      }
177	      const wrappedZ = ((worldZ % cumulativeZ) + cumulativeZ) % cumulativeZ;
178	      let cz = 0;
179	      for (let i = 0; i < segs.length; i++) {
180	        const seg = segs[i];
181	        const segLength = seg.length || 200;
182	        if (wrappedZ >= cz && wrappedZ < cz + segLength) {
183	          return { segment: seg, index: i, localZ: wrappedZ - cz, segStartZ: cz };
184	        }
185	        cz += segLength;
186	      }
187	    }
188	    return null;
189	  }
190	
191	  /**
192	   * Calculate the cumulative distance traveled (z) by following the track.
193	   * For AI position sorting, we use worldZ as the primary sort key.
194	   * Accounts for lap count.
195	   * @param {object} car
196	   * @returns {number} total distance traveled
197	   */
198	  function getTotalDistance(car) {
199	    const segs = R.track.segments;
200	    if (!segs || segs.length === 0) return car.z || car.y || 0;
201	    let trackLength = 0;
202	    for (let i = 0; i < segs.length; i++) {
203	      trackLength += segs[i].length || 200;
204	    }
205	    return (car.lap || 0) * trackLength + (car.z || car.y || 0);
206	  }
207	
208	  /**
209	   * Get the worldX center of the track at a given position.
210	   * Accounts for curvature to offset the center line.
211	   * @param {number} worldZ
212	   * @param {number} lookaheadZ — how far ahead to look
213	   * @returns {{ x: number, curvature: number }}
214	   */
215	  function getTrackCenterAt(worldZ, lookaheadZ) {
216	    const zTarget = worldZ + lookaheadZ;
217	    const segInfo = getSegmentAtZ(zTarget);
218	    if (!segInfo) {
219	      return { x: 400, curvature: 0 }; // default center
220	    }
221	    const seg = segInfo.segment;
222	    /* Accumulate lateral offset from curvature of preceding segments */
223	    let totalCurveOffset = 0;
224	    let totalCurvature = 0;
225	    const segs = R.track.segments;
226	    let cz = 0;
227	    for (let i = 0; i < segs.length && cz < zTarget; i++) {
228	      const s = segs[i];
229	      const sLen = s.length || 200;
230	      if (cz < worldZ) {
231	        cz += sLen;
232	        continue;
233	      }
234	      const endZ = cz + sLen;
235	      const overlapStart = Math.max(cz, worldZ);
236	      const overlapEnd = Math.min(endZ, zTarget);
237	      if (overlapEnd > overlapStart) {
238	        const frac = (overlapEnd - overlapStart) / (zTarget - worldZ);
239	        totalCurveOffset += (s.curvature || 0) * frac * sLen;
240	        totalCurvature += (s.curvature || 0) * frac;
241	      }
242	      cz += sLen;
243	      if (cz >= zTarget) break;
244	    }
245	    /* Segments have worldX — use the current segment's worldX plus curvature offset */
246	    const segX = seg.worldX !== undefined ? seg.worldX : 400;
247	    return { x: segX + totalCurveOffset * 0.5, curvature: totalCurvature };
248	  }
249	
250	  /**
251	   * Get the weighted average curvature of upcoming segments.
252	   * Used for pre-braking decisions.
253	   * @param {number} worldZ — current z position
254	   * @param {number} lookDistance — how far ahead to scan
255	   * @returns {number} average absolute curvature (0 = straight, >0 = curve)
256	   */
257	  function getUpcomingCurvature(worldZ, lookDistance) {
258	    const segs = R.track.segments;
259	    if (!segs || segs.length === 0) return 0;
260	    let totalWeight = 0;
261	    let weightedCurv = 0;
262	    let cz = 0;
263	    const endZ = worldZ + lookDistance;
264	    for (let i = 0; i < segs.length; i++) {
265	      const s = segs[i];
266	      const sLen = s.length || 200;
267	      const segEnd = cz + sLen;
268	      if (segEnd > worldZ && cz < endZ) {
269	        const overlapStart = Math.max(cz, worldZ);
270	        const overlapEnd = Math.min(segEnd, endZ);
271	        if (overlapEnd > overlapStart) {
272	          /* Closer segments weighted more heavily */
273	          const dist = overlapStart - worldZ;
274	          const weight = (lookDistance - dist) / lookDistance * (overlapEnd - overlapStart);
275	          weightedCurv += Math.abs(s.curvature || 0) * weight;
276	          totalWeight += weight;
277	        }
278	      }
279	      cz += sLen;
280	      if (cz >= endZ) break;
281	    }
282	    return totalWeight > 0 ? weightedCurv / totalWeight : 0;
283	  }
