285	  /**
286	   * Calculate total track length (one lap).
287	   * @returns {number}
288	   */
289	  function trackLength() {
290	    const segs = R.track.segments;
291	    if (!segs || segs.length === 0) return 10000;
292	    let len = 0;
293	    for (let i = 0; i < segs.length; i++) {
294	      len += segs[i].length || 200;
295	    }
296	    return len;
297	  }
