330	        speed: 0,
331	        steerAngle: 0,
332	        driftFactor: 0,
333	        /* Race state */
334	        lap: 0,
335	        checkpointIdx: 0,
336	        finished: false,
337	        /* Visual */
338	        color: shuffledColors[i % shuffledColors.length],
339	        /* Performance (tuned per-car) */
340	        maxSpeed: (R.CONFIG.CAR_MAX_SPEED || 12) * lerp(R.CONFIG.AI_MAX_SPEED_VARIANCE, 1.0, skill),
341	        acceleration: (R.CONFIG.CAR_ACCELERATION || 0.15) * lerp(R.CONFIG.AI_ACCELERATION_VARIANCE, 1.0, skill),
342	        braking: (R.CONFIG.CAR_BRAKING || 0.3),
343	        handling: (R.CONFIG.CAR_HANDLING || 0.04) * skill,
344	        /* AI-specific fields */
345	        driverName: shuffledNames[i % shuffledNames.length],
346	        aggression: randRange(aggRange[0], aggRange[1]),
347	        skillLevel: skill,
348	        targetSpeed: 0,
349	        state: 'racing',        // 'racing' | 'overtaking' | 'defending' | 'recovering'
350	        stateTimer: 0,
351	        prevSteer: 0,
352	        brakeLevel: 0,
353	        prevWorldZ: -R.CONFIG.AI_STAGGER_DISTANCE * (i + 1),
354	        totalDistance: 0,
355	        overtakeTarget: null,   // reference to car being overtaken
356	        defendAgainst: null,    // reference to car defending against
