386	  /**
387	   * Update all AI cars each frame.
388	   * @param {number} dt — delta time in seconds
389	   */
390	  R.updateAI = function(dt) {
391	    if (R.state.phase !== 'racing') { return; }
392	    if (!R.aiCars || R.aiCars.length === 0) { return; }
393	
394	    const dtClamped = Math.min(dt, 0.05); // cap to prevent physics explosion
395	    const allCars = getAllCars(); // player + AI for interaction
396	
397	    for (let i = 0; i < R.aiCars.length; i++) {
398	      const ai = R.aiCars[i];
399	      if (ai.finished) { continue; }
400	
401	      updateAISingle(ai, i, dtClamped, allCars);
402	    }
403	  };
404	
405	  /**
406	   * Update a single AI car for one frame.
407	   * @param {object} ai
408	   * @param {number} index
409	   * @param {number} dt
410	   * @param {object[]} allCars
411	   */
412	  function updateAISingle(ai, index, dt, allCars) {
413	    /* ---- Step 1: Find target position ahead on track ---- */
414	    const lookaheadDist = R.CONFIG.AI_LOOKAHEAD_BASE
415	      + ai.speed * R.CONFIG.AI_LOOKAHEAD_SPEED_FACTOR * ai.skillLevel;
416	    const trackInfo = getTrackCenterAt(ai.z, lookaheadDist);
417	    const upcomingCurv = getUpcomingCurvature(ai.z, lookaheadDist);
418	
419	    /* ---- Step 2: Calculate desired angle to target ---- */
420	    const targetX = trackInfo.x;
421	    const targetZ = ai.z + lookaheadDist;
422	    const currentX = ai.x;
423	    const dx = targetX - currentX;
424	    const dz = targetZ - ai.z;
425	
426	    let desiredAngle = Math.atan2(dx, dz);
427	
428	    /* Racing line optimization: skilled drivers hug the inside of curves */
429	    if (trackInfo.curvature !== 0 && ai.skillLevel > 0.55) {
430	      const curveSign = trackInfo.curvature > 0 ? 1 : -1;
431	      const lineOffset = curveSign * R.track.segments[0].width * 0.15 * ai.skillLevel;
432	      desiredAngle = Math.atan2(dx + lineOffset, dz);
433	    }
434	
435	    /* ---- Step 3: Steer toward desired angle ---- */
436	    const angleErr = angleDelta(ai.angle, desiredAngle);
437	    const steerSmooth = lerp(
438	      R.CONFIG.AI_STEER_SMOOTH,
439	      R.CONFIG.AI_STEER_SMOOTH_HIGH_SKILL,
440	      ai.skillLevel
441	    );
442	
443	    /* Aggressive AIs turn faster */
444	    const aggressionSteerMul = 0.7 + ai.aggression * 0.6;
445	    let targetSteer = clamp(angleErr * steerSmooth * 15 * aggressionSteerMul, -1, 1);
446	
447	    /* Smoother transition for high-skill drivers */
448	    ai.steerAngle = lerp(ai.prevSteer, targetSteer, steerSmooth * 3);
449	    ai.prevSteer = ai.steerAngle;
450	
451	    /* ---- Step 4: AI state transitions ---- */
452	    updateAIState(ai, allCars, upcomingCurv);
453	
454	    /* ---- Step 5: Speed control based on state and upcoming road ---- */
455	    updateAISpeed(ai, dt, upcomingCurv, trackInfo);
456	
457	    /* ---- Step 6: Apply physics (same as player car physics) ---- */
458	    applyCarPhysics(ai, dt);
459	
460	    /* ---- Step 7: Lap and checkpoint detection ---- */
461	    updateAILapProgress(ai);
462	
463	    /* ---- Step 8: Off-track recovery ---- */
464	    handleOffTrack(ai, dt);
465	  }
