471	  /**
472	   * Determine and transition AI state.
473	   * @param {object} ai
474	   * @param {object[]} allCars
475	   * @param {number} upcomingCurv
476	   */
477	  function updateAIState(ai, allCars, upcomingCurv) {
478	    /* Check for car ahead within overtaking range */
479	    const carAhead = findCarAhead(ai, allCars, R.CONFIG.AI_OVERTAKE_RANGE);
480	
481	    /* Check for car behind within defending range */
482	    const carBehind = findCarBehind(ai, allCars, R.CONFIG.AI_DEFEND_RANGE);
483	
484	    /* Check if off track */
485	    const segInfo = getSegmentAtZ(ai.z);
486	    const offTrack = isOffTrack(ai, segInfo);
487	
488	    /* State transitions */
489	    if (offTrack && ai.state !== 'recovering') {
490	      ai.state = 'recovering';
491	      ai.recoveryTimer = 60;
492	    } else if (ai.state === 'recovering') {
493	      ai.recoveryTimer--;
494	      if (!offTrack && ai.recoveryTimer <= 0) {
495	        ai.state = 'racing';
496	      }
497	    } else if (carAhead && ai.aggression > 0.35 && !offTrack) {
498	      /* Only attempt overtaking if car ahead is slower */
499	      if (carAhead.speed < ai.speed * 1.05 || ai.aggression > 0.65) {
500	        ai.state = 'overtaking';
501	        ai.overtakeTarget = carAhead;
502	      } else {
503	        ai.state = 'racing';
504	        ai.overtakeTarget = null;
505	      }
506	    } else if (carBehind && carBehind.aggression > 0.5 && ai.aggression > 0.3 && !offTrack) {
507	      /* Defensive driving: block if someone aggressive is behind */
508	      ai.state = 'defending';
509	      ai.defendAgainst = carBehind;
510	    } else {
511	      ai.state = 'racing';
512	      ai.overtakeTarget = null;
513	      ai.defendAgainst = null;
514	    }
515	
516	    /* State timer tracking */
517	    if (ai.state === 'overtaking') {
518	      ai.stateTimer++;
519	    } else if (ai.state === 'defending') {
520	      ai.stateTimer++;
521	    } else {
522	      ai.stateTimer = 0;
523	    }
524	  }
