526	  /**
527	   * Find the nearest car ahead of this AI within range.
528	   * @param {object} ai
529	   * @param {object[]} allCars
530	   * @param {number} range
531	   * @returns {object|null}
532	   */
533	  function findCarAhead(ai, allCars, range) {
534	    let closest = null;
535	    let closestDist = range;
536	    for (let i = 0; i < allCars.length; i++) {
537	      const other = allCars[i];
538	      if (other === ai) { continue; }
539	      if (other.finished) { continue; }
540	      const dz = other.z - ai.z;
541	      if (dz > 0 && dz < range) {
542	        const dx = Math.abs(other.x - ai.x);
543	        if (dx < 50 && dz < closestDist) {
544	          closestDist = dz;
545	          closest = other;
546	        }
547	      }
548	    }
549	    return closest;
550	  }
551	
552	  /**
553	   * Find the nearest car behind this AI within range.
554	   * @param {object} ai
555	   * @param {object[]} allCars
556	   * @param {number} range
557	   * @returns {object|null}
558	   */
559	  function findCarBehind(ai, allCars, range) {
560	    let closest = null;
561	    let closestDist = range;
562	    for (let i = 0; i < allCars.length; i++) {
563	      const other = allCars[i];
564	      if (other === ai) { continue; }
565	      if (other.finished) { continue; }
566	      const dz = ai.z - other.z;
567	      if (dz > 0 && dz < range) {
568	        const dx = Math.abs(other.x - ai.x);
569	        if (dx < 50 && dz < closestDist) {
570	          closestDist = dz;
571	          closest = other;
572	        }
573	      }
574	    }
575	    return closest;
576	  }
