578	  /**
579	   * Check if an AI car is off the track.
580	   * @param {object} ai
581	   * @param {object|null} segInfo
582	   * @returns {boolean}
583	   */
584	  function isOffTrack(ai, segInfo) {
585	    if (!segInfo) { return false; }
586	    const seg = segInfo.segment;
587	    const halfWidth = (seg.width || 120) / 2;
588	    const centerX = seg.worldX !== undefined ? seg.worldX : 400;
589	    const distFromCenter = Math.abs(ai.x - centerX);
590	    return distFromCenter > halfWidth + R.CONFIG.AI_OFFTRACK_THRESHOLD;
591	  }
