593	  /* ==========================================================================
594	     AI Speed Control
595	     ========================================================================== */
596	
597	  /**
598	   * Control AI speed based on road conditions and state.
599	   * @param {object} ai
600	   * @param {number} dt
601	   * @param {number} upcomingCurv
602	   * @param {{ x: number, curvature: number }} trackInfo
603	   */
604	  function updateAISpeed(ai, dt, upcomingCurv, trackInfo) {
605	    const brakeCurvThresh = R.CONFIG.AI_BRAKE_CURVATURE_THRESHOLD;
606	    const brakeHardCurv = R.CONFIG.AI_BRAKE_HARD_CURVATURE;
607	
608	    /* Target speed based on upcoming curvature */
609	    let idealSpeed = ai.maxSpeed;
610	
611	    /* Pre-brake for upcoming corners */
612	    if (upcomingCurv > brakeCurvThresh) {
613	      /* Skilled drivers brake less before corners */
614	      const brakeFactor = 1 - (ai.skillLevel * 0.5);
615	      const curvRatio = clamp(
616	        (upcomingCurv - brakeCurvThresh) / (brakeHardCurv - brakeCurvThresh),
617	        0, 1
618	      );
619	      const speedReduction = curvRatio * ai.maxSpeed * 0.6 * brakeFactor;
620	      idealSpeed = ai.maxSpeed - speedReduction;
621	      /* Hard brake for tight corners */
622	      if (upcomingCurv > brakeHardCurv * 0.7) {
623	        idealSpeed = ai.maxSpeed * 0.35 * (1 + ai.skillLevel * 0.5);
624	      }
625	    }
626	
627	    /* Curve negotiation: skilled drivers can corner faster */
628	    const currentCurv = Math.abs(trackInfo.curvature);
629	    if (currentCurv > brakeCurvThresh * 0.3) {
630	      const cornerSpeedPenalty = currentCurv * 400 * (1 - ai.skillLevel * 0.6);
631	      idealSpeed = Math.min(idealSpeed, ai.maxSpeed - cornerSpeedPenalty);
632	    }
633	
634	    /* State-specific speed adjustments */
635	    if (ai.state === 'overtaking') {
636	      /* Push harder when overtaking */
637	      idealSpeed = Math.min(idealSpeed * 1.08, ai.maxSpeed * 1.02);
638	      /* High aggression: more speed, less caution */
639	      if (ai.aggression > 0.7) {
640	        idealSpeed *= 1.05;
641	      }
642	    } else if (ai.state === 'defending') {
643	      /* Slightly faster to maintain position */
644	      idealSpeed = Math.min(idealSpeed * 1.03, ai.maxSpeed * 0.98);
645	    } else if (ai.state === 'recovering') {
646	      /* Slow down to regain control */
647	      idealSpeed = ai.maxSpeed * 0.45;
648	    }
649	
650	    /* Overtaking: steer to inside of approaching curve if car ahead is slower */
651	    if (ai.state === 'overtaking' && ai.overtakeTarget && trackInfo.curvature !== 0) {
652	      const curveSign = trackInfo.curvature > 0 ? 1 : -1;
653	      /* Inside line on curves */
654	      const insideOffset = -curveSign * 25;
655	      ai.steerAngle += insideOffset * 0.015 * ai.aggression;
656	      ai.steerAngle = clamp(ai.steerAngle, -1, 1);
657	    }
658	
659	    /* Defending: block the racing line */
660	    if (ai.state === 'defending') {
661	      /* Position car in the middle to block overtaking attempts */
662	      const segInfo = getSegmentAtZ(ai.z);
663	      if (segInfo) {
664	        const centerX = segInfo.segment.worldX || 400;
665	        if (Math.abs(ai.x - centerX) < 20) {
666	          /* Stay near center to block the racing line */
667	          ai.steerAngle *= 0.8;
668	        }
669	      }
670	    }
671	
672	    /* ---- Rubber-banding: subtle speed adjustment ---- */
673	    idealSpeed = applyRubberBanding(ai, idealSpeed);
674	
675	    /* ---- Apply acceleration or braking to reach ideal speed ---- */
676	    ai.targetSpeed = idealSpeed;
677	    const speedDiff = idealSpeed - ai.speed;
678	
679	    if (speedDiff > 0) {
680	      /* Accelerate */
681	      ai.speed += ai.acceleration * dt * 60;
682	      ai.brakeLevel = 0;
683	    } else {
684	      /* Brake */
685	      const brakeForce = ai.braking * (1 + (1 - ai.skillLevel) * 0.5);
686	      ai.speed += Math.max(speedDiff, -brakeForce * dt * 60);
687	      ai.brakeLevel = Math.min(1, Math.abs(speedDiff) / ai.maxSpeed * 2);
688	    }
689	
690	    /* Ensure minimum speed */
691	    if (ai.speed < 0.5 && ai.state !== 'recovering') {
692	      ai.speed = 0.5;
693	    }
694	    ai.speed = clamp(ai.speed, 0, ai.maxSpeed * 1.1);
695	  }
696	
697	  /**
698	   * Subtle rubber-banding: AI speeds up slightly if player is far ahead,
699	   * slows down slightly if player is far behind.
700	   * @param {object} ai
701	   * @param {number} idealSpeed
702	   * @returns {number} adjusted speed
703	   */
704	  function applyRubberBanding(ai, idealSpeed) {
705	    const playerCar = R.playerCar;
706	    if (!playerCar || playerCar.finished) { return idealSpeed; }
707	
708	    const aiDist = getTotalDistance(ai);
709	    const playerDist = getTotalDistance(playerCar);
710	    const gap = playerDist - aiDist; // positive = player ahead
711	    const bandRange = R.CONFIG.AI_RUBBERBAND_RANGE;
712	    const bandFactor = R.CONFIG.AI_RUBBERBAND_FACTOR;
713	
714	    if (Math.abs(gap) > bandRange) {
715	      if (gap > 0) {
716	        /* Player is far ahead — AI gets a slight boost */
717	        return idealSpeed * (1 + bandFactor);
718	      } else {
719	        /* Player is far behind — AI slows a tiny bit */
720	        return idealSpeed * (1 - bandFactor * 0.5);
721	      }
722	    }
723	    return idealSpeed;
724	  }
