726	  /**
727	   * Get all cars (player + AI) in a unified array for interaction.
728	   * @returns {object[]}
729	   */
730	  function getAllCars() {
731	    const cars = [];
732	    if (R.playerCar) { cars.push(R.playerCar); }
733	    for (let i = 0; i < R.aiCars.length; i++) {
734	      cars.push(R.aiCars[i]);
735	    }
736	    return cars;
737	  }
