739	  /* ==========================================================================
740	     Car Physics (mirrors player physics)
741	     ========================================================================== */
742	
743	  /**
744	   * Apply the same car physics as the player to an AI car.
745	   * Updates ai.x, ai.z, ai.angle, ai.speed, ai.driftFactor.
746	   * @param {object} car — AI car (or player car shape)
747	   * @param {number} dt
748	   */
749	  function applyCarPhysics(car, dt) {
750	    const speed = car.speed || 0;
751	    const steer = car.steerAngle || 0;
752	    const handling = car.handling || 0.04;
753	
754	    if (speed < 0.01 && (R.input && R.input.throttle === 0)) {
755	      car.driftFactor = 0;
756	      return;
757	    }
758	
759	    /* Friction */
760	    const friction = 0.98;
761	    car.speed *= friction;
762	
763	    /* Drift physics */
764	    const steerStrength = steer * handling * speed * 0.5;
765	    car.driftFactor += steerStrength;
766	    car.driftFactor *= 0.96; // drift recovery
767	    car.driftFactor = clamp(car.driftFactor, -speed * 0.35, speed * 0.35);
768	
769	    /* Update angle */
770	    car.angle += car.driftFactor * dt * 3;
771	
772	    /* Update position */
773	    const forwardX = Math.sin(car.angle) * car.speed * dt * 60;
774	    const forwardZ = Math.cos(car.angle) * car.speed * dt * 60;
775	
776	    car.x += forwardX;
777	    car.z += forwardZ;
778	
779	    /* Update distance tracking */
780	    car.totalDistance = getTotalDistance(car);
781	
782	    /* Clamp speed */
783	    car.speed = clamp(car.speed, 0, car.maxSpeed * 1.15);
784	  }
