786	  /* ==========================================================================
787	     Lap / Checkpoint tracking
788	     ========================================================================== */
789	
790	  /**
791	   * Track lap progress and checkpoint crossing.
792	   * @param {object} ai
793	   */
794	  function updateAILapProgress(ai) {
795	    const tLen = trackLength();
796	    if (tLen <= 0) { return; }
797	
798	    /* Detect lap crossing */
799	    const prevZ = ai.prevWorldZ || ai.z;
800	    if (prevZ < tLen * 0.5 && ai.z >= tLen * 0.9) {
801	      /* Wrapped around? Check if close to track length */
802	    }
803	    if (ai.z >= tLen) {
804	      ai.lap = (ai.lap || 0) + 1;
805	      ai.z -= tLen;
806	      const total = R.track.totalLaps || 3;
807	      const segs = R.track.segments;
808	      if (!segs) return;
809	      if (ai.lap >= total) {
810	        ai.finished = true;
811	        ai.speed = 0;
812	      }
813	    } else if (ai.z < 0 && (ai.lap || 0) > 0) {
814	      /* Crossed finish line going forward */
815	      const total = R.track.totalLaps || 3;
816	      if (ai.lap >= total) {
817	        ai.finished = true;
818	        ai.speed = 0;
819	        ai.z = tLen;
820	      }
821	    }
822	    ai.prevWorldZ = ai.z;
823	  }
