826	     Off-track recovery
827	     ========================================================================== */
828	
829	  /**
830	   * Steer back toward the track when off-road.
831	   * @param {object} ai
832	   * @param {number} dt
833	   */
834	  function handleOffTrack(ai, dt) {
835	    const segInfo = getSegmentAtZ(ai.z);
836	    if (!segInfo) { return; }
837	
838	    const centerX = segInfo.segment.worldX !== undefined ? segInfo.segment.worldX : 400;
839	    const halfWidth = (segInfo.segment.width || 120) / 2;
840	    const distFromCenter = Math.abs(ai.x - centerX);
841	
842	    if (distFromCenter > halfWidth + 15) {
843	      ai.state = 'recovering';
844	      ai.recoveryTimer = Math.max(ai.recoveryTimer, 30);
845	      /* Reduce speed on rough ground */
846	      const offTrackPenalty = 1 - Math.min((distFromCenter - halfWidth) / 100, 0.6);
847	      ai.speed *= lerp(offTrackPenalty, 1, 0.1);
848	      /* Steer toward track center */
849	      const toCenter = centerX - ai.x;
850	      const steerCorrection = clamp(toCenter * 0.02, -0.5, 0.5);
851	      ai.steerAngle = lerp(ai.steerAngle, steerCorrection, 0.15);
852	    }
853	  }
