1040	    /* Name text with outline */
1041	    ctx.strokeStyle = '#000';
1042	    ctx.lineWidth = 2;
1043	    ctx.strokeText(name, sx, nameY);
1044	    ctx.fillStyle = '#fff';
1045	    ctx.fillText(name, sx, nameY);
