1057	      const pulseAlpha = 0.3 + Math.sin(pulsePhase) * 0.3;
1058	      ctx.strokeStyle = dotColor.replace(')', ', ' + pulseAlpha.toFixed(2) + ')')
1059	        .replace('rgb', 'rgba');
1060	      if (dotColor.startsWith('#')) {
