1154	  /**
1155	   * Convert world (x, z, y) to screen (x, y) with perspective scale.
1156	   * Uses the camera position to offset.
1157	   * @param {number} wx
1158	   * @param {number} wz
1159	   * @param {number} wy — elevation
1160	   * @returns {{ x: number, y: number, scale: number }}
1161	   */
1162	  function worldToScreenPos(wx, wz, wy) {
1163	    const cam = R.camera;
1164	    if (!cam) { return { x: wx, y: 400, scale: 1 }; }
1165	
1166	    const camX = cam.x || 0;
1167	    const camY = cam.y || 0;
1168	    const camZ = cam.z || 0;
1169	    const zoom = cam.zoom || 1;
1170	
1171	    /* Simple orthographic with perspective scaling */
1172	    const relX = wx - camX;
1173	    const relZ = wz - camZ;
1174	
1175	    /* Perspective scale: closer = bigger */
1176	    const perspectiveZ = Math.max(relZ, 1); // prevent division by zero
1177	    const scale = (400 / perspectiveZ) * zoom;
1178	    const clampedScale = clamp(scale, 0.3, 3.0);
1179	
1180	    /* Screen position */
1181	    const centerX = 1280 / 2;
1182	    const centerY = 720 / 2;
1183	    const sx = centerX + relX * clampedScale;
1184	    const sy = centerY - wy * clampedScale * 0.5 + 60; // slight vertical offset for car height
1185	
1186	    return { x: sx, y: sy, scale: clampedScale };
1187	  }
