1193	  /**
1194	   * Sort all cars (player + AI) by total distance traveled (descending).
1195	   * Accounts for lap count and z position.
1196	   * @returns {object[]} sorted array of car objects with position metadata
1197	   */
1198	  R.sortCarsByPosition = function() {
1199	    const cars = [];
1200	    if (R.playerCar) {
1201	      cars.push(R.playerCar);
1202	    }
1203	    for (let i = 0; i < R.aiCars.length; i++) {
1204	      cars.push(R.aiCars[i]);
1205	    }
1206	
1207	    /* Sort by total distance (descending — farther = higher position) */
1208	    cars.sort(function(a, b) {
1209	      const distA = getTotalDistance(a);
1210	      const distB = getTotalDistance(b);
1211	      if (distB !== distA) { return distB - distA; }
1212	      /* Tie-break: closer to center of track is slightly ahead */
1213	      const centerXA = a.segmentCenterX || 400;
1214	      const centerXB = b.segmentCenterX || 400;
1215	      const offA = Math.abs(a.x - centerXA);
1216	      const offB = Math.abs(b.x - centerXB);
1217	      return offA - offB;
1218	    });
1219	
1220	    return cars;
1221	  };
