20	// ─── Helpers ───────────────────────────────────────────────────────────────
21	
22	/**
23	 * Rotate a point (px, py) around origin (ox, oy) by angle (radians).
24	 */
25	R._rotatePoint = function(px, py, ox, oy, angle) {
26	  const cos = Math.cos(angle);
27	  const sin = Math.sin(angle);
28	  const dx = px - ox;
29	  const dy = py - oy;
30	  return {
31	    x: ox + dx * cos - dy * sin,
32	    y: oy + dx * sin + dy * cos
33	  };
34	};
35	
36	/**
37	 * Project polygon points onto an axis. Returns { min, max }.
38	 */
39	R._projectPolygon = function(points, axisX, axisY) {
40	  let min = Infinity;
41	  let max = -Infinity;
42	  for (let i = 0; i < points.length; i++) {
43	    const dot = points[i].x * axisX + points[i].y * axisY;
44	    if (dot < min) min = dot;
45	    if (dot > max) max = dot;
46	  }
47	  return { min, max };
48	};
49	
50	/**
51	 * Get the 4 corner points of a car as a rotated rectangle.
52	 * Car origin (x, y) is the center of the rectangle.
53	 */
54	R._getCarCorners = function(car) {
55	  const hw = R.CONFIG.CAR_WIDTH * 0.5;
56	  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
57	  const cx = car.x;
58	  const cy = car.y;
59	  const angle = car.angle || 0;
60	
61	  const local = [
62	    { x: -hw, y: -hh },
63	    { x:  hw, y: -hh },
64	    { x:  hw, y:  hh },
65	    { x: -hw, y:  hh }
66	  ];
67	
68	  const corners = [];
69	  for (let i = 0; i < 4; i++) {
70	    corners.push(R._rotatePoint(
71	      cx + local[i].x, cy + local[i].y, cx, cy, angle
72	    ));
73	  }
74	  return corners;
75	};
76	
77	/**
78	 * Get edge normals of a polygon for SAT (perpendicular to each edge, normalized).
79	 */
80	R._getNormals = function(corners) {
81	  const normals = [];
82	  for (let i = 0; i < corners.length; i++) {
83	    const j = (i + 1) % corners.length;
84	    const edgeX = corners[j].x - corners[i].x;
85	    const edgeY = corners[j].y - corners[i].y;
86	    const len = Math.sqrt(edgeX * edgeX + edgeY * edgeY);
87	    if (len < 0.0001) continue;
88	    normals.push({ x: -edgeY / len, y: edgeX / len });
89	  }
90	  return normals;
91	};
92	
93	/**
94	 * Overlap amount on an axis between two projections.
95	 * Positive = overlapping, negative/zero = separated.
96	 */
97	R._overlapOnAxis = function(projA, projB) {
98	  return Math.min(projA.max, projB.max) - Math.max(projA.min, projB.min);
99	};
100	
101	// ─── AABB ───────────────────────────────────────────────────────────────────
102	
103	/**
104	 * Axis-aligned bounding box for a car. Uses max extent of the rotated rectangle
105	 * (a conservative circle-bounds approximation).
106	 *
107	 * @param {Object} car — { x, y, angle }
108	 * @returns {{ minX: number, maxX: number, minY: number, maxY: number }}
109	 */
110	R.carAABB = function(car) {
111	  const hw = R.CONFIG.CAR_WIDTH * 0.5;
112	  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
113	  const angle = car.angle || 0;
114	  const absCos = Math.abs(Math.cos(angle));
115	  const absSin = Math.abs(Math.sin(angle));
116	  const radiusX = hw * absCos + hh * absSin;
117	  const radiusY = hw * absSin + hh * absCos;
118	
119	  return {
120	    minX: car.x - radiusX,
121	    maxX: car.x + radiusX,
122	    minY: car.y - radiusY,
123	    maxY: car.y + radiusY
124	  };
125	};
126	
127	/**
128	 * Test if two AABBs overlap.
129	 */
130	R._aabbOverlap = function(a, b) {
131	  return a.minX < b.maxX && a.maxX > b.minX && a.minY < b.maxY && a.maxY > b.minY;
132	};
133	
134	// ─── Car-to-Car Collision (SAT) ─────────────────────────────────────────────
135	
136	/**
137	 * Detailed collision detection between two cars using Separating Axis Theorem.
138	 * Each car is a 40x70 rotated rectangle.
139	 *
140	 * @param {Object} carA
141	 * @param {Object} carB
142	 * @returns {{ hit: boolean, overlapX: number, overlapY: number, depth: number } | null}
143	 */
144	R.checkCarToCar = function(carA, carB) {
145	  // Broad phase: AABB
146	  if (!R._aabbOverlap(R.carAABB(carA), R.carAABB(carB))) {
147	    return null;
148	  }
149	
150	  // Narrow phase: SAT
151	  const cornersA = R._getCarCorners(carA);
152	  const cornersB = R._getCarCorners(carB);
153	  const axes = R._getNormals(cornersA).concat(R._getNormals(cornersB));
154	
155	  let minOverlap = Infinity;
156	  let minAxisX = 0;
157	  let minAxisY = 0;
158	
159	  for (let i = 0; i < axes.length; i++) {
160	    const ax = axes[i].x;
161	    const ay = axes[i].y;
162	    const projA = R._projectPolygon(cornersA, ax, ay);
163	    const projB = R._projectPolygon(cornersB, ax, ay);
164	    const overlap = R._overlapOnAxis(projA, projB);
165	
166	    if (overlap <= 0) return null; // separating axis found
167	
168	    if (overlap < minOverlap) {
169	      minOverlap = overlap;
170	      minAxisX = ax;
171	      minAxisY = ay;
172	    }
173	  }
174	
175	  return {
176	    hit: true,
177	    overlapX: minAxisX * minOverlap,
178	    overlapY: minAxisY * minOverlap,
179	    depth: minOverlap
180	  };
181	};
182	
183	// ─── Collision Resolution ───────────────────────────────────────────────────
184	
185	/**
186	 * Resolve a collision between two cars: push apart and adjust velocities.
187	 *
188	 * Push ratios:
189	 *   - Both moving: 50% each
190	 *   - One stationary (speed < MIN_SPEED): stationary car gets 70% push,
191	 *     moving car takes 30%
192	 *
193	 * Velocity impulse:
194	 *   - Relative velocity along collision normal
195	 *   - Equal-mass damped exchange
196	 *   - COLLISION_DAMPING applied to both cars' speed
197	 *
198	 * @param {Object} carA
199	 * @param {Object} carB
200	 * @param {{ overlapX: number, overlapY: number, depth: number }} overlap
201	 */
202	R.resolveCollision = function(carA, carB, overlap) {
203	  const depth = overlap.depth;
204	  if (depth <= 0) return;
205	
206	  const speedA = Math.abs(carA.speed || 0);
207	  const speedB = Math.abs(carB.speed || 0);
208	  const aStationary = speedA < R.CONFIG.MIN_SPEED;
209	  const bStationary = speedB < R.CONFIG.MIN_SPEED;
210	
211	  // Determine push ratios
212	  let pushRatioA, pushRatioB;
213	  if (aStationary && !bStationary) {
214	    pushRatioA = 0.7; pushRatioB = 0.3;
215	  } else if (bStationary && !aStationary) {
216	    pushRatioA = 0.3; pushRatioB = 0.7;
217	  } else {
218	    pushRatioA = 0.5; pushRatioB = 0.5;
219	  }
220	
221	  // Push apart
222	  carA.x -= overlap.overlapX * pushRatioA;
223	  carA.y -= overlap.overlapY * pushRatioA;
224	  carB.x += overlap.overlapX * pushRatioB;
225	  carB.y += overlap.overlapY * pushRatioB;
226	
227	  // Velocity exchange
228	  const nx = overlap.overlapX / (depth || 0.001);
229	  const ny = overlap.overlapY / (depth || 0.001);
230	
231	  const vAx = Math.cos(carA.angle || 0) * (carA.speed || 0);
232	  const vAy = Math.sin(carA.angle || 0) * (carA.speed || 0);
233	  const vBx = Math.cos(carB.angle || 0) * (carB.speed || 0);
234	  const vBy = Math.sin(carB.angle || 0) * (carB.speed || 0);
235	
236	  const relVelN = (vAx - vBx) * nx + (vAy - vBy) * ny;
237	
238	  // Only resolve if cars are approaching
239	  if (relVelN > 0) {
240	    if (!aStationary && !bStationary) {
241	      // Equal-mass damped exchange: each car moves toward average speed
242	      const avgSpeed = (carA.speed + carB.speed) / 2;
243	      carA.speed = avgSpeed - (carA.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
244	      carB.speed = avgSpeed - (carB.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
245	    } else if (aStationary) {
246	      carB.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
247	      carA.speed = carB.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
248	    } else {
249	      carA.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
250	      carB.speed = carA.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
251	    }
252	
253	    // Both lose energy
254	    carA.speed *= R.CONFIG.COLLISION_DAMPING;
255	    carB.speed *= R.CONFIG.COLLISION_DAMPING;
256	  }
257	
258	  // Clamp tiny speeds to zero
259	  if (Math.abs(carA.speed) < R.CONFIG.MIN_SPEED * 0.5) carA.speed = 0;
260	  if (Math.abs(carB.speed) < R.CONFIG.MIN_SPEED * 0.5) carB.speed = 0;
261	};
