263	// ─── Boundary Checking ──────────────────────────────────────────────────────
264	
265	/**
266	 * Check if a car is off the track and apply penalties.
267	 *
268	 * - Uses R.isOnTrack(car.x, car.z) to determine track position
269	 * - Off track: applies OFFROAD_FRICTION (shallow) or OFFROAD_DEEP_PENALTY (deep)
270	 * - Deep off track (>50px from edge) + speed > 3: aggressive speed reduction
271	 * - Spawns dust particles via R.spawnDust()
272	 * - Sets car._offRoadSteerScale = 0.6 for reduced steering control
273	 *
274	 * @param {Object} car
275	 * @param {number} dt — delta time (seconds), unused but accepted for API compatibility
276	 */
277	R.checkCarToBoundary = function(car, dt) {
278	  if (typeof R.isOnTrack !== 'function') return;
279	
280	  const carZ = (car.z !== undefined) ? car.z : 0;
281	  if (R.isOnTrack(car.x, carZ)) {
282	    car._offTrack = false;
283	    car._offTrackDepth = 0;
284	    car._offRoadSteerScale = 1;
285	    return;
286	  }
287	
288	  // Off track — determine depth
289	  car._offTrack = true;
290	  const testOffset = R.CONFIG.OFFROAD_DEEP_THRESH;
291	  let deepOff;
292	
293	  if (typeof R.isOnTrack === 'function') {
294	    const probeX = car.x + (car.x > 0 ? -testOffset : testOffset);
295	    deepOff = !R.isOnTrack(probeX, carZ);
296	  } else {
297	    deepOff = false;
298	  }
299	
300	  car._offTrackDepth = deepOff ? R.CONFIG.OFFROAD_DEEP_THRESH + 1 : 30;
301	
302	  // Apply friction
303	  const friction = deepOff ? R.CONFIG.OFFROAD_DEEP_PENALTY : R.CONFIG.OFFROAD_FRICTION;
304	  car.speed *= friction;
305	
306	  // Aggressive scrubbing for fast cars deep off track
307	  if (deepOff && Math.abs(car.speed) > 3) {
308	    car.speed *= R.CONFIG.OFFROAD_DEEP_PENALTY;
309	  }
310	
311	  if (Math.abs(car.speed) < R.CONFIG.MIN_SPEED * 0.3) {
312	    car.speed = 0;
313	  }
314	
315	  // Dust particles
316	  if (typeof R.spawnDust === 'function' && Math.abs(car.speed) > 0.5) {
317	    R.spawnDust(car.x, car.y, deepOff ? 4 : 2);
318	  }
319	
320	  // Reduced steering off-road
321	  car._offRoadSteerScale = 0.6;
322	};
