324	// ─── Per-Frame Collision Check ──────────────────────────────────────────────
325	
326	/**
327	 * Main entry point. Called each frame during 'racing' phase.
328	 *
329	 * Pipeline:
330	 *   1. Gather active cars (player + AI)
331	 *   2. AABB broad phase → candidate pairs
332	 *   3. SAT narrow phase → confirmed collisions
333	 *   4. Sort by overlap depth (deepest first)
334	 *   5. Resolve each collision (push apart + impulse + effects)
335	 *   6. Re-check boundaries for all cars (collisions may push cars off track)
336	 *
337	 * Edge cases handled:
338	 *   - Multiple simultaneous collisions: resolved in depth order, max per car = 3
339	 *   - Very slow collisions: no sparks/sound, just positional nudging
340	 *   - One car stationary: push ratio biased toward stationary car
341	 *   - Car pushed off track: boundary re-check after resolution
342	 */
343	
344	// Debug/metrics (populated each frame)
345	R._lastCollisionInfo = null;
346	R._collisionCountThisFrame = 0;
347	
348	R.checkCollisions = function() {
349	  R._collisionCountThisFrame = 0;
350	  R._lastCollisionInfo = null;
351	
352	  if (R.state.phase !== 'racing') return;
353	
354	  // 1. Gather cars
355	  const cars = [];
356	  if (R.playerCar) cars.push(R.playerCar);
357	  if (R.aiCars && R.aiCars.length > 0) {
358	    for (let i = 0; i < R.aiCars.length; i++) cars.push(R.aiCars[i]);
359	  }
360	
361	  if (cars.length < 2) {
362	    for (let i = 0; i < cars.length; i++) R.checkCarToBoundary(cars[i], 0.016);
363	    return;
364	  }
365	
366	  // 2. AABB broad phase
367	  const aabbs = [];
368	  for (let i = 0; i < cars.length; i++) aabbs.push(R.carAABB(cars[i]));
369	
370	  const candidates = [];
371	  for (let i = 0; i < cars.length; i++) {
372	    for (let j = i + 1; j < cars.length; j++) {
373	      if (R._aabbOverlap(aabbs[i], aabbs[j])) {
374	        candidates.push({ a: cars[i], b: cars[j] });
375	      }
376	    }
377	  }
378	
379	  if (candidates.length === 0) {
380	    for (let i = 0; i < cars.length; i++) R.checkCarToBoundary(cars[i], 0.016);
381	    return;
382	  }
383	
384	  // 3. SAT narrow phase
385	  const collisions = [];
386	  for (let k = 0; k < candidates.length; k++) {
387	    const { a, b } = candidates[k];
388	    const result = R.checkCarToCar(a, b);
389	    if (result && result.hit) {
390	      collisions.push({ carA: a, carB: b, overlap: result, depth: result.depth });
391	    }
392	  }
393	
394	  R._collisionCountThisFrame = collisions.length;
395	  if (collisions.length === 0) {
396	    for (let i = 0; i < cars.length; i++) R.checkCarToBoundary(cars[i], 0.016);
397	    return;
398	  }
399	
400	  // 4. Sort deepest first
401	  collisions.sort(function(c1, c2) { return c2.depth - c1.depth; });
402	
403	  // 5. Resolve collisions
404	  const maxResolve = Math.min(collisions.length, R.CONFIG.MAX_SIMULTANEOUS);
405	  const resolvedCars = {};
406	  const involvedCarKeys = [];
407	
408	  for (let k = 0; k < maxResolve; k++) {
409	    const col = collisions[k];
410	
411	    const keyA = col.carA._id || 'player';
412	    const keyB = col.carB._id || 'ai_' + R.aiCars.indexOf(col.carB);
413	
414	    resolvedCars[keyA] = (resolvedCars[keyA] || 0) + 1;
415	    resolvedCars[keyB] = (resolvedCars[keyB] || 0) + 1;
416	
417	    // Limit per-car resolutions to prevent jitter
418	    if (resolvedCars[keyA] > 3 || resolvedCars[keyB] > 3) continue;
419	
420	    const speedA = Math.abs(col.carA.speed || 0);
421	    const speedB = Math.abs(col.carB.speed || 0);
422	    const avgSpeed = (speedA + speedB) / 2;
423	
424	    // Resolve
425	    R.resolveCollision(col.carA, col.carB, col.overlap);
426	
427	    // Effects
428	    const midpointX = (col.carA.x + col.carB.x) / 2;
429	    const midpointY = (col.carA.y + col.carB.y) / 2;
430	
431	    if (avgSpeed > R.CONFIG.SPARK_SPEED_THRESH) {
432	      const intensity = Math.min(avgSpeed / 20, 1);
433	      if (typeof R.spawnSparks === 'function') R.spawnSparks(midpointX, midpointY, intensity);
434	      if (typeof R.playSound === 'function') R.playSound('crash', intensity);
435	    } else if (avgSpeed > R.CONFIG.MIN_COLLISION_SPEED) {
436	      const intensity = avgSpeed / R.CONFIG.SPARK_SPEED_THRESH * 0.5;
437	      if (typeof R.spawnSparks === 'function') R.spawnSparks(midpointX, midpointY, intensity);
438	      if (typeof R.playSound === 'function') R.playSound('crash', intensity * 0.3);
439	    }
440	    // Below MIN_COLLISION_SPEED: no effects, just nudging
441	
442	    R._lastCollisionInfo = { carA: keyA, carB: keyB, depth: col.depth, avgSpeed: avgSpeed };
443	
444	    if (involvedCarKeys.indexOf(keyA) === -1) involvedCarKeys.push(keyA);
445	    if (involvedCarKeys.indexOf(keyB) === -1) involvedCarKeys.push(keyB);
446	  }
447	
448	  // 6. Boundary re-check for all cars (collisions may have pushed cars off track)
449	  const boundaryChecked = {};
450	
451	  // Check involved cars first
452	  for (let k = 0; k < maxResolve; k++) {
453	    const col = collisions[k];
454	    const keyA = col.carA._id || 'player';
455	    const keyB = col.carB._id || 'ai_' + R.aiCars.indexOf(col.carB);
456	
457	    if (!boundaryChecked[keyA]) {
458	      R.checkCarToBoundary(col.carA, 0.016);
459	      boundaryChecked[keyA] = true;
460	    }
461	    if (!boundaryChecked[keyB]) {
462	      R.checkCarToBoundary(col.carB, 0.016);
463	      boundaryChecked[keyB] = true;
464	    }
465	  }
466	
467	  // Then check remaining cars
468	  for (let i = 0; i < cars.length; i++) {
469	    const carKey = cars[i]._id || (cars[i] === R.playerCar ? 'player' : 'ai_' + R.aiCars.indexOf(cars[i]));
470	    if (!boundaryChecked[carKey]) {
471	      R.checkCarToBoundary(cars[i], 0.016);
472	      boundaryChecked[carKey] = true;
473	    }
474	  }
475	};
