297	    }
298	
299	    // Tick marks every 10 units (0 to maxSpeed+2)
300	    var tickStep = 10;
301	    var tickMax  = Math.ceil((maxSpeed + 2) / tickStep) * tickStep;
302	    for (var v = 0; v <= tickMax; v += tickStep) {
303	      var frac  = Math.min(v / maxSpeed, 1);
304	      var angle = a0 + (a1 - a0) * frac;
305	      var isMajor = (v % 40 === 0);
306	      var innerR  = isMajor ? r - 20 : r - 14;
307	      var outerR  = r - 5;
308	      var tx1 = cx + Math.cos(angle) * innerR;
309	      var ty1 = cy + Math.sin(angle) * innerR;
310	      var tx2 = cx + Math.cos(angle) * outerR;
311	      var ty2 = cy + Math.sin(angle) * outerR;
312	
313	      ctx.beginPath();
314	      ctx.moveTo(tx1, ty1);
315	      ctx.lineTo(tx2, ty2);
316	      ctx.strokeStyle = isMajor ? '#ddd' : '#777';
317	      ctx.lineWidth   = isMajor ? 2 : 1;
318	      ctx.stroke();
319	
320	      // Label every 40 units
321	      if (isMajor) {
322	        var lblR = r - 28;
323	        var lx   = cx + Math.cos(angle) * lblR;
324	        var ly   = cy + Math.sin(angle) * lblR;
325	        ctx.font         = 'bold 9px "Courier New", monospace';
326	        ctx.fillStyle    = '#ddd';
327	        ctx.textAlign    = 'center';
328	        ctx.textBaseline = 'middle';
329	        ctx.fillText(String(v), lx, ly);
330	      }
331	    }
332	
333	    // Needle
334	    var needleAngle = a0 + (a1 - a0) * speedFrac;
335	    var nx = cx + Math.cos(needleAngle) * nLen;
336	    var ny = cy + Math.sin(needleAngle) * nLen;
337	
338	    // Needle shadow
339	    ctx.beginPath();
340	    ctx.moveTo(cx + 1, cy + 1);
341	    ctx.lineTo(nx + 1, ny + 1);
342	    ctx.strokeStyle = 'rgba(0,0,0,0.4)';
343	    ctx.lineWidth   = 3;
344	    ctx.stroke();
345	
346	    // Needle
347	    ctx.beginPath();
348	    ctx.moveTo(cx, cy);
349	    ctx.lineTo(nx, ny);
350	    ctx.strokeStyle = '#ff3333';
351	    ctx.lineWidth   = 2.5;
352	    ctx.stroke();
353	
354	    // Center cap
355	    ctx.beginPath();
356	    ctx.arc(cx, cy, 6, 0, Math.PI * 2);
357	    ctx.fillStyle = '#ff3333';
358	    ctx.fill();
359	    ctx.beginPath();
360	    ctx.arc(cx, cy, 3, 0, Math.PI * 2);
361	    ctx.fillStyle = '#111';
362	    ctx.fill();
363	
364	    // Digital readout centered below
365	    var digiY = cy + r * 0.55;
366	    var speedKmh = Math.round(speed);
367	    ctx.font         = 'bold 22px "Courier New", monospace';
368	    ctx.fillStyle    = '#ffffff';
369	    ctx.textAlign    = 'center';
370	    ctx.textBaseline = 'top';
371	    ctx.fillText(speedKmh + ' km/h', cx, digiY);
372	
373	    // "SPEED" label
374	    ctx.font         = 'bold 10px Arial, sans-serif';
375	    ctx.fillStyle    = '#aaaaaa';
376	    ctx.textBaseline = 'top';
377	    ctx.fillText('SPEED', cx, digiY + 24);
378	
379	    ctx.restore();
380	  };
