384	  /**
385	   * R.renderPositionBadge()
386	   * Top-right corner. Show "1st / 6" with large bold position number.
387	   * Color-coded: 1st=gold, 2nd=silver, 3rd=bronze, rest=white.
388	   * Animate position changes with scale bounce.
389	   */
390	  R.renderPositionBadge = function () {
391	    var ctx = R.ctx;
392	    var px  = CFG.HUD.POS_BADGE_X;
393	    var py  = CFG.HUD.POS_BADGE_Y;
394	
395	    var player     = R.player;
396	    var totalCars  = R.cars ? R.cars.length : 1;
397	    var position   = 1;
398	    var playerIdx  = -1;
399	
400	    // Determine player position and index
401	    if (player && R.cars) {
402	      for (var i = 0; i < R.cars.length; i++) {
403	        if (R.cars[i] === player) {
404	          playerIdx = i;
405	          break;
406	        }
407	      }
408	      // Use sorted order if available
409	      var sorted = R.sortCarsByPosition ? R.sortCarsByPosition() : null;
410	      if (sorted && sorted.length > 0) {
411	        for (var s = 0; s < sorted.length; s++) {
412	          var entry = sorted[s];
413	          var idx   = entry._carIndex != null ? entry._carIndex : s;
414	          if (idx === playerIdx) {
415	            position = s + 1;
416	            break;
417	          }
418	        }
419	      }
420	    }
421	
422	    // Bounce scale
423	    var bounce = 1;
424	    if (playerIdx >= 0 && _bounceTimers[playerIdx]) {
425	      var tRemain = _bounceTimers[playerIdx];
426	      var tTotal  = 0.35;
427	      var t       = 1 - (tRemain / tTotal); // 0→1
428	      // Eased bounce: sin decay
429	      bounce = 1 + Math.sin(t * Math.PI) * 0.25 * (1 - t);
430	    }
431	
432	    // Color based on position
433	    var posColor = '#ffffff';
434	    if (position === 1) posColor = '#ffd700';
435	    else if (position === 2) posColor = '#c0c0c0';
436	    else if (position === 3) posColor = '#cd7f32';
437	
438	    // Ordinal suffix
439	    var suffix = 'th';
440	    if (position === 1) suffix = 'st';
441	    else if (position === 2) suffix = 'nd';
442	    else if (position === 3) suffix = 'rd';
443	
444	    ctx.save();
445	    ctx.translate(px, py);
446	    ctx.scale(bounce, bounce);
447	
448	    // Background panel
449	    var panelW = 120;
450	    var panelH = 72;
451	    ctx.fillStyle = 'rgba(0,0,0,0.55)';
452	    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
453	    ctx.lineWidth = 1.5;
454	    R._roundRect(ctx, -panelW / 2, 0, panelW, panelH, 8);
455	
456	    // Position number — large
457	    var posText = position + suffix;
458	    ctx.font         = 'bold 30px Arial, sans-serif';
459	    ctx.fillStyle    = posColor;
460	    ctx.textAlign    = 'center';
461	    ctx.textBaseline = 'top';
462	    // Dark outline for readability
463	    ctx.strokeStyle = 'rgba(0,0,0,0.7)';
464	    ctx.lineWidth   = 3;
465	    ctx.strokeText(posText, 0, 6);
466	    ctx.fillText(posText, 0, 6);
467	
468	    // "/ total" below
469	    ctx.font         = '14px Arial, sans-serif';
470	    ctx.fillStyle    = '#cccccc';
471	    ctx.textBaseline = 'top';
472	    ctx.lineWidth    = 1.5;
473	    ctx.strokeStyle  = 'rgba(0,0,0,0.6)';
474	    ctx.strokeText('/ ' + totalCars, 0, 40);
475	    ctx.fillText('/ ' + totalCars, 0, 40);
476	
477	    ctx.restore();
478	  };
