481	
482	  /**
483	   * R.renderLapCounter()
484	   * Below position badge. "LAP 2 / 3" with progress bar showing lap completion %.
485	   */
486	  R.renderLapCounter = function () {
487	    var ctx = R.ctx;
488	    var lx  = CFG.HUD.LAP_X;
489	    var ly  = CFG.HUD.LAP_Y;
490	    var bw  = CFG.HUD.LAP_BAR_WIDTH;
491	    var bh  = CFG.HUD.LAP_BAR_HEIGHT;
492	
493	    var player    = R.player;
494	    var track     = R.track;
495	    var totalLaps = (track && track.totalLaps) ? track.totalLaps : 3;
496	    var curLap    = player ? (player.lap || 1) : 1;
497	    // Clamp display lap
498	    var displayLap = Math.min(curLap, totalLaps);
499	
500	    // Estimate lap progress (0–1) based on checkpoint index and car x position
501	    var progress = 0;
502	    if (player && track && track.segments && track.segments.length > 0) {
503	      var segs = track.segments;
504	      // Simple progress: fraction of track based on player x vs total track length
505	      var segIdx  = player.checkpointIdx || 0;
506	      var clamped = Math.min(segIdx, segs.length - 1);
507	      // Approximate progress: segment index / total segments, plus sub-segment offset
508	      var subFrac = segs[clamped].worldX ? (player.x - segs[clamped].worldX) / (segs[clamped].width || 200) : 0;
509	      subFrac = Math.max(0, Math.min(subFrac, 1));
510	      progress = (clamped + subFrac) / segs.length;
511	    }
512	
513	    // Progress bar background
514	    var barX = lx - bw / 2;
515	    var barY = ly + 30;
516	
517	    ctx.save();
518	
519	    // "LAP" label
520	    ctx.font         = 'bold 12px Arial, sans-serif';
521	    ctx.fillStyle    = '#aaaaaa';
522	    ctx.textAlign    = 'center';
523	    ctx.textBaseline = 'top';
524	    ctx.fillText('LAP', lx, ly);
525	
526	    // Lap numbers
527	    ctx.font         = 'bold 26px Arial, sans-serif';
528	    ctx.fillStyle    = '#ffffff';
529	    ctx.textBaseline = 'top';
530	    ctx.lineWidth    = 2.5;
531	    ctx.strokeStyle  = 'rgba(0,0,0,0.6)';
532	    var lapText = displayLap + ' / ' + totalLaps;
533	    ctx.strokeText(lapText, lx, ly + 14);
534	    ctx.fillText(lapText, lx, ly + 14);
535	
536	    // Progress bar background
537	    ctx.fillStyle = 'rgba(60,60,60,0.7)';
538	    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
539	    ctx.lineWidth = 1;
540	    R._roundRect(ctx, barX, barY, bw, bh, bh / 2);
541	
542	    // Progress bar fill
543	    var fillW = Math.max(bh, bw * progress); // minimum = height (for rounded ends)
544	    var barColor = displayLap >= totalLaps ? '#22cc55' : '#4488ff';
545	    ctx.save();
546	    ctx.beginPath();
547	    R._roundRectPath(ctx, barX, barY, bw, bh, bh / 2);
548	    ctx.clip();
549	    ctx.fillStyle = barColor;
550	    R._roundRect(ctx, barX, barY, fillW, bh, bh / 2);
551	    ctx.restore();
552	
553	    // Outline the bar again over the fill
554	    ctx.strokeStyle = 'rgba(255,255,255,0.25)';
555	    ctx.lineWidth = 1;
556	    R._roundRectStroke(ctx, barX, barY, bw, bh, bh / 2);
557	
558	    ctx.restore();
559	  };
