561	  // ── Minimap ─────────────────────────────────────────────────────────
562	
563	  /**
564	   * R.renderMiniMap()
565	   * Bottom-right corner, 140x140 pixels.
566	   * Simplified track outline + all cars as dots + player as pulsing dot.
567	   */
568	  R.renderMiniMap = function () {
569	    var ctx  = R.ctx;
570	    var mx   = CFG.HUD.MINIMAP_X;
571	    var my   = CFG.HUD.MINIMAP_Y;
572	    var size = CFG.HUD.MINIMAP_SIZE;
573	
574	    // Draw onto offscreen canvas first
575	    var mCtx = _minimapCtx;
576	    var w = size, h = size;
577	
578	    // Clear offscreen
579	    mCtx.clearRect(0, 0, w, h);
580	
581	    // Background
582	    mCtx.fillStyle = 'rgba(10,10,10,0.8)';
583	    mCtx.fillRect(0, 0, w, h);
584	    mCtx.strokeStyle = 'rgba(255,255,255,0.2)';
585	    mCtx.lineWidth = 1.5;
586	    mCtx.strokeRect(0, 0, w, h);
587	
588	    // Compute track bounds
589	    var track = R.track;
590	    if (!track || !track.segments || track.segments.length === 0) {
591	      // Draw empty minimap to screen
592	      ctx.drawImage(_minimapCanvas, mx, my);
593	      return;
594	    }
595	
596	    var segs = track.segments;
597	    var minX = Infinity, maxX = -Infinity;
598	    var minY = Infinity, maxY = -Infinity;
599	    var points = [];
600	    for (var i = 0; i < segs.length; i++) {
601	      var sx = segs[i].worldX || 0;
602	      var sy = segs[i].worldY || 0;
603	      points.push({ x: sx, y: sy });
604	      if (sx < minX) minX = sx;
605	      if (sx > maxX) maxX = sx;
606	      if (sy < minY) minY = sy;
607	      if (sy > maxY) maxY = sy;
608	    }
609	
610	    // Pad bounds
611	    var rangeX = maxX - minX || 1;
612	    var rangeY = maxY - minY || 1;
613	    var maxRange = Math.max(rangeX, rangeY);
614	    // Ensure square aspect with padding
615	    var pad = maxRange * 0.12;
616	    minX -= pad; maxX += pad;
617	    minY -= pad; maxY += pad;
618	    rangeX = maxX - minX;
619	    rangeY = maxY - minY;
620	    maxRange = Math.max(rangeX, rangeY);
621	
622	    var margin = 12;
623	    var drawW  = w - margin * 2;
624	    var drawH  = h - margin * 2;
625	    var scale  = Math.min(drawW / maxRange, drawH / maxRange);
626	
627	    // Center offset
628	    var cxOff = margin + (drawW - rangeX * scale) / 2 - minX * scale;
629	    var cyOff = margin + (drawH - rangeY * scale) / 2 - minY * scale;
630	
631	    function toMapX(wx) { return cxOff + wx * scale; }
632	    function toMapY(wy) { return cyOff + wy * scale; }
633	
634	    // Draw track outline — thin polyline with subtle gradient segments
635	    mCtx.lineWidth = 2;
636	    mCtx.lineCap   = 'round';
637	    mCtx.lineJoin  = 'round';
638	
639	    for (var tSeg = 1; tSeg < points.length; tSeg++) {
640	      var p0 = points[tSeg - 1];
641	      var p1 = points[tSeg];
642	      var x0 = toMapX(p0.x), y0 = toMapY(p0.y);
643	      var x1 = toMapX(p1.x), y1 = toMapY(p1.y);
644	
645	      // Gradient based on track progress (lighter at start, dimmer toward end)
646	      var frac = tSeg / points.length;
647	      var gAlpha = 0.25 + frac * 0.35;
648	
649	      mCtx.beginPath();
650	      mCtx.moveTo(x0, y0);
651	      mCtx.lineTo(x1, y1);
652	      mCtx.strokeStyle = 'rgba(255,255,255,' + gAlpha.toFixed(2) + ')';
653	      mCtx.stroke();
654	    }
655	
656	    // Draw road width as subtle parallel lines
657	    mCtx.lineWidth = 1;
658	    for (var rSeg = 1; rSeg < points.length; rSeg++) {
659	      var rp0 = points[rSeg - 1];
660	      var rp1 = points[rSeg];
661	      var segW = (rp0.width || 30) * scale * 0.3;
662	      var dx = rp1.x - rp0.x;
663	      var dy = rp1.y - rp0.y;
664	      var len = Math.sqrt(dx * dx + dy * dy) || 1;
665	      var nx = -dy / len * segW;
666	      var ny =  dx / len * segW;
667	
668	      var mx0L = toMapX(rp0.x) + nx, my0L = toMapY(rp0.y) + ny;
669	      var mx0R = toMapX(rp0.x) - nx, my0R = toMapY(rp0.y) - ny;
670	      var mx1L = toMapX(rp1.x) + nx, my1L = toMapY(rp1.y) + ny;
671	      var mx1R = toMapX(rp1.x) - nx, my1R = toMapY(rp1.y) - ny;
672	
673	      mCtx.strokeStyle = 'rgba(255,255,255,0.1)';
674	      mCtx.beginPath();
675	      mCtx.moveTo(mx0L, my0L); mCtx.lineTo(mx1L, my1L);
676	      mCtx.moveTo(mx0R, my0R); mCtx.lineTo(mx1R, my1R);
677	      mCtx.stroke();
678	    }
679	
680	    // Draw all cars as dots
681	    var cars = R.cars || [];
682	    var playerIdx = -1;
683	    for (var c = 0; c < cars.length; c++) {
684	      if (cars[c] === R.player) { playerIdx = c; break; }
685	    }
686	
687	    for (var ci = 0; ci < cars.length; ci++) {
688	      var car = cars[ci];
689	      var cmx = toMapX(car.x || 0);
690	      var cmy = toMapY(car.y || 0);
691	
692	      if (ci === playerIdx) continue; // player drawn last
693	
694	      mCtx.beginPath();
695	      mCtx.arc(cmx, cmy, 3, 0, Math.PI * 2);
696	      mCtx.fillStyle = car.color || '#aaaaaa';
697	      mCtx.fill();
698	      mCtx.strokeStyle = 'rgba(0,0,0,0.5)';
699	      mCtx.lineWidth = 0.8;
700	      mCtx.stroke();
701	    }
702	
703	    // Draw player car as larger pulsing dot
704	    if (playerIdx >= 0 && R.player) {
705	      var pmx = toMapX(R.player.x || 0);
706	      var pmy = toMapY(R.player.y || 0);
707	      var pulse = 1 + Math.sin(R.state.time * 5) * 0.25;
708	      var pRad  = 5.5 * pulse;
709	
710	      // Outer glow
711	      mCtx.beginPath();
712	      mCtx.arc(pmx, pmy, pRad + 3, 0, Math.PI * 2);
713	      mCtx.fillStyle = 'rgba(255,255,100,0.15)';
714	      mCtx.fill();
715	
716	      // Main dot
717	      mCtx.beginPath();
718	      mCtx.arc(pmx, pmy, pRad, 0, Math.PI * 2);
719	      mCtx.fillStyle = '#ffff44';
720	      mCtx.fill();
721	      mCtx.strokeStyle = '#ffffff';
722	      mCtx.lineWidth = 1.2;
723	      mCtx.stroke();
724	    }
725	
726	    // Draw to screen
727	    ctx.drawImage(_minimapCanvas, mx, my);
728	
729	    // "MAP" label above the minimap
730	    ctx.font         = 'bold 10px Arial, sans-serif';
731	    ctx.fillStyle    = 'rgba(255,255,255,0.4)';
732	    ctx.textAlign    = 'left';
733	    ctx.textBaseline = 'bottom';
734	    ctx.fillText('MAP', mx + 2, my - 3);
735	  };
