782	      var bMil = Math.floor((_bestLapTime % 1) * 1000);
783	      var bestStr = 'BEST: ' + bMin + ':' +
784	        (bSec < 10 ? '0' : '') + bSec + '.' +
785	        (bMil < 100 ? (bMil < 10 ? '00' : '0') : '') + bMil;
786	
787	      ctx.font         = 'bold 12px "Courier New", monospace';
788	      ctx.fillStyle    = '#ffcc00';
789	      ctx.textBaseline = 'top';
790	      ctx.lineWidth    = 1.5;
791	      ctx.strokeStyle  = 'rgba(0,0,0,0.6)';
792	      ctx.strokeText(bestStr, tx, ty + 38);
