799	  // ── Drift Indicator ─────────────────────────────────────────────────
800	
801	  /**
802	   * R.renderDriftIndicator()
803	   * Bottom-center. Horizontal bar showing lateral G-force / drift.
804	   * Center = no drift. Extends left/right based on drift direction.
805	   */
806	  R.renderDriftIndicator = function () {
807	    var ctx = R.ctx;
808	    var dx  = CFG.HUD.DRIFT_X;
809	    var dy  = CFG.HUD.DRIFT_Y;
810	    var bw  = CFG.HUD.DRIFT_BAR_WIDTH;
811	    var bh  = CFG.HUD.DRIFT_BAR_HEIGHT;
812	
813	    var player = R.player;
814	    if (!player) return;
815	
816	    // Drift amount: use driftFactor or compute from speed & steer angle
817	    var driftAmt = 0;
818	    if (player.driftFactor !== undefined) {
819	      driftAmt = player.driftFactor;
820	    } else {
821	      // Approximate drift from steer angle and speed
822	      var steer = R.input ? R.input.steer : 0;
823	      var spd   = player.speed || 0;
824	      var maxSpd = player.maxSpeed || 200;
825	      driftAmt = steer * Math.min(spd / (maxSpd * 0.3), 1);
826	    }
827	    // Clamp to [-1, 1]
828	    driftAmt = Math.max(-1, Math.min(1, driftAmt));
829	
830	    var absDrift = Math.abs(driftAmt);
831	    var barHalf  = bw / 2;
832	
833	    ctx.save();
834	
835	    // Background bar (dark)
836	    var bgX = dx - barHalf;
837	    var bgY = dy;
838	    ctx.fillStyle = 'rgba(30,30,30,0.7)';
839	    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
840	    ctx.lineWidth = 1;
841	    R._roundRect(ctx, bgX, bgY, bw, bh, bh / 2);
842	
843	    // Center notch
844	    ctx.beginPath();
845	    ctx.moveTo(dx, bgY - 3);
846	    ctx.lineTo(dx, bgY + bh + 3);
