1147	   * _buildResultsTable()
1148	   * Internal: build the sorted results snapshot for the race-results overlay.
1149	   * @returns {Array<Object>} sorted list of result entries
1150	   */
1151	  function _buildResultsTable() {
1152	    var cars  = R.cars || [];
1153	    var track = R.track;
1154	    var totalLaps = (track && track.totalLaps) || 3;
1155	    var entries = [];
1156	
1157	    for (var i = 0; i < cars.length; i++) {
1158	      var car = cars[i];
1159	      var finished = car.finished || false;
1160	      var lap      = car.lap || 0;
1161	      var timeStr  = 'DNF';
1162	
1163	      if (finished) {
1164	        timeStr = _formatTime(car.finishTime || 0);
1165	      } else if (lap >= totalLaps) {
1166	        timeStr = 'DONE';
1167	      }
1168	
1169	      entries.push({
1170	        _carIndex:  i,
1171	        _isPlayer:  car === R.player,
1172	        _color:     car.color || '#aaaaaa',
1173	        _name:      car === R.player ? 'YOU' : (car.driverName || ('Car ' + (i + 1))),
1174	        _lap:       lap,
1175	        _finished:  finished,
1176	        _finishTime: car.finishTime || 0,
1177	        _timeStr:   timeStr
1178	      });
1179	    }
1180	
1181	    // Sort: finished cars first (by finishTime asc), then by lap desc, then by checkpoint/x
1182	    entries.sort(function (a, b) {
1183	      if (a._finished && b._finished) {
1184	        return a._finishTime - b._finishTime;
1185	      }
1186	      if (a._finished) return -1;
1187	      if (b._finished) return 1;
1188	      if (a._lap !== b._lap) return b._lap - a._lap;
1189	
1190	      var carA = R.cars[a._carIndex];
1191	      var carB = R.cars[b._carIndex];
1192	      var lapA = carA ? (carA.checkpointIdx || 0) : 0;
1193	      var lapB = carB ? (carB.checkpointIdx || 0) : 0;
1194	      if (lapA !== lapB) return lapB - lapA;
1195	
1196	      var xA = carA ? (carA.x || 0) : 0;
1197	      var xB = carB ? (carB.x || 0) : 0;
1198	      return xB - xA;
