1281	    r = Math.min(r, w / 2, h / 2);
1282	    ctx.beginPath();
1283	    ctx.moveTo(x + r, y);
1284	    ctx.lineTo(x + w - r, y);
1285	    ctx.arcTo(x + w, y, x + w, y + r, r);
1286	    ctx.lineTo(x + w, y + h - r);
1287	    ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
1288	    ctx.lineTo(x + r, y + h);
1289	    ctx.arcTo(x, y + h, x, y + h - r, r);
1290	    ctx.lineTo(x, y + r);
1291	    ctx.arcTo(x, y, x + r, y, r);
1292	    ctx.closePath();
