86	   */
87	  function randPick(arr) {
88	    return arr[randInt(0, arr.length - 1)];
89	  }
90	
91	  /**
92	   * Clamp a value between min and max.
93	   * @param {number} val
94	   * @param {number} min
95	   * @param {number} max
96	   * @returns {number}
97	   */
98	  function clamp(val, min, max) {
99	    return val < min ? min : (val > max ? max : val);
100	  }
101	
102	  /**
103	   * Linear interpolation between two hex-like colors by decomposing RGB channels.
104	   * Returns a CSS rgb() string for simplicity.
105	   * @param {string} c1 - hex color like '#FF8800'
106	   * @param {string} c2 - hex color like '#FF0000'
107	   * @param {number} t - blend factor 0..1
108	   * @returns {string} rgb() string
109	   */
110	  function lerpColor(c1, c2, t) {
111	    const r1 = parseInt(c1.slice(1, 3), 16);
112	    const g1 = parseInt(c1.slice(3, 5), 16);
113	    const b1 = parseInt(c1.slice(5, 7), 16);
114	    const r2 = parseInt(c2.slice(1, 3), 16);
115	    const g2 = parseInt(c2.slice(3, 5), 16);
116	    const b2 = parseInt(c2.slice(5, 7), 16);
117	    const r = Math.round(r1 + (r2 - r1) * t);
118	    const g = Math.round(g1 + (g2 - g1) * t);
119	    const b = Math.round(b1 + (b2 - b1) * t);
120	    return 'rgb(' + r + ',' + g + ',' + b + ')';
121	  }
122	
123	  /**
124	   * Return a spark color based on life ratio (1.0 = newborn → 0.0 = dying).
125	   * Early life: bright yellow-white; mid: orange; late: red; end: dark red.
126	   * @param {number} t - life ratio 0..1
127	   * @returns {string} hex color
128	   */
129	  function sparkColorByLife(t) {
130	    const idx = Math.floor((1 - t) * (SPARK_COLORS.length - 1));
131	    return SPARK_COLORS[clamp(idx, 0, SPARK_COLORS.length - 1)];
132	  }
133	
134	  /**
135	   * Return a smoke color based on life ratio (newborn light gray → dying darker).
136	   * @param {number} t - life ratio 0..1
137	   * @returns {string} hex color
138	   */
139	  function smokeColorByLife(t) {
140	    const idx = Math.floor(t * (SMOKE_COLORS.length - 1));
141	    return SMOKE_COLORS[clamp(idx, 0, SMOKE_COLORS.length - 1)];
142	  }
