145	  // Particle pool
146	  // ──────────────────────────────────────────────
147	
148	  /** @type {number} Next spawn slot in the pool (cyclic). */
149	  let _nextSpawnIndex = 0;
150	
151	  /**
152	   * Create a dead particle template.
153	   * @returns {Object}
154	   */
155	  function createDeadParticle() {
156	    return {
157	      x: 0,
158	      y: 0,
159	      vx: 0,
160	      vy: 0,
161	      life: 0,
162	      maxLife: 0,
163	      size: 0,
164	      color: '#000',
165	      alpha: 0,
166	      type: 'spark'   // 'spark' | 'smoke' | 'dust' | 'debris'
167	    };
168	  }
169	
170	  /**
171	   * Initialize the particle pool.
172	   * Pre-allocate R.particles with MAX_PARTICLES dead particles.
173	   * Safe to call multiple times — clears and rebuilds the pool.
174	   */
175	  R.initEffects = function() {
176	    const max = R.CONFIG.MAX_PARTICLES;
177	    R.particles = new Array(max);
178	    for (let i = 0; i < max; i++) {
179	      R.particles[i] = createDeadParticle();
180	    }
181	    _nextSpawnIndex = 0;
182	    R._shakeIntensity = 0;
183	    R._shakeDuration = 0;
184	    R._shakeTimer = 0;
185	  };
186	
187	  /**
188	   * Activate a dead particle from the pool and configure it.
189	   * If no dead particle is available, recycle the oldest one (cyclic overwrite).
190	   *
191	   * @param {number} x - world/screen X position
192	   * @param {number} y - world/screen Y position
193	   * @param {Object} config
194	   * @param {number} [config.vx] - horizontal velocity; random if omitted
195	   * @param {number} [config.vy] - vertical velocity; random if omitted
196	   * @param {number} [config.vxRange] - if vx omitted, random range [-vxRange, vxRange]
197	   * @param {number} [config.vyRange] - if vy omitted, random range [-vyRange, vyRange]
198	   * @param {number} config.life - particle lifetime in frames
199	   * @param {number} config.size - particle size in px
200	   * @param {string} config.color - fill color (hex or rgb)
201	   * @param {string} [config.type='spark'] - particle type
202	   * @param {number} [config.alpha=1] - starting alpha
203	   * @returns {Object|null} the activated particle, or null if pool is empty (should not happen)
204	   */
205	  R.spawnParticle = function(x, y, config) {
206	    if (!R.particles || R.particles.length === 0) return null;
207	
208	    const max = R.particles.length;
209	    let p = null;
210	
211	    // Strategy 1: find the first dead particle starting from the current
212	    // write-pointer position (avoids always scanning from index 0).
213	    for (let attempt = 0; attempt < max; attempt++) {
214	      const idx = (_nextSpawnIndex + attempt) % max;
215	      if (R.particles[idx].life <= 0) {
216	        p = R.particles[idx];
217	        _nextSpawnIndex = (idx + 1) % max;
218	        break;
219	      }
220	    }
221	
222	    // Strategy 2: all particles are alive — recycle the oldest (cyclic write pointer).
223	    if (!p) {
224	      p = R.particles[_nextSpawnIndex];
225	      _nextSpawnIndex = (_nextSpawnIndex + 1) % max;
226	    }
227	
228	    // Configure particle
229	    p.x = x;
230	    p.y = y;
231	    p.vx = config.vx !== undefined ? config.vx : randRange(-(config.vxRange || 3), config.vxRange || 3);
232	    p.vy = config.vy !== undefined ? config.vy : randRange(-(config.vyRange || 3), config.vyRange || 3);
233	    p.life = config.life || 30;
234	    p.maxLife = config.life || 30;
235	    p.size = config.size || 3;
236	    p.color = config.color || '#FFFFFF';
237	    p.alpha = config.alpha !== undefined ? config.alpha : 1.0;
238	    p.type = config.type || 'spark';
239	
240	    return p;
241	  };
