243	  /**
244	   * Spawn a burst of spark particles.
245	   * Each spark: small (2-4px), bright yellow/orange, high velocity in a random direction,
246	   * short life (20-40 frames), colors cycle from yellow → orange → red → dark.
247	   *
248	   * @param {number} x - origin X
249	   * @param {number} y - origin Y
250	   * @param {number} count - number of spark particles to spawn
251	   */
252	  R.spawnSparks = function(x, y, count) {
253	    for (let i = 0; i < count; i++) {
254	      const angle = randRange(0, Math.PI * 2);
255	      const speed = randRange(2, 8);
256	      const life = randInt(20, 40);
257	      const size = randRange(2, 4);
