297	  /**
298	   * Spawn dust particles (off-road / grass kick-up).
299	   * Each: brown/tan, medium size (3-6px), low velocity, medium-short life (20-50 frames).
300	   *
301	   * @param {number} x - origin X
302	   * @param {number} y - origin Y
303	   * @param {number} count - number of dust particles to spawn
304	   */
305	  R.spawnDust = function(x, y, count) {
306	    for (let i = 0; i < count; i++) {
307	      const life = randInt(20, 50);
308	      const size = randRange(3, 6);
309	
310	      R.spawnParticle(x, y, {
311	        vx: randRange(-1.5, 1.5),
312	        vy: randRange(-2.0, 0.2),    // slight upward bias
313	        life: life,
