322	  /**
323	   * Spawn tire smoke during drifting from both rear wheel positions.
324	   * Two plumes from rear wheel positions offset from car center.
325	   * intensity affects spawn rate and particle count (~1-6 particles per plume per call).
326	   *
327	   * @param {number} carX - car center X (world)
328	   * @param {number} carY - car center Y (world)
329	   * @param {number} carAngle - car heading angle in radians
330	   * @param {number} intensity - 0..1 drift intensity (0 = no drift, 1 = full lock)
331	   */
332	  R.spawnDriftSmoke = function(carX, carY, carAngle, intensity) {
333	    if (intensity <= 0.02) return;   // negligible — skip
334	
335	    // Rear wheel positions relative to car center
336	    const rearOffset = 35;   // px behind center
337	    const wheelSpan = 22;    // px left/right of center
338	
339	    const cosA = Math.cos(carAngle);
340	    const sinA = Math.sin(carAngle);
341	
342	    // Rear-left wheel world position
343	    const rlX = carX - rearOffset * cosA - wheelSpan * sinA;
344	    const rlY = carY - rearOffset * sinA + wheelSpan * cosA;
345	
346	    // Rear-right wheel world position
347	    const rrX = carX - rearOffset * cosA + wheelSpan * sinA;
348	    const rrY = carY - rearOffset * sinA - wheelSpan * cosA;
349	
350	    // Particle count per plume scales with intensity
351	    const baseCount = Math.floor(intensity * 6) + 1;
352	
353	    for (let plume = 0; plume < 2; plume++) {
354	      const px = plume === 0 ? rlX : rrX;
355	      const py = plume === 0 ? rlY : rrY;
356	      const count = baseCount + randInt(0, 2);
357	
358	      for (let i = 0; i < count; i++) {
359	        const life = randInt(30, 60);
360	        const size = randRange(4, 10);
361	
362	        // Drift smoke billows outward from the drift direction
363	        const spreadAngle = carAngle + Math.PI / 2 + randRange(-0.6, 0.6);
364	        const spreadSpeed = randRange(0.5, 2.0) * intensity;
365	
366	        R.spawnParticle(px + randRange(-4, 4), py + randRange(-4, 4), {
367	          vx: Math.cos(spreadAngle) * spreadSpeed,
368	          vy: Math.sin(spreadAngle) * spreadSpeed - randRange(0.3, 1.0),   // slight upward
369	          life: life,
370	          size: size,
371	          color: randPick(DRIFT_SMOKE_COLORS),
372	          type: 'smoke',
373	          alpha: randRange(0.3, 0.55) * intensity
374	        });
375	      }
376	    }
377	  };
