408	  // ──────────────────────────────────────────────
409	  // Particle update
410	  // ──────────────────────────────────────────────
411	
412	  /**
413	   * Update all alive particles.
414	   * Called each frame from the game loop.
415	   *
416	   * Steps:
417	   *  1. Decrement life by dt * 60 (normalize to ~60fps frame ticks)
418	   *  2. Update position: x += vx * dt * 60, y += vy * dt * 60
419	   *  3. Apply gravity to smoke / debris types: vy -= gravity
420	   *  4. Fade alpha based on life/maxLife ratio
421	   *  5. Mark dead if life <= 0
422	   *
423	   * @param {number} dt - delta time in seconds
424	   */
425	  R.updateEffects = function(dt) {
426	    if (!R.particles || R.particles.length === 0) return;
427	
428	    const frameScale = dt * 60;   // normalize to 60fps equivalent
429	    const gravity = R.CONFIG.PARTICLE_GRAVITY;
430	    const particles = R.particles;
431	    const len = particles.length;
432	
433	    for (let i = 0; i < len; i++) {
434	      const p = particles[i];
435	      if (p.life <= 0) continue;   // dead particle, skip
436	
437	      // 1. Decrement life
438	      p.life -= frameScale * 1;    // life measured in frame-ticks
439	
440	      // 2. Update position
441	      p.x += p.vx * frameScale;
442	      p.y += p.vy * frameScale;
443	
444	      // 3. Apply gravity for affected types
445	      if (p.type === 'smoke' || p.type === 'debris') {
446	        p.vy += gravity * frameScale;
447	      }
448	
449	      // 4. Fade alpha
450	      const lifeRatio = p.life / p.maxLife;
451	      if (p.type === 'smoke') {
452	        // Smoke fades out in the last 40% of its life
453	        p.alpha = lifeRatio > 0.4 ? p.alpha : (p.alpha * (lifeRatio / 0.4));
454	      } else if (p.type === 'dust') {
455	        // Dust fades smoothly
456	        p.alpha = lifeRatio * 0.7;
457	      } else {
458	        // Sparks / debris: hold alpha then fade sharply at end
459	        p.alpha = lifeRatio > 0.3 ? 1.0 : lifeRatio / 0.3;
460	      }
461	
462	      // 5. Mark dead
463	      if (p.life <= 0) {
464	        p.life = 0;
465	        p.alpha = 0;
466	      }
467	    }
468	
469	    // Update screen shake
470	    R.updateScreenShake(dt);
471	  };
472	
473	  // ──────────────────────────────────────────────
474	  // Particle rendering
475	  // ──────────────────────────────────────────────
476	
477	  /**
478	   * Render all alive particles.
479	   * Called each frame from the game loop.
480	   * For each alive particle:
481	   *   - Set ctx.globalAlpha = particle.alpha
482	   *   - Set ctx.fillStyle based on particle type and life ratio
483	   *   - Draw as small circle (spark, smoke, dust) or square (debris)
484	   *   - Reset globalAlpha to 1.0
485	   */
486	  R.renderEffects = function() {
487	    if (!R.particles || R.particles.length === 0) return;
488	
489	    const ctx = R.ctx;
490	    const particles = R.particles;
491	    const len = particles.length;
492	    let aliveCount = 0;
493	
494	    ctx.save();
495	
496	    for (let i = 0; i < len; i++) {
497	      const p = particles[i];
498	      if (p.life <= 0 || p.alpha <= 0.005) continue;   // skip dead or invisible
499	
500	      aliveCount++;
501	
502	      const lifeRatio = clamp(p.life / p.maxLife, 0, 1);
503	
504	      // Determine color based on particle type
505	      let color;
506	      switch (p.type) {
507	        case 'spark':
508	          color = sparkColorByLife(lifeRatio);
509	          break;
510	        case 'smoke':
511	          color = smokeColorByLife(lifeRatio);
512	          break;
513	        case 'dust':
514	          color = p.color;    // dust uses its assigned color, just fades alpha
515	          break;
516	        case 'debris':
517	          color = p.color;
518	          break;
519	        default:
520	          color = p.color;
521	      }
522	
523	      ctx.globalAlpha = clamp(p.alpha, 0, 1);
524	      ctx.fillStyle = color;
525	
526	      const halfSize = p.size / 2;
527	
528	      switch (p.type) {
529	        case 'spark':
530	          // Small bright circle, sometimes with a glow
531	          ctx.beginPath();
532	          ctx.arc(p.x, p.y, halfSize, 0, Math.PI * 2);
533	          ctx.fill();
534	          // Tiny glow for bright sparks
535	          if (lifeRatio > 0.5 && p.size >= 3) {
536	            ctx.globalAlpha = clamp(p.alpha * 0.35, 0, 1);
537	            ctx.beginPath();
538	            ctx.arc(p.x, p.y, halfSize * 2, 0, Math.PI * 2);
539	            ctx.fill();
540	          }
541	          break;
542	
543	        case 'smoke':
544	          // Soft round puff
545	          ctx.beginPath();
546	          ctx.arc(p.x, p.y, halfSize, 0, Math.PI * 2);
547	          ctx.fill();
548	          break;
549	
550	        case 'dust':
551	          // Small irregular — use a filled circle, optionally a little scatter
552	          ctx.beginPath();
553	          ctx.arc(p.x, p.y, halfSize, 0, Math.PI * 2);
554	          ctx.fill();
555	          break;
556	
557	        case 'debris':
558	          // Small square / rectangle oriented randomly
559	          ctx.fillRect(p.x - halfSize, p.y - halfSize * 0.6, p.size, p.size * 0.6);
560	          break;
561	
562	        default:
563	          ctx.beginPath();
564	          ctx.arc(p.x, p.y, halfSize, 0, Math.PI * 2);
565	          ctx.fill();
566	      }
567	    }
568	
569	    ctx.restore();
570	    // Always reset globalAlpha
571	    ctx.globalAlpha = 1.0;
572	
573	    return aliveCount;
574	  };
