576	  // ──────────────────────────────────────────────
577	  // Screen shake
578	  // ──────────────────────────────────────────────
579	
580	  /**
581	   * Trigger a screen shake effect.
582	   *
583	   * @param {number} intensity - max pixel offset (e.g. 4 = up to 4px shake)
584	   * @param {number} [duration=15] - shake duration in frames (~0.25s at 60fps)
585	   */
586	  R.triggerScreenShake = function(intensity, duration) {
587	    if (!intensity || intensity <= 0) return;
588	
589	    const dur = duration || 15;
590	
591	    // If already shaking with higher intensity, don't downgrade
592	    if (R._shakeTimer > 0 && R._shakeIntensity > intensity) {
593	      // Keep the existing stronger shake
594	      return;
595	    }
596	
597	    R._shakeIntensity = clamp(intensity, 0, R.CONFIG.SHAKE_MAX_OFFSET);
598	    R._shakeDuration = dur;
599	    R._shakeTimer = dur;
600	  };
601	
602	  /**
603	   * Update screen shake state — decay intensity over time.
604	   * Called automatically from R.updateEffects().
605	   *
606	   * @param {number} dt - delta time in seconds
607	   */
608	  R.updateScreenShake = function(dt) {
609	    if (!R._shakeTimer || R._shakeTimer <= 0) {
610	      R._shakeIntensity = 0;
611	      R._shakeOffsetX = 0;
612	      R._shakeOffsetY = 0;
613	      return;
614	    }
615	
616	    const frameScale = dt * 60;
617	    R._shakeTimer -= frameScale;
618	
619	    if (R._shakeTimer <= 0) {
620	      R._shakeIntensity = 0;
621	      R._shakeOffsetX = 0;
622	      R._shakeOffsetY = 0;
623	      R._shakeTimer = 0;
624	      return;
625	    }
626	
627	    // Decay factor: intensity ramps down linearly
628	    const decay = R._shakeTimer / R._shakeDuration;
629	    const currentIntensity = R._shakeIntensity * decay;
630	
631	    // Random offset within current intensity range; changes each frame for jitter
632	    R._shakeOffsetX = randRange(-currentIntensity, currentIntensity);
633	    R._shakeOffsetY = randRange(-currentIntensity, currentIntensity);
634	  };
635	
636	  /**
637	   * Apply screen shake offset to the canvas transform.
638	   * Call this in the render pipeline before drawing world objects,
639	   * or apply the offset manually to R.camera.
640	   *
641	   * Returns the current shake offsets { x, y } so the caller can apply them.
642	   *
643	   * @returns {{x: number, y: number}}
644	   */
645	  R.getScreenShakeOffset = function() {
646	    return {
647	      x: R._shakeOffsetX || 0,
648	      y: R._shakeOffsetY || 0
649	    };
650	  };
651	
652	  /**
653	   * Legacy / compatibility wrapper: directly applies shake via ctx.translate.
654	   * Use getScreenShakeOffset + manual application in the render pipeline
655	   * for more control. This is a convenience method.
656	   */
657	  R.renderScreenShake = function() {
658	    if (!R._shakeTimer || R._shakeTimer <= 0) return;
659	
660	    const offset = R.getScreenShakeOffset();
661	    if (offset.x !== 0 || offset.y !== 0) {
662	      R.ctx.translate(offset.x, offset.y);
663	    }
664	  };
665	
666	  // ──────────────────────────────────────────────
667	  // Speed lines
668	  // ──────────────────────────────────────────────
669	
670	  /**
671	   * Render speed lines at screen edges when the player is at high speed.
672	   * Lines streak backward to create a speed-sensation effect.
673	   *
674	   * Requires: R.playerCar (the player's car object with .speed and .maxSpeed).
675	   * Safe to call even if playerCar is not ready — returns silently.
676	   */
677	  R.renderSpeedLines = function() {
678	    const car = R.playerCar;
679	    if (!car || !car.maxSpeed) return;
680	
681	    const speedRatio = car.speed / car.maxSpeed;
682	    if (speedRatio < R.CONFIG.SPEED_LINES_THRESHOLD) return;
683	
684	    const ctx = R.ctx;
685	    const w = R.canvas.width;
686	    const h = R.canvas.height;
687	
688	    // Intensity 0..1 based on speed above threshold
689	    const intensity = (speedRatio - R.CONFIG.SPEED_LINES_THRESHOLD) /
690	                      (1.0 - R.CONFIG.SPEED_LINES_THRESHOLD);
691	
692	    const lineCount = Math.floor(intensity * 18) + 4;
693	    const maxLength = intensity * 120 + 30;
694	    const minLength = maxLength * 0.3;
695	
696	    ctx.save();
697	
698	    // Lines run horizontally, concentrated near top and bottom edges
699	    for (let i = 0; i < lineCount; i++) {
700	      const topEdge = Math.random() < 0.5;
701	      const y = topEdge
702	        ? randRange(0, h * 0.08)                          // near top
703	        : randRange(h * 0.92, h);                          // near bottom
704	
705	      const length = randRange(minLength, maxLength);
706	      const xStart = randRange(0, w);
707	      const xEnd = xStart - length;                        // streak left (backward)
708	
709	      const alpha = randRange(0.08, 0.22) * intensity;
710	      const lineWidth = randRange(1, 2.5);
711	
712	      ctx.globalAlpha = alpha;
713	      ctx.strokeStyle = '#FFFFFF';
714	      ctx.lineWidth = lineWidth;
715	      ctx.lineCap = 'round';
716	
717	      ctx.beginPath();
718	      ctx.moveTo(xStart, y);
719	      ctx.lineTo(xEnd, y);
720	      ctx.stroke();
721	
722	      // Occasionally add a slightly wider, more transparent glow line
723	      if (Math.random() < 0.3) {
724	        ctx.globalAlpha = alpha * 0.4;
725	        ctx.lineWidth = lineWidth * 3;
726	        ctx.beginPath();
727	        ctx.moveTo(xStart, y);
728	        ctx.lineTo(xEnd, y);
729	        ctx.stroke();
730	      }
731	    }
732	
733	    ctx.restore();
734	    ctx.globalAlpha = 1.0;
735	  };
