737	  // ──────────────────────────────────────────────
738	  // Exhaust particles (engine running)
739	  // ──────────────────────────────────────────────
740	
741	  /**
742	   * Spawn exhaust particles behind a car.
743	   * Called each frame for every active car during racing.
744	   *
745	   * @param {number} carX - car center X (world)
746	   * @param {number} carY - car center Y (world)
747	   * @param {number} carAngle - car heading angle in radians
748	   * @param {number} throttle - 0..1 throttle amount
749	   * @param {number} speed - current car speed (used to reduce exhaust at speed)
750	   * @param {number} maxSpeed - car's maximum speed
751	   */
752	  R.spawnExhaust = function(carX, carY, carAngle, throttle, speed, maxSpeed) {
753	    if (throttle <= 0.05) return;
754	
755	    // Exhaust decreases at very high speeds (less visible)
756	    const speedRatio = maxSpeed > 0 ? speed / maxSpeed : 0;
757	    const exhaustFactor = throttle * (1 - speedRatio * 0.6);
758	
759	    if (exhaustFactor < 0.1) return;
760	
761	    // Exhaust comes from behind the car
762	    const rearOffset = 30;
763	    const exhaustX = carX - Math.cos(carAngle) * rearOffset;
764	    const exhaustY = carY - Math.sin(carAngle) * rearOffset;
765	
766	    const count = Math.floor(exhaustFactor * 3) + 1;
767	
768	    for (let i = 0; i < count; i++) {
769	      const life = randInt(25, 50);
770	      const size = randRange(3, 7);
771	
772	      R.spawnParticle(exhaustX + randRange(-6, 6), exhaustY + randRange(-3, 3), {
773	        vx: -Math.cos(carAngle) * randRange(0.2, 0.8) + randRange(-0.2, 0.2),
774	        vy: -Math.sin(carAngle) * randRange(0.2, 0.8) - randRange(0.5, 1.2),
775	        life: life,
776	        size: size,
777	        color: randPick(SMOKE_COLORS.slice(3, 8)),   // mid-to-dark grays
778	        type: 'smoke',
779	        alpha: randRange(0.15, 0.35) * exhaustFactor
780	      });
781	    }
782	  };
