784	  // ──────────────────────────────────────────────
785	  // Collision burst (called on car-to-car or car-to-wall impact)
786	  // ──────────────────────────────────────────────
787	
788	  /**
789	   * Spawn a combined spark+debris burst at the impact point.
790	   * Also triggers screen shake proportional to impact force.
791	   *
792	   * @param {number} x - impact position X
793	   * @param {number} y - impact position Y
794	   * @param {number} force - 0..1 impact severity
795	   */
796	  R.spawnCollisionBurst = function(x, y, force) {
797	    const clampedForce = clamp(force, 0, 1);
798	
799	    const sparkCount = Math.floor(clampedForce * 25) + 5;
800	    const debrisCount = Math.floor(clampedForce * 10) + 2;
801	    const shakeIntensity = clampedForce * 8;
802	
803	    R.spawnSparks(x, y, sparkCount);
804	    R.spawnDebris(x, y, debrisCount);
805	    R.triggerScreenShake(shakeIntensity, Math.floor(clampedForce * 25) + 5);
806	  };
