809	  // Off-road particle burst
810	  // ──────────────────────────────────────────────
811	
812	  /**
813	   * Spawn dust particles when a car goes off the track surface.
814	   * Call rate-limited (e.g. every 2-3 frames) from the car update logic.
815	   *
816	   * @param {number} x - car position X
817	   * @param {number} y - car position Y
818	   * @param {number} speed - current car speed for intensity scaling
819	   * @param {number} maxSpeed - car max speed
820	   */
821	  R.spawnOffRoadDust = function(x, y, speed, maxSpeed) {
822	    const speedRatio = maxSpeed > 0 ? clamp(speed / maxSpeed, 0, 1) : 0;
823	    const count = Math.floor(speedRatio * 8) + 1;
824	
825	    R.spawnDust(x, y, count);
826	  };
