832	  /**
833	   * Return the count of alive particles currently in the pool.
834	   * Useful for debug overlays and performance monitoring.
835	   *
836	   * @returns {number}
837	   */
838	  R.getAliveParticleCount = function() {
839	    if (!R.particles) return 0;
840	    let count = 0;
841	    for (let i = 0; i < R.particles.length; i++) {
842	      if (R.particles[i].life > 0) count++;
843	    }
844	    return count;
845	  };
846	
847	  /**
848	   * Return pool utilization as a fraction (0..1).
849	   * @returns {number}
850	   */
851	  R.getPoolUtilization = function() {
852	    if (!R.particles || R.particles.length === 0) return 0;
853	    return R.getAliveParticleCount() / R.particles.length;
854	  };
