856	  /**
857	   * Kill all particles and reset screen shake.
858	   * Useful when resetting the race or returning to menu.
859	   */
860	  R.clearAllEffects = function() {
861	    if (R.particles) {
862	      for (let i = 0; i < R.particles.length; i++) {
863	        R.particles[i].life = 0;
864	        R.particles[i].alpha = 0;
865	      }
866	    }
867	    _nextSpawnIndex = 0;
868	    R._shakeTimer = 0;
869	    R._shakeIntensity = 0;
870	    R._shakeOffsetX = 0;
871	    R._shakeOffsetY = 0;
872	  };
