6	// Internal module state (closure-scoped, not on R)
7	// ---------------------------------------------------------------------------
8	
9	/** @type {AudioContext|null} */
10	let _ctx = null;
11	
12	/** @type {GainNode|null} — master gain, connected to destination */
13	let _masterGain = null;
14	
15	/** @type {boolean} */
16	let _muted = false;
17	
18	/** @type {number} — saved volume level before muting, so toggleMute can restore */
19	let _preMuteVolume = 0.7;
20	
21	/** @type {boolean} — true once initAudio succeeds; guards against operations on dead context */
22	let _initialized = false;
