24	// ---- Oscillator pool (reuse for one-shot sounds) ----
25	/** @type {OscillatorNode[]} */
26	let _oscPool = [];
27	const _MAX_OSC_POOL = 16;       // pre-allocate this many oscillators
28	
29	/** @type {GainNode[]} */
30	let _gainPool = [];
31	const _MAX_GAIN_POOL = 16;
32	
33	// ---- Active continuous-sound references ----
34	/** @type {{ osc1: OscillatorNode, osc2: OscillatorNode, gain: GainNode, filter: BiquadFilterNode }|null} */
35	let _engineNodes = null;
36	
37	/** @type {{ gain: GainNode, filter: BiquadFilterNode, noiseGen: (() => AudioBufferSourceNode)|null }|null} */
38	let _skidNodes = null;
39	
40	/** @type {Set<AudioNode>} — all one-shot oscillators currently playing */
41	let _activeOneShots = new Set();
42	
43	// ---- Reusable noise buffer (generated once, used for crash + skid) ----
44	/** @type {AudioBuffer|null} */
45	let _noiseBuffer = null;
