51	/**
52	 * Safely retrieve a config value with a fallback default.
53	 * @param {string} key - Config key (e.g. 'VOLUME_MASTER')
54	 * @param {number} fallback
55	 * @returns {number}
56	 */
57	function _cfg(key, fallback) {
58	  return (R.CONFIG && typeof R.CONFIG[key] === 'number') ? R.CONFIG[key] : fallback;
59	}
60	
61	/**
62	 * Ensure default config values exist on R.CONFIG.
63	 * Only sets values that are absent — never overwrites user config.
64	 */
65	function _ensureConfigDefaults() {
66	  if (!R.CONFIG) R.CONFIG = {};
67	  const defaults = {
68	    VOLUME_MASTER:   0.7,
69	    VOLUME_SFX:      0.6,
70	    VOLUME_ENGINE:   0.25,
71	    VOLUME_SKID:     0.35,
72	    ENGINE_FREQ_MIN: 80,
73	    ENGINE_FREQ_MAX: 400,
74	    ENGINE_DETUNE:   6,        // cents detune between two engine oscillators
75	    SKID_FREQ_MIN:   200,
76	    SKID_FREQ_MAX:   2000,
77	    COUNTDOWN_BEEP_FREQ: 440,
78	    COUNTDOWN_GO_FREQ:    880,
79	    COUNTDOWN_BEEP_DUR:   0.1,
80	    COUNTDOWN_GO_DUR:     0.3,
81	    COUNTDOWN_INTERVAL:   0.6,  // seconds between beeps
82	    MENU_SELECT_FREQ: 1000,
83	    MENU_SELECT_DUR:  0.03,
84	    CRASH_DURATION:   0.3,
85	    CRASH_CENTER_FREQ: 800,
86	    CRASH_BANDWIDTH:   600,
87	    FINISH_START_FREQ: 200,
88	    FINISH_END_FREQ:   800,
89	    FINISH_DURATION:   1.0,
90	    FINISH_DELAY_TIME: 0.15,
91	    FINISH_DELAY_FEEDBACK: 0.35
92	  };
93	  for (const [k, v] of Object.entries(defaults)) {
94	    if (R.CONFIG[k] === undefined) R.CONFIG[k] = v;
95	  }
96	}
