98	/**
99	 * Create a stereo white-noise buffer (2 seconds, single-channel is fine — we use mono).
100	 * Generated once and cached in _noiseBuffer.
101	 * @returns {AudioBuffer|null}
102	 */
103	function _getNoiseBuffer() {
104	  if (_noiseBuffer) return _noiseBuffer;
105	  if (!_ctx) return null;
106	  try {
107	    const sampleRate = _ctx.sampleRate;
108	    const length = sampleRate * 2; // 2 seconds of noise
109	    const buffer = _ctx.createBuffer(1, length, sampleRate);
110	    const data = buffer.getChannelData(0);
111	    for (let i = 0; i < length; i++) {
112	      data[i] = Math.random() * 2 - 1;
113	    }
114	    _noiseBuffer = buffer;
115	    return buffer;
116	  } catch (e) {
117	    return null;
118	  }
119	}
120	
121	/**
122	 * Acquire an oscillator from the pool or create a new one.
123	 * Returns null if AudioContext is unavailable.
124	 * @returns {OscillatorNode|null}
125	 */
126	function _acquireOsc() {
127	  if (!_ctx) return null;
128	  if (_oscPool.length > 0) return _oscPool.pop();
129	  try { return _ctx.createOscillator(); } catch (e) { return null; }
130	}
131	
132	/**
133	 * Acquire a gain node from the pool or create new.
134	 * @returns {GainNode|null}
135	 */
136	function _acquireGain() {
137	  if (!_ctx) return null;
138	  if (_gainPool.length > 0) return _gainPool.pop();
139	  try { return _ctx.createGain(); } catch (e) { return null; }
140	}
141	
142	/**
143	 * Return an oscillator to the pool for reuse.
144	 * @param {OscillatorNode} osc
145	 */
146	function _releaseOsc(osc) {
147	  if (!osc) return;
148	  try { osc.disconnect(); } catch (e) { /* already disconnected */ }
149	  _activeOneShots.delete(osc);
150	  if (_oscPool.length < _MAX_OSC_POOL) _oscPool.push(osc);
151	}
152	
153	/**
154	 * Return a gain node to the pool.
155	 * @param {GainNode} gain
156	 */
157	function _releaseGain(gain) {
158	  if (!gain) return;
159	  try { gain.disconnect(); } catch (e) { /* ignore */ }
160	  if (_gainPool.length < _MAX_GAIN_POOL) _gainPool.push(gain);
161	}
162	
163	/**
164	 * Schedule a gain ramp to 0 and auto-cleanup after `duration` seconds.
165	 * @param {GainNode} gain
166	 * @param {number} startValue
167	 * @param {number} duration - seconds from now until silent
168	 * @param {OscillatorNode} [osc] - if provided, stop + release after fade
169	 * @param {AudioBufferSourceNode} [src] - if provided, stop + disconnect after fade
170	 */
171	function _scheduleFadeOut(gain, startValue, duration, osc, src) {
172	  if (!gain || !_ctx) return;
173	  const now = _ctx.currentTime;
174	  try {
175	    gain.gain.setValueAtTime(startValue, now);
176	    gain.gain.linearRampToValueAtTime(0, now + duration + 0.01);
177	  } catch (e) { /* ignore */ }
178	
179	  const cleanupTime = now + duration + 0.05;
180	  if (osc) {
181	    try { osc.stop(cleanupTime); } catch (e) { /* already stopped */ }
182	    setTimeout(() => _releaseOsc(osc), (cleanupTime - _ctx.currentTime) * 1000 + 100);
183	  }
184	  if (src) {
185	    try { src.stop(cleanupTime); } catch (e) { /* already stopped */ }
186	    setTimeout(() => { try { src.disconnect(); } catch (e) { /* ignore */ } }, (cleanupTime - _ctx.currentTime) * 1000 + 100);
187	  }
188	}
189	
190	/**
191	 * Small helper: schedule a precise beep.
192	 * @param {number} freq - Hz
193	 * @param {number} startTime - AudioContext time
194	 * @param {number} duration - seconds
195	 * @param {number} volume - gain 0-1
196	 */
197	function _scheduleBeep(freq, startTime, duration, volume) {
198	  if (!_ctx || !_masterGain) return;
199	  const osc = _acquireOsc();
200	  const g = _acquireGain();
201	  if (!osc || !g) return;
202	
203	  try {
204	    osc.type = 'square';
205	    osc.frequency.setValueAtTime(freq, startTime);
206	  } catch (e) { _releaseOsc(osc); _releaseGain(g); return; }
207	
208	  try { g.gain.setValueAtTime(0, startTime); } catch (e) { /* ignore */ }
209	  try { g.gain.linearRampToValueAtTime(volume, startTime + 0.005); } catch (e) { /* ignore */ }
210	  try { g.gain.setValueAtTime(volume, startTime + duration * 0.7); } catch (e) { /* ignore */ }
211	  try { g.gain.linearRampToValueAtTime(0, startTime + duration + 0.01); } catch (e) { /* ignore */ }
212	
213	  try { osc.connect(g); } catch (e) { _releaseOsc(osc); _releaseGain(g); return; }
214	  try { g.connect(_masterGain); } catch (e) { _releaseOsc(osc); _releaseGain(g); return; }
215	
216	  _activeOneShots.add(osc);
217	  try { osc.start(startTime); } catch (e) { /* ignore */ }
218	  try { osc.stop(startTime + duration + 0.02); } catch (e) { /* ignore */ }
219	
220	  // Cleanup after the note ends
221	  const cleanupDelay = (duration + 0.1) * 1000;
222	  setTimeout(() => {
223	    _releaseOsc(osc);
224	    _releaseGain(g);
225	  }, cleanupDelay);
226	}
