228	// ===================================================================
229	// PUBLIC API — attached to window.R
230	// ===================================================================
231	
232	/**
233	 * Initialize the audio system. Must be called once, typically after a user
234	 * gesture (click / tap / keypress) so the browser allows AudioContext creation.
235	 *
236	 * On failure (e.g. browser blocks autoplay), all R.playSound calls become
237	 * no-ops and the game continues silently.
238	 */
239	R.initAudio = function () {
240	  if (_initialized) return;
241	
242	  _ensureConfigDefaults();
243	
244	  try {
245	    // Some browsers use webkitAudioContext
246	    const AudioCtx = window.AudioContext || window.webkitAudioContext;
247	    if (!AudioCtx) {
248	      console.warn('[audio] Web Audio API not available in this browser.');
249	      return;
250	    }
251	    _ctx = new AudioCtx();
252	  } catch (e) {
253	    console.warn('[audio] Failed to create AudioContext:', e.message);
254	    _ctx = null;
255	    return;
256	  }
257	
258	  try {
259	    _masterGain = _ctx.createGain();
260	    _masterGain.gain.value = _cfg('VOLUME_MASTER', 0.7);
261	    _masterGain.connect(_ctx.destination);
262	  } catch (e) {
263	    console.warn('[audio] Failed to create master gain:', e.message);
264	    _ctx = null;
265	    _masterGain = null;
266	    return;
267	  }
268	
269	  // Pre-fill oscillator and gain pools
270	  for (let i = 0; i < _MAX_OSC_POOL; i++) {
271	    try {
272	      const osc = _ctx.createOscillator();
273	      _oscPool.push(osc);
274	    } catch (e) { break; }
275	  }
276	  for (let i = 0; i < _MAX_GAIN_POOL; i++) {
277	    try {
278	      const g = _ctx.createGain();
279	      _gainPool.push(g);
280	    } catch (e) { break; }
281	  }
282	
283	  // Generate the noise buffer eagerly
284	  _getNoiseBuffer();
285	
286	  _initialized = true;
287	  console.log('[audio] Audio system initialized. Sample rate:', _ctx.sampleRate, 'Hz');
288	};
289	
290	/**
291	 * Play a procedural sound effect.
292	 *
293	 * @param {string} type - One of: 'engine', 'crash', 'skid', 'countdown', 'go',
294	 *   'finish', 'menu_select'
295	 * @param {Object} [params={}] - Type-specific parameters:
296	 *   - crash: { intensity: 0..1 }
297	 *   - engine: { speed: number, maxSpeed: number }
298	 */
299	R.playSound = function (type, params) {
300	  if (!_initialized || !_ctx || !_masterGain) return;
301	  if (_muted) return; // Respect mute state
302	
303	  params = params || {};
304	
305	  switch (type) {
306	
307	    // ------------------------------------------------------------------
308	    // ENGINE — continuous rumble, started once and updated per frame
309	    // ------------------------------------------------------------------
310	    case 'engine':
311	      {
312	        if (_engineNodes) return; // Already running
313	        const vol = _cfg('VOLUME_ENGINE', 0.25);
314	
315	        // Low-pass filter for muffled engine character
316	        let filter;
317	        try { filter = _ctx.createBiquadFilter(); } catch (e) { return; }
318	        filter.type = 'lowpass';
319	        filter.frequency.value = 300;
320	        filter.Q.value = 1;
321	
322	        // Two detuned oscillators for richness
323	        const osc1 = _acquireOsc();
324	        const osc2 = _acquireOsc();
325	        const gain = _acquireGain();
326	        if (!osc1 || !osc2 || !gain) {
327	          _releaseOsc(osc1); _releaseOsc(osc2); _releaseGain(gain);
328	          return;
329	        }
330	
331	        const detuneCents = _cfg('ENGINE_DETUNE', 6);
332	        const freqMin = _cfg('ENGINE_FREQ_MIN', 80);
333	
334	        try {
335	          osc1.type = 'sawtooth';
336	          osc2.type = 'sawtooth';
337	          osc1.frequency.value = freqMin;
338	          osc2.frequency.value = freqMin;
339	          osc1.detune.value = -detuneCents;
340	          osc2.detune.value = detuneCents;
341	
342	          gain.gain.value = 0; // Start silent, fade in
343	
344	          osc1.connect(gain);
345	          osc2.connect(gain);
346	          gain.connect(filter);
347	          filter.connect(_masterGain);
348	
349	          osc1.start();
350	          osc2.start();
351	        } catch (e) {
352	          _releaseOsc(osc1); _releaseOsc(osc2); _releaseGain(gain);
353	          return;
354	        }
355	
356	        // Fade engine in over 0.3s to avoid pop
357	        try {
358	          const now = _ctx.currentTime;
359	          gain.gain.linearRampToValueAtTime(vol, now + 0.3);
360	        } catch (e) { /* ignore */ }
361	
362	        _engineNodes = { osc1, osc2, gain, filter };
363	      }
364	      break;
365	
366	    // ------------------------------------------------------------------
367	    // CRASH — short noise burst
368	    // ------------------------------------------------------------------
369	    case 'crash':
370	      {
371	        const intensity = Math.max(0, Math.min(1, params.intensity || 0.5));
372	        const vol = _cfg('VOLUME_SFX', 0.6) * (0.4 + intensity * 0.6);
373	        const duration = _cfg('CRASH_DURATION', 0.3);
374	
375	        const noiseBuf = _getNoiseBuffer();
376	        if (!noiseBuf) return;
377	
378	        let src, bandpass, gain;
379	        try {
380	          src = _ctx.createBufferSource();
381	          bandpass = _ctx.createBiquadFilter();
382	          gain = _acquireGain();
383	          if (!gain) { src = null; throw new Error('no gain'); }
384	        } catch (e) { return; }
385	
386	        src.buffer = noiseBuf;
387	        src.loop = false;
388	
389	        bandpass.type = 'bandpass';
390	        bandpass.frequency.value = _cfg('CRASH_CENTER_FREQ', 800);
391	        bandpass.Q.value = bandpass.frequency.value / _cfg('CRASH_BANDWIDTH', 600);
392	
393	        try {
394	          src.connect(bandpass);
395	          bandpass.connect(gain);
396	          gain.connect(_masterGain);
397	        } catch (e) {
398	          try { src.disconnect(); } catch (ex) { /* ignore */ }
399	          _releaseGain(gain);
400	          return;
401	        }
402	
403	        _scheduleFadeOut(gain, vol, duration, null, src);
404	        try { src.start(); } catch (e) { /* ignore */ }
405	
406	        // Auto-cleanup
407	        setTimeout(() => {
408	          try { bandpass.disconnect(); } catch (e) { /* ignore */ }
409	          _releaseGain(gain);
410	        }, (duration + 0.2) * 1000);
411	      }
412	      break;
413	
414	    // ------------------------------------------------------------------
415	    // SKID — continuous noise, started when drifting
416	    // ------------------------------------------------------------------
417	    case 'skid':
418	      {
419	        if (_skidNodes) return; // Already skidding
420	        const vol = _cfg('VOLUME_SKID', 0.35);
421	
422	        const noiseBuf = _getNoiseBuffer();
423	        if (!noiseBuf) return;
424	
425	        let src, filter, gain;
426	        try {
427	          src = _ctx.createBufferSource();
428	          filter = _ctx.createBiquadFilter();
429	          gain = _acquireGain();
430	          if (!gain) { src = null; throw new Error('no gain'); }
431	        } catch (e) { return; }
432	
433	        src.buffer = noiseBuf;
434	        src.loop = true;
435	
436	        filter.type = 'bandpass';
437	        filter.frequency.value = _cfg('SKID_FREQ_MIN', 200);
438	        filter.Q.value = 1.5;
439	
440	        try {
441	          gain.gain.value = 0;
442	          src.connect(filter);
443	          filter.connect(gain);
444	          gain.connect(_masterGain);
445	        } catch (e) {
446	          try { src.disconnect(); } catch (ex) { /* ignore */ }
447	          _releaseGain(gain);
448	          return;
449	        }
450	
451	        // Fade in
452	        try {
453	          const now = _ctx.currentTime;
454	          gain.gain.linearRampToValueAtTime(vol, now + 0.15);
455	        } catch (e) { /* ignore */ }
456	
457	        try { src.start(); } catch (e) { /* ignore */ }
458	
459	        _skidNodes = { gain, filter, noiseGen: null }; // noiseGen unused but kept for shape
460	      }
461	      break;
462	
463	    // ------------------------------------------------------------------
464	    // COUNTDOWN — three low beeps then one high "GO!" beep
465	    // ------------------------------------------------------------------
466	    case 'countdown':
467	      {
468	        const beepFreq = _cfg('COUNTDOWN_BEEP_FREQ', 440);
469	        const goFreq = _cfg('COUNTDOWN_GO_FREQ', 880);
470	        const beepDur = _cfg('COUNTDOWN_BEEP_DUR', 0.1);
471	        const interval = _cfg('COUNTDOWN_INTERVAL', 0.6);
472	        const sfxVol = _cfg('VOLUME_SFX', 0.6);
473	        const now = _ctx.currentTime;
474	
475	        // 3… 2… 1…
476	        for (let i = 0; i < 3; i++) {
477	          _scheduleBeep(beepFreq, now + i * interval, beepDur, sfxVol);
478	        }
479	        // GO! — also handled separately via 'go' sound, but include here for completeness
480	        // (The 'go' sound type below handles the higher-pitched final beep.)
481	      }
482	      break;
483	
484	    // ------------------------------------------------------------------
485	    // GO — the higher-pitched final countdown beep
486	    // ------------------------------------------------------------------
487	    case 'go':
488	      {
489	        const goFreq = _cfg('COUNTDOWN_GO_FREQ', 880);
490	        const goDur = _cfg('COUNTDOWN_GO_DUR', 0.3);
491	        const sfxVol = _cfg('VOLUME_SFX', 0.6);
492	        const now = _ctx.currentTime;
493	        _scheduleBeep(goFreq, now, goDur, sfxVol * 1.1);
494	      }
495	      break;
496	
497	    // ------------------------------------------------------------------
498	    // FINISH — ascending sweep with delay (reverb-like)
499	    // ------------------------------------------------------------------
500	    case 'finish':
501	      {
502	        const startFreq = _cfg('FINISH_START_FREQ', 200);
503	        const endFreq = _cfg('FINISH_END_FREQ', 800);
504	        const duration = _cfg('FINISH_DURATION', 1.0);
505	        const delayTime = _cfg('FINISH_DELAY_TIME', 0.15);
506	        const delayFeedback = _cfg('FINISH_DELAY_FEEDBACK', 0.35);
507	        const sfxVol = _cfg('VOLUME_SFX', 0.6);
508	
509	        const osc = _acquireOsc();
510	        const gain = _acquireGain();
511	        const delay = _ctx.createDelay(2.0);
512	        const feedbackGain = _acquireGain();
513	        const dryGain = _acquireGain();
514	        if (!osc || !gain || !delay || !feedbackGain || !dryGain) {
515	          _releaseOsc(osc); _releaseGain(gain); _releaseGain(feedbackGain); _releaseGain(dryGain);
516	          return;
517	        }
518	
519	        try {
520	          // Delay setup with feedback
521	          delay.delayTime.value = delayTime;
522	          feedbackGain.gain.value = delayFeedback;
523	
524	          // Dry/wet mix: dry at full vol, wet (delayed) at ~60%
525	          dryGain.gain.value = 1.0;
526	          const wetGain = _acquireGain();
527	          if (wetGain) { try { wetGain.gain.value = 0.6; } catch (e) { /* ignore */ } }
528	
529	          osc.type = 'sine';
530	          const now = _ctx.currentTime;
531	          osc.frequency.setValueAtTime(startFreq, now);
532	          osc.frequency.linearRampToValueAtTime(endFreq, now + duration);
533	
534	          gain.gain.setValueAtTime(0, now);
535	          gain.gain.linearRampToValueAtTime(sfxVol, now + 0.05);
536	          gain.gain.setValueAtTime(sfxVol, now + duration * 0.6);
537	          gain.gain.linearRampToValueAtTime(0, now + duration + 0.05);
538	
539	          // Routing: osc → gain → dryGain → masterGain
540	          //                   → delay → feedbackGain → delay (feedback)
541	          //                   → delay → wetGain → masterGain
542	          osc.connect(gain);
543	
544	          // Dry path
545	          gain.connect(dryGain);
546	          dryGain.connect(_masterGain);
547	
548	          // Delay path
549	          gain.connect(delay);
550	          delay.connect(feedbackGain);
551	          feedbackGain.connect(delay); // feedback loop
552	          if (wetGain) {
553	            delay.connect(wetGain);
554	            wetGain.connect(_masterGain);
555	          }
556	
557	          _activeOneShots.add(osc);
558	          osc.start(now);
559	          osc.stop(now + duration + 0.1);
560	        } catch (e) {
561	          _releaseOsc(osc); _releaseGain(gain); _releaseGain(feedbackGain); _releaseGain(dryGain);
562	          return;
563	        }
564	
565	        // Cleanup after sound finishes + reverb tail
566	        const cleanupMs = (duration + delayTime * 4 + 0.5) * 1000;
567	        setTimeout(() => {
568	          _releaseOsc(osc);
569	          _releaseGain(gain);
570	          _releaseGain(feedbackGain);
571	          _releaseGain(dryGain);
572	          try { delay.disconnect(); } catch (e) { /* ignore */ }
573	        }, cleanupMs);
574	      }
575	      break;
576	
577	    // ------------------------------------------------------------------
578	    // MENU_SELECT — short click
579	    // ------------------------------------------------------------------
580	    case 'menu_select':
581	      {
582	        const freq = _cfg('MENU_SELECT_FREQ', 1000);
583	        const dur = _cfg('MENU_SELECT_DUR', 0.03);
584	        const sfxVol = _cfg('VOLUME_SFX', 0.6);
585	        const now = _ctx.currentTime;
586	
587	        const osc = _acquireOsc();
588	        const gain = _acquireGain();
589	        if (!osc || !gain) { _releaseOsc(osc); _releaseGain(gain); return; }
590	
591	        try {
592	          osc.type = 'sine';
593	          osc.frequency.setValueAtTime(freq, now);
594	          gain.gain.setValueAtTime(0, now);
595	          gain.gain.linearRampToValueAtTime(sfxVol * 0.5, now + 0.002);
596	          gain.gain.linearRampToValueAtTime(0, now + dur);
597	
598	          osc.connect(gain);
599	          gain.connect(_masterGain);
600	
601	          _activeOneShots.add(osc);
602	          osc.start(now);
603	          osc.stop(now + dur + 0.01);
604	        } catch (e) {
605	          /* cleanup handled below */
606	        }
607	
608	        setTimeout(() => {
609	          _releaseOsc(osc);
610	          _releaseGain(gain);
611	        }, (dur + 0.1) * 1000);
612	      }
613	      break;
614	
615	    default:
616	      // Unknown sound type — silently ignored
617	      break;
618	  }
619	};
