622	// CONTINUOUS SOUND UPDATE — called every frame by the game loop
623	// ===================================================================
624	
625	/**
626	 * Update continuous sounds (engine pitch, skid filter). Called each frame with
627	 * the delta time in seconds. Reads current car state from R.playerCar (or the
628	 * first car in R.cars if that convention is used).
629	 *
630	 * @param {number} dt - Delta time in seconds
631	 */
632	R.updateAudio = function (dt) {
633	  if (!_initialized || !_ctx || !_masterGain) return;
634	  if (_muted && _engineNodes) {
635	    // Keep engine silent while muted but don't tear it down
636	    return;
637	  }
638	
639	  const now = _ctx.currentTime;
640	
641	  // ---- Engine sound update ----
642	  if (_engineNodes) {
643	    const en = _engineNodes;
644	    const car = (R.playerCar) || (R.cars && R.cars[0]) || null;
645	
646	    let speed = 0;
647	    let maxSpeed = 300; // fallback
648	    if (car && typeof car.speed === 'number') {
649	      speed = Math.abs(car.speed);
650	      maxSpeed = (typeof car.maxSpeed === 'number' && car.maxSpeed > 0) ? car.maxSpeed : 300;
651	    }
652	
653	    // Clamp speed ratio
654	    const ratio = Math.max(0, Math.min(1, speed / maxSpeed));
655	    const freqMin = _cfg('ENGINE_FREQ_MIN', 80);
656	    const freqMax = _cfg('ENGINE_FREQ_MAX', 400);
657	    const targetFreq = freqMin + ratio * (freqMax - freqMin);
658	
659	    // Smooth frequency transition to avoid pops (exponential smoothing)
660	    try {
661	      // Ramp over a short window rather than instantaneous set
662	      en.osc1.frequency.linearRampToValueAtTime(targetFreq, now + 0.05);
663	      en.osc2.frequency.linearRampToValueAtTime(targetFreq, now + 0.05);
664	
665	      // Adjust filter cutoff: higher speed = more open filter
666	      const filterFreq = 150 + ratio * 350;
667	      en.filter.frequency.linearRampToValueAtTime(filterFreq, now + 0.05);
668	    } catch (e) { /* ignore — oscillators may have been stopped */ }
669	  }
670	
671	  // ---- Skid sound update ----
672	  if (_skidNodes) {
673	    const sk = _skidNodes;
674	    const car = (R.playerCar) || (R.cars && R.cars[0]) || null;
675	
676	    let driftMag = 0;
677	    if (car && typeof car.driftFactor === 'number') {
678	      driftMag = Math.abs(car.driftFactor);
679	    }
680	
681	    // If drift is negligible, stop skid sound
682	    if (driftMag < 0.05) {
683	      // Fade out and tear down
684	      try {
685	        sk.gain.gain.linearRampToValueAtTime(0, now + 0.1);
686	      } catch (e) { /* ignore */ }
687	      setTimeout(() => {
688	        if (_skidNodes === sk) {
689	          _stopSkidInternal();
690	        }
691	      }, 150);
692	      _skidNodes = null;
693	      return;
694	    }
695	
696	    // Sweep bandpass filter based on drift magnitude
697	    const skidFreqMin = _cfg('SKID_FREQ_MIN', 200);
698	    const skidFreqMax = _cfg('SKID_FREQ_MAX', 2000);
699	    const targetFilterFreq = skidFreqMin + driftMag * (skidFreqMax - skidFreqMin);
700	    const targetVol = _cfg('VOLUME_SKID', 0.35) * (0.3 + driftMag * 0.7);
701	
702	    try {
703	      sk.filter.frequency.linearRampToValueAtTime(targetFilterFreq, now + 0.05);
704	      sk.gain.gain.linearRampToValueAtTime(targetVol, now + 0.05);
705	    } catch (e) { /* ignore */ }
706	  }
707	};
