713	/**
714	 * Internal: tear down the engine sound nodes.
715	 */
716	function _stopEngineInternal() {
717	  if (!_engineNodes) return;
718	  const en = _engineNodes;
719	  try {
720	    const now = _ctx ? _ctx.currentTime : 0;
721	    if (en.gain && now > 0) {
722	      en.gain.gain.linearRampToValueAtTime(0, now + 0.05);
723	    }
724	  } catch (e) { /* ignore */ }
725	
726	  // Schedule actual disconnect after the ramp
727	  setTimeout(() => {
728	    try { en.osc1.stop(); } catch (e) { /* ignore */ }
729	    try { en.osc2.stop(); } catch (e) { /* ignore */ }
730	    _releaseOsc(en.osc1);
731	    _releaseOsc(en.osc2);
732	    _releaseGain(en.gain);
733	    try { en.filter.disconnect(); } catch (e) { /* ignore */ }
734	  }, 100);
735	
736	  _engineNodes = null;
737	}
738	
739	/**
740	 * Internal: tear down the skid sound nodes.
741	 */
742	function _stopSkidInternal() {
743	  if (!_skidNodes) return;
744	  const sk = _skidNodes;
745	  try { sk.gain.gain.value = 0; } catch (e) { /* ignore */ }
746	  setTimeout(() => {
747	    _releaseGain(sk.gain);
748	    try { sk.filter.disconnect(); } catch (e) { /* ignore */ }
749	  }, 100);
750	  _skidNodes = null;
751	}
752	
753	/**
754	 * Stop all active continuous and one-shot sounds immediately.
755	 * Called when leaving a race or resetting state.
756	 */
757	R.stopAllSounds = function () {
758	  if (!_initialized || !_ctx) return;
759	
760	  // Tear down engine
761	  _stopEngineInternal();
762	
763	  // Tear down skid
764	  _stopSkidInternal();
765	
766	  // Stop all active one-shot oscillators
767	  const now = _ctx.currentTime;
768	  for (const osc of _activeOneShots) {
769	    try {
770	      // Quick fade to avoid click
771	      osc.stop(now + 0.01);
772	    } catch (e) { /* already stopped */ }
773	    try { osc.disconnect(); } catch (e) { /* ignore */ }
774	  }
775	  _activeOneShots.clear();
776	};
