782	/**
783	 * Set the master volume level.
784	 * @param {number} v - Volume 0..1 (clamped internally)
785	 */
786	R.setMasterVolume = function (v) {
787	  const clamped = Math.max(0, Math.min(1, v));
788	  if (_masterGain) {
789	    try {
790	      const now = _ctx ? _ctx.currentTime : 0;
791	      _masterGain.gain.linearRampToValueAtTime(clamped, now + 0.02);
792	    } catch (e) {
793	      try { _masterGain.gain.value = clamped; } catch (e2) { /* ignore */ }
794	    }
795	  }
796	  // Sync config
797	  if (R.CONFIG) R.CONFIG.VOLUME_MASTER = clamped;
798	  if (!_muted) _preMuteVolume = clamped;
799	};
