801	/**
802	 * Toggle mute on/off. Restores previous volume when unmuting.
803	 */
804	R.toggleMute = function () {
805	  _muted = !_muted;
806	
807	  if (_muted) {
808	    // Save current volume, then set gain to 0
809	    if (_masterGain) {
810	      try {
811	        _preMuteVolume = _masterGain.gain.value;
812	        _masterGain.gain.value = 0;
813	      } catch (e) { /* ignore */ }
814	    }
815	  } else {
816	    // Restore
817	    if (_masterGain) {
818	      try {
819	        _masterGain.gain.linearRampToValueAtTime(_preMuteVolume, (_ctx ? _ctx.currentTime : 0) + 0.02);
820	      } catch (e) {
821	        try { _masterGain.gain.value = _preMuteVolume; } catch (e2) { /* ignore */ }
822	      }
823	    }
824	  }
825	};
