46	/**
47	 * Weighted random selection from SCENERY_TYPES using SCENERY_WEIGHTS.
48	 * @returns {string} scenery type key
49	 */
50	function weightedRandomType() {
51	  let total = 0;
52	  for (let i = 0; i < SCENERY_WEIGHTS.length; i++) {
53	    total += SCENERY_WEIGHTS[i];
54	  }
55	  let roll = Math.random() * total;
56	  for (let i = 0; i < SCENERY_WEIGHTS.length; i++) {
57	    roll -= SCENERY_WEIGHTS[i];
58	    if (roll <= 0) {
59	      return SCENERY_TYPES[i];
60	    }
61	  }
62	  return 'tree';
63	}
