65	/**
66	 * Random int in [min, max].
67	 */
68	function randInt(min, max) {
69	  return Math.floor(Math.random() * (max - min + 1)) + min;
70	}
71	
72	/**
73	 * Random float in [min, max].
74	 */
75	function randFloat(min, max) {
76	  return Math.random() * (max - min) + min;
77	}
78	
79	/**
80	 * Pick a random element from an array.
81	 */
82	function randPick(arr) {
83	  return arr[Math.floor(Math.random() * arr.length)];
84	}
85	
86	/**
87	 * Linear interpolation.
88	 */
89	function lerp(a, b, t) {
90	  return a + (b - a) * t;
91	}
92	
93	/**
94	 * Clamp a value.
95	 */
96	function clamp(val, lo, hi) {
97	  return val < lo ? lo : val > hi ? hi : val;
98	}
