100	/**
101	 * Compute screen-space depth from world position relative to camera.
102	 * Positive z means farther away (on screen, y goes down; worldZ tilts toward horizon).
103	 */
104	function computeScreenDepth(worldX, worldY, worldZ, camX, camY) {
105	  // Approximate: distance from camera position (ignoring z for simplicity)
106	  var dx = worldX - camX;
107	  var dy = worldY - camY;
108	  var dist = Math.sqrt(dx * dx + dy * dy);
109	  return dist + worldZ * 0.5; // z pushes into depth
110	}
