112	// ---------------------------------------------------------------------------
113	// R.initScenery — populate R.sceneryObjects along the track
114	// ---------------------------------------------------------------------------
115	R.initScenery = function () {
116	  R.sceneryObjects = [];
117	  var segments = R.track.segments;
118	  if (!segments || segments.length === 0) return;
119	
120	  var step = R.CONFIG.SCENERY_SEGMENT_STEP;
121	  var totalSegments = segments.length;
122	  var startFinishSeg = R.CONFIG.SCENERY_GRANDSTAND_SEGMENT_INDEX;
123	
124	  // Pre-compute per-segment direction vectors for perpendicular offsets
125	  var dirs = [];
126	  for (var i = 0; i < totalSegments; i++) {
127	    var prev = segments[(i - 1 + totalSegments) % totalSegments];
128	    var curr = segments[i];
129	    var dx = curr.worldX - prev.worldX;
130	    var dy = curr.worldY - prev.worldY;
131	    var len = Math.sqrt(dx * dx + dy * dy);
132	    if (len < 1) {
133	      // degenerate — reuse previous dir
134	      dirs.push(dirs.length > 0 ? dirs[dirs.length - 1] : { dx: 1, dy: 0, len: 1 });
135	    } else {
136	      dirs.push({ dx: dx / len, dy: dy / len, len: len });
137	    }
138	  }
139	
140	  // Place grandstand near start/finish line, off to the right
141	  var startSeg = segments[startFinishSeg];
142	  var startDir = dirs[startFinishSeg];
143	  var perpX = -startDir.dy; // right perpendicular
144	  var perpY = startDir.dx;
145	  R.sceneryObjects.push({
146	    worldX: startSeg.worldX + perpX * 150,
147	    worldY: startSeg.worldY + perpY * 150,
148	    worldZ: startSeg.worldZ,
149	    type: 'grandstand',
150	    width: 300,
151	    height: 120,
152	    color: randPick(BUILDING_COLORS),
153	    variant: 1
154	  });
155	
156	  // Generate scenery along every Nth segment
157	  var buildingClusterSegments = [];
158	  for (var s = 0; s < totalSegments; s += step) {
159	    var seg = segments[s];
160	    var dir = dirs[s];
161	    var perpRightX = -dir.dy;
162	    var perpRightY = dir.dx;
163	
164	    // Determine if this segment is near start/finish (for building clustering)
165	    var distFromHome = Math.min(
166	      Math.abs(s - startFinishSeg),
167	      totalSegments - Math.abs(s - startFinishSeg)
168	    );
169	
170	    // Choose type — rural vs urban bias
171	    var rawType = weightedRandomType();
172	    if (rawType === 'building') {
173	      if (distFromHome > R.CONFIG.SCENERY_BUILDING_CLUSTER_RANGE) {
174	        // Far from start/finish — convert some buildings to trees
175	        if (Math.random() < 0.7) rawType = 'tree';
176	      }
177	    }
178	    if (rawType === 'tree') {
179	      if (distFromHome <= R.CONFIG.SCENERY_BUILDING_CLUSTER_RANGE && Math.random() < 0.3) {
180	        rawType = 'building'; // some trees become buildings near start/finish
181	      }
182	    }
183	
184	    // Only one grandstand (placed above)
185	    if (rawType === 'grandstand') {
186	      rawType = 'building';
187	    }
188	
189	    // Choose side: left or right (biased toward outside of curves)
190	    var side = Math.random() < 0.5 ? 1 : -1;
191	    if (seg.curvature !== undefined && seg.curvature !== 0) {
192	      // Bias toward outside of curve
193	      side = seg.curvature > 0 ? 1 : -1;
194	      if (Math.random() < 0.3) side = -side; // 30% chance of inner placement
195	    }
196	
197	    var offsetDist = randFloat(
198	      R.CONFIG.SCENERY_TRACK_EDGE_OFFSET_MIN,
199	      R.CONFIG.SCENERY_TRACK_EDGE_OFFSET_MAX
200	    ) + seg.width * 0.5;
201	
202	    var obj = {
203	      worldX: seg.worldX + perpRightX * offsetDist * side,
204	      worldY: seg.worldY + perpRightY * offsetDist * side,
205	      worldZ: seg.worldZ || 0,
206	      type: rawType,
207	      width: 0,
208	      height: 0,
209	      color: '',
210	      variant: 0,
211	      rotation: 0
212	    };
213	
214	    // Tune dimensions and color by type
215	    switch (rawType) {
216	      case 'building':
217	        obj.width = randInt(30, 90);
218	        obj.height = randInt(40, 160);
219	        obj.color = randPick(BUILDING_COLORS);
220	        obj.variant = randInt(0, 3); // 0=flat roof, 1=peaked, 2=wide, 3=tall+narrow
221	        buildingClusterSegments.push(s);
222	        break;
223	
224	      case 'tree':
225	        obj.width = randInt(18, 40);
226	        obj.height = randInt(30, 70);
227	        obj.color = randPick(TREE_GREENS);
228	        obj.variant = randInt(0, 2); // 0=round, 1=pine, 2=double-canopy
229	        obj.rotation = randFloat(-0.3, 0.3); // slight random lean
230	        break;
231	
232	      case 'billboard':
233	        obj.width = randInt(40, 70);
234	        obj.height = randInt(50, 90);
235	        obj.color = randPick(BILLBOARD_COLORS);
236	        obj.variant = randInt(0, 1); // 0=single pole, 1=double pole
237	        break;
238	
239	      case 'barrier':
240	        obj.width = randInt(15, 30);
241	        obj.height = randInt(8, 16);
242	        obj.color = '#cc0000'; // red base, white stripes added in render
243	        obj.variant = 0;
244	        // Place barriers closer to track edge
245	        obj.worldX = seg.worldX + perpRightX * (seg.width * 0.5 + randInt(5, 15)) * side;
246	        obj.worldY = seg.worldY + perpRightY * (seg.width * 0.5 + randInt(5, 15)) * side;
247	        break;
248	
249	      default:
250	        break;
251	    }
252	
253	    R.sceneryObjects.push(obj);
254	  }
255	
256	  // Depth-sort by worldZ + distance from origin (approximate back-to-front for rendering)
257	  // We'll sort per-frame in render for accurate camera-relative depth.
258	};
259	
260	// ---------------------------------------------------------------------------
261	// R.renderScenery — render visible scenery objects
262	// ---------------------------------------------------------------------------
263	R.renderScenery = function () {
264	  var ctx = R.ctx;
265	  var cam = R.camera;
266	  var cullDist = R.CONFIG.SCENERY_CULL_DISTANCE;
267	  var margin = R.CONFIG.SCENERY_CULL_MARGIN;
268	  var objects = R.sceneryObjects;
269	  var n = objects.length;
270	  if (n === 0) return;
271	
272	  var camX = cam.x;
273	  var camY = cam.y;
274	
275	  // First pass: compute screen positions and depth, collect visible objects
276	  var visible = [];
277	  for (var i = 0; i < n; i++) {
278	    var obj = objects[i];
279	    var screen = R.worldToScreen
280	      ? R.worldToScreen(obj.worldX, obj.worldY, obj.worldZ)
281	      : defaultWorldToScreen(obj.worldX, obj.worldY, obj.worldZ, camX, camY, cam.zoom);
282	
283	    if (!screen || !screen.visible) continue;
284	
285	    // Cull by screen-space bounding box with margin
286	    var hw = obj.width * screen.scale * 0.5;
287	    var hh = obj.height * screen.scale * 0.5;
288	    if (screen.x + hw < -margin || screen.x - hw > R.canvas.width + margin ||
289	        screen.y + hh < -margin || screen.y - hh > R.canvas.height + margin) {
290	      continue;
291	    }
292	
293	    // Depth for sorting
294	    obj._depth = computeScreenDepth(obj.worldX, obj.worldY, obj.worldZ, camX, camY);
295	    obj._screenX = screen.x;
296	    obj._screenY = screen.y;
297	    obj._scale = screen.scale;
298	    visible.push(obj);
299	  }
300	
301	  // Sort by depth (far to near — paint back to front)
302	  visible.sort(function (a, b) { return b._depth - a._depth; });
303	
304	  // Second pass: draw each visible object
305	  for (var v = 0; v < visible.length; v++) {
306	    var o = visible[v];
307	    ctx.save();
308	    drawSceneryObject(ctx, o, o._screenX, o._screenY, o._scale);
309	    ctx.restore();
310	  }
311	};
