313	// ---------------------------------------------------------------------------
314	// drawSceneryObject — route to type-specific renderer
315	// ---------------------------------------------------------------------------
316	function drawSceneryObject(ctx, obj, sx, sy, scale) {
317	  switch (obj.type) {
318	    case 'building':
319	      drawBuilding(ctx, obj, sx, sy, scale);
320	      break;
321	    case 'tree':
322	      drawTree(ctx, obj, sx, sy, scale);
323	      break;
324	    case 'billboard':
325	      drawBillboard(ctx, obj, sx, sy, scale);
326	      break;
327	    case 'barrier':
328	      drawBarrier(ctx, obj, sx, sy, scale);
329	      break;
330	    case 'grandstand':
331	      drawGrandstand(ctx, obj, sx, sy, scale);
332	      break;
333	    default:
334	      break;
335	  }
336	}
