338	// ---------------------------------------------------------------------------
339	// drawBuilding — rectangle body + windows + roof + shadow
340	// ---------------------------------------------------------------------------
341	function drawBuilding(ctx, obj, sx, sy, scale) {
342	  var w = obj.width * scale;
343	  var h = obj.height * scale;
344	  var x = sx - w * 0.5;
345	  var y = sy - h; // bottom-aligned at ground
346	
347	  // Shadow
348	  ctx.fillStyle = 'rgba(0,0,0,0.25)';
349	  ctx.beginPath();
350	  ctx.ellipse(sx, sy, w * 0.55, w * 0.15, 0, 0, Math.PI * 2);
351	  ctx.fill();
352	
353	  // Building body
354	  ctx.fillStyle = obj.color;
355	  ctx.fillRect(x, y, w, h);
356	
357	  // Outline
358	  ctx.strokeStyle = 'rgba(0,0,0,0.3)';
359	  ctx.lineWidth = Math.max(1, scale * 1.5);
360	  ctx.strokeRect(x, y, w, h);
361	
362	  // Windows
363	  var windowCols = Math.max(2, Math.floor(w / (10 * scale)));
364	  var windowRows = Math.max(2, Math.floor(h / (14 * scale)));
365	  if (windowCols < 1) windowCols = 1;
366	  if (windowRows < 1) windowRows = 1;
367	  var winW = (w * 0.7) / windowCols;
368	  var winH = (h * 0.6) / windowRows;
369	  var startX = x + w * 0.15;
370	  var startY = y + h * 0.1;
371	
372	  // Seed deterministic per-building window pattern
373	  var seed = (obj.worldX * 31 + obj.worldY * 17) % 1000;
374	
375	  for (var row = 0; row < windowRows; row++) {
376	    for (var col = 0; col < windowCols; col++) {
377	      var lit = ((seed + row * 7 + col * 13) % 5) < 3; // ~60% lit
378	      ctx.fillStyle = lit
379	        ? 'rgba(255,255,200,0.75)'
380	        : 'rgba(40,40,60,0.6)';
381	      var wx = startX + col * (winW + w * 0.02);
382	      var wy = startY + row * (winH + h * 0.03);
383	      ctx.fillRect(wx, wy, winW, winH);
384	
385	      // Window frame
386	      ctx.strokeStyle = lit ? 'rgba(0,0,0,0.2)' : 'rgba(0,0,0,0.35)';
387	      ctx.lineWidth = Math.max(0.5, scale * 0.5);
388	      ctx.strokeRect(wx, wy, winW, winH);
389	    }
390	  }
391	
392	  // Door
393	  var doorW = w * 0.18;
394	  var doorH = h * 0.25;
395	  var doorX = sx - doorW * 0.5;
396	  var doorY = sy - doorH;
397	  ctx.fillStyle = 'rgba(60,40,30,0.8)';
398	  ctx.fillRect(doorX, doorY, doorW, doorH);
399	  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
400	  ctx.lineWidth = Math.max(0.5, scale * 0.7);
401	  ctx.strokeRect(doorX, doorY, doorW, doorH);
402	  // Doorknob
403	  ctx.fillStyle = 'rgba(200,180,100,0.7)';
404	  ctx.beginPath();
405	  ctx.arc(doorX + doorW * 0.8, doorY + doorH * 0.5, Math.max(1, scale * 1.5), 0, Math.PI * 2);
406	  ctx.fill();
407	
408	  // Roof
409	  var roofH = h * 0.15;
410	  switch (obj.variant) {
411	    case 0: // flat roof — slightly wider
412	      ctx.fillStyle = randPick(ROOF_COLORS);
413	      ctx.fillRect(x - w * 0.05, y - roofH, w * 1.1, roofH);
414	      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
415	      ctx.lineWidth = Math.max(0.5, scale * 0.7);
416	      ctx.strokeRect(x - w * 0.05, y - roofH, w * 1.1, roofH);
417	      break;
418	
419	    case 1: // peaked roof (triangle)
420	      ctx.fillStyle = randPick(ROOF_COLORS);
421	      ctx.beginPath();
422	      ctx.moveTo(x - w * 0.08, y);
423	      ctx.lineTo(sx, y - roofH * 2);
424	      ctx.lineTo(x + w + w * 0.08, y);
425	      ctx.closePath();
426	      ctx.fill();
427	      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
428	      ctx.lineWidth = Math.max(0.5, scale * 0.7);
429	      ctx.stroke();
430	      break;
431	
432	    case 2: // wide building — flat with slight overhang
433	      ctx.fillStyle = randPick(ROOF_COLORS);
434	      ctx.fillRect(x - w * 0.08, y - roofH, w * 1.16, roofH);
435	      ctx.strokeStyle = 'rgba(0,0,0,0.25)';
436	      ctx.lineWidth = Math.max(0.5, scale * 0.5);
437	      ctx.strokeRect(x - w * 0.08, y - roofH, w * 1.16, roofH);
438	      break;
439	
440	    case 3: // tall narrow — flat roof + chimney
441	      ctx.fillStyle = randPick(ROOF_COLORS);
442	      ctx.fillRect(x - w * 0.04, y - roofH, w * 1.08, roofH);
443	      ctx.strokeStyle = 'rgba(0,0,0,0.25)';
444	      ctx.lineWidth = Math.max(0.5, scale * 0.5);
445	      ctx.strokeRect(x - w * 0.04, y - roofH, w * 1.08, roofH);
446	      // Chimney
447	      var chimW = w * 0.12;
448	      var chimH = roofH * 3;
449	      ctx.fillStyle = '#8b4513';
450	      ctx.fillRect(x + w * 0.65, y - roofH - chimH, chimW, chimH);
451	      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
452	      ctx.lineWidth = Math.max(0.3, scale * 0.4);
453	      ctx.strokeRect(x + w * 0.65, y - roofH - chimH, chimW, chimH);
454	      break;
455	
456	    default:
457	      ctx.fillStyle = randPick(ROOF_COLORS);
458	      ctx.fillRect(x - w * 0.05, y - roofH, w * 1.1, roofH);
459	      break;
460	  }
461	}
