463	// ---------------------------------------------------------------------------
464	// drawTree — circle canopy on brown trunk
465	// ---------------------------------------------------------------------------
466	function drawTree(ctx, obj, sx, sy, scale) {
467	  var w = obj.width * scale;
468	  var h = obj.height * scale;
469	  var trunkW = w * 0.2;
470	  var trunkH = h * 0.4;
471	  var canopyR = w * 0.5;
472	
473	  // Rotation for slight lean
474	  var rot = obj.rotation || 0;
475	
476	  ctx.save();
477	  if (rot !== 0) {
478	    ctx.translate(sx, sy);
479	    ctx.rotate(rot);
480	    ctx.translate(-sx, -sy);
481	  }
482	
483	  // Shadow
484	  ctx.fillStyle = 'rgba(0,0,0,0.2)';
485	  ctx.beginPath();
486	  ctx.ellipse(sx, sy, canopyR * 0.8, canopyR * 0.2, 0, 0, Math.PI * 2);
487	  ctx.fill();
488	
489	  // Trunk
490	  var trunkX = sx - trunkW * 0.5;
491	  var trunkY = sy - trunkH - canopyR * 0.3;
492	  ctx.fillStyle = '#6b4226';
493	  ctx.fillRect(trunkX, trunkY, trunkW, trunkH);
494	  ctx.strokeStyle = 'rgba(0,0,0,0.2)';
495	  ctx.lineWidth = Math.max(0.5, scale * 0.5);
496	  ctx.strokeRect(trunkX, trunkY, trunkW, trunkH);
497	
498	  // Canopy
499	  var canopyY = trunkY - canopyR * 0.5;
500	  var green = obj.color;
501	
502	  switch (obj.variant) {
503	    case 0: // round canopy
504	      ctx.fillStyle = green;
505	      ctx.beginPath();
506	      ctx.arc(sx, canopyY, canopyR, 0, Math.PI * 2);
507	      ctx.fill();
508	      // Highlight
509	      ctx.fillStyle = 'rgba(255,255,255,0.12)';
510	      ctx.beginPath();
511	      ctx.arc(sx - canopyR * 0.2, canopyY - canopyR * 0.2, canopyR * 0.5, 0, Math.PI * 2);
512	      ctx.fill();
513	      // Outline
514	      ctx.strokeStyle = 'rgba(0,0,0,0.25)';
515	      ctx.lineWidth = Math.max(0.5, scale * 0.6);
516	      ctx.beginPath();
517	      ctx.arc(sx, canopyY, canopyR, 0, Math.PI * 2);
518	      ctx.stroke();
519	      break;
520	
521	    case 1: // pine tree — triangular tiers
522	      var pineCY = trunkY - canopyR * 0.0;
523	      for (var tier = 0; tier < 3; tier++) {
524	        var tierW = canopyR * (1.2 - tier * 0.35);
525	        var tierH = canopyR * 0.8;
526	        var tierTopY = pineCY - tier * tierH * 0.5;
527	        ctx.fillStyle = tier === 0 ? green : shadeColor(green, -10 * tier);
528	        ctx.beginPath();
529	        ctx.moveTo(sx, tierTopY - tierH);
530	        ctx.lineTo(sx - tierW, tierTopY);
531	        ctx.lineTo(sx + tierW, tierTopY);
532	        ctx.closePath();
533	        ctx.fill();
534	        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
535	        ctx.lineWidth = Math.max(0.5, scale * 0.4);
536	        ctx.stroke();
537	      }
538	      break;
539	
540	    case 2: // double canopy — two overlapping circles
541	      var c1Y = canopyY - canopyR * 0.1;
542	      ctx.fillStyle = green;
543	      ctx.beginPath();
544	      ctx.arc(sx - canopyR * 0.25, c1Y, canopyR * 0.7, 0, Math.PI * 2);
545	      ctx.fill();
546	      ctx.fillStyle = shadeColor(green, 10);
547	      ctx.beginPath();
548	      ctx.arc(sx + canopyR * 0.25, c1Y, canopyR * 0.65, 0, Math.PI * 2);
549	      ctx.fill();
550	      // Highlight
551	      ctx.fillStyle = 'rgba(255,255,255,0.1)';
552	      ctx.beginPath();
553	      ctx.arc(sx - canopyR * 0.35, c1Y - canopyR * 0.2, canopyR * 0.3, 0, Math.PI * 2);
554	      ctx.fill();
555	      break;
556	
557	    default:
558	      ctx.fillStyle = green;
559	      ctx.beginPath();
560	      ctx.arc(sx, canopyY, canopyR, 0, Math.PI * 2);
561	      ctx.fill();
562	      break;
563	  }
564	
565	  ctx.restore();
566	}
