568	// ---------------------------------------------------------------------------
569	// drawBillboard — tall rectangle with colored ad
570	// ---------------------------------------------------------------------------
571	function drawBillboard(ctx, obj, sx, sy, scale) {
572	  var w = obj.width * scale;
573	  var h = obj.height * scale;
574	  var poleW = Math.max(2, w * 0.12);
575	  var poleH = h * 0.25;
576	  var boardH = h * 0.75;
577	  var x = sx - w * 0.5;
578	  var y = sy - h;
579	
580	  // Shadow
581	  ctx.fillStyle = 'rgba(0,0,0,0.2)';
582	  ctx.beginPath();
583	  ctx.ellipse(sx, sy, w * 0.45, w * 0.1, 0, 0, Math.PI * 2);
584	  ctx.fill();
585	
586	  // Pole(s)
587	  ctx.fillStyle = '#555555';
588	  if (obj.variant === 0) {
589	    // Single center pole
590	    ctx.fillRect(sx - poleW * 0.5, sy - poleH, poleW, poleH);
591	  } else {
592	    // Double poles
593	    ctx.fillRect(x + w * 0.15, sy - poleH, poleW, poleH);
594	    ctx.fillRect(x + w * 0.85 - poleW, sy - poleH, poleW, poleH);
595	  }
596	
597	  // Board background (white)
598	  var boardX = x;
599	  var boardY = y;
600	  ctx.fillStyle = '#f8f8f8';
601	  ctx.fillRect(boardX, boardY, w, boardH);
602	
603	  // Colored ad panel (center portion)
604	  var adPadding = w * 0.08;
605	  var adX = boardX + adPadding;
606	  var adY = boardY + adPadding;
607	  var adW = w - adPadding * 2;
608	  var adH = boardH * 0.55;
609	  ctx.fillStyle = obj.color;
610	  ctx.fillRect(adX, adY, adW, adH);
611	
612	  // "Text" lines on ad
613	  ctx.fillStyle = 'rgba(255,255,255,0.9)';
614	  var lineH = Math.max(1, adH * 0.08);
615	  var lines = 3;
616	  for (var li = 0; li < lines; li++) {
617	    var lw = adW * (0.5 + Math.random() * 0.4);
618	    var lx = adX + adW * 0.1;
619	    var ly = adY + adH * 0.25 + li * adH * 0.25;
620	    ctx.fillRect(lx, ly, lw, lineH);
621	  }
622	
623	  // Bottom text area
624	  var bottomY = adY + adH + adPadding * 0.5;
625	  ctx.fillStyle = 'rgba(0,0,0,0.15)';
626	  ctx.fillRect(adX, bottomY, adW, Math.max(2, boardH * 0.12));
627	
628	  // Border
629	  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
630	  ctx.lineWidth = Math.max(1, scale * 1);
631	  ctx.strokeRect(boardX, boardY, w, boardH);
632	}
