634	// ---------------------------------------------------------------------------
635	// drawBarrier — red-white striped rectangle
636	// ---------------------------------------------------------------------------
637	function drawBarrier(ctx, obj, sx, sy, scale) {
638	  var w = obj.width * scale;
639	  var h = obj.height * scale;
640	  var x = sx - w * 0.5;
641	  var y = sy - h;
642	
643	  // Shadow
644	  ctx.fillStyle = 'rgba(0,0,0,0.2)';
645	  ctx.beginPath();
646	  ctx.ellipse(sx, sy, w * 0.45, w * 0.08, 0, 0, Math.PI * 2);
647	  ctx.fill();
648	
649	  // Barrier body with stripes
650	  var stripeCount = Math.max(2, Math.floor(w / (6 * scale)));
651	  var stripeW = w / stripeCount;
652	
653	  ctx.strokeStyle = 'rgba(0,0,0,0.3)';
654	  ctx.lineWidth = Math.max(0.5, scale * 0.5);
655	
656	  for (var s = 0; s < stripeCount; s++) {
657	    ctx.fillStyle = s % 2 === 0 ? '#cc0000' : '#ffffff';
658	    var sx2 = x + s * stripeW;
659	    ctx.fillRect(sx2, y, stripeW, h);
660	    ctx.strokeRect(sx2, y, stripeW, h);
661	  }
662	}
