664	// ---------------------------------------------------------------------------
665	// drawGrandstand — multi-tier seating structure
666	// ---------------------------------------------------------------------------
667	function drawGrandstand(ctx, obj, sx, sy, scale) {
668	  var w = obj.width * scale;
669	  var h = obj.height * scale;
670	  var x = sx - w * 0.5;
671	  var y = sy - h;
672	  var tiers = 6;
673	  var tierH = h * 0.55 / tiers; // seating takes bottom 55%
674	  var roofH = h * 0.45;
675	  var tierOffset = w * 0.03;
676	
677	  // Shadow
678	  ctx.fillStyle = 'rgba(0,0,0,0.3)';
679	  ctx.beginPath();
680	  ctx.ellipse(sx, sy, w * 0.6, w * 0.12, 0, 0, Math.PI * 2);
681	  ctx.fill();
682	
683	  // Main structure
684	  ctx.fillStyle = '#888888';
685	  ctx.fillRect(x, y, w, h);
686	  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
687	  ctx.lineWidth = Math.max(1, scale * 1.5);
688	  ctx.strokeRect(x, y, w, h);
689	
690	  // Seating tiers — each row a different color
691	  var tierColors = ['#cc3333', '#3366cc', '#33aa33', '#ccaa33', '#aa3366', '#33aaaa'];
692	  var baseY = y + roofH;
693	  for (var t = 0; t < tiers; t++) {
694	    var tw = w - t * tierOffset * 2; // each tier slightly narrower
695	    var tx = x + t * tierOffset;
696	    var ty = baseY + t * tierH;
697	    ctx.fillStyle = tierColors[t % tierColors.length];
698	    ctx.fillRect(tx, ty, tw, tierH);
699	    ctx.strokeStyle = 'rgba(0,0,0,0.3)';
700	    ctx.lineWidth = Math.max(0.5, scale * 0.4);
701	    ctx.strokeRect(tx, ty, tw, tierH);
702	
703	    // Row of seat dots
704	    if (tw > 8 && tierH > 3) {
705	      var dotCount = Math.floor(tw / (3 * scale));
706	      var dotSpacing = tw / (dotCount + 1);
707	      ctx.fillStyle = 'rgba(255,255,255,0.3)';
708	      for (var d = 0; d < dotCount; d++) {
709	        var dx = tx + (d + 1) * dotSpacing;
710	        ctx.beginPath();
711	        ctx.arc(dx, ty + tierH * 0.5, Math.max(0.5, scale * 0.8), 0, Math.PI * 2);
712	        ctx.fill();
713	      }
714	    }
715	  }
716	
717	  // Roof
718	  ctx.fillStyle = '#666666';
719	  ctx.fillRect(x - w * 0.05, y, w * 1.1, roofH * 0.15);
720	  // Roof slant
721	  ctx.fillStyle = '#555555';
722	  ctx.beginPath();
723	  ctx.moveTo(x - w * 0.08, y + roofH * 0.15);
724	  ctx.lineTo(sx, y - roofH * 0.15);
725	  ctx.lineTo(x + w + w * 0.08, y + roofH * 0.15);
726	  ctx.closePath();
727	  ctx.fill();
728	  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
729	  ctx.lineWidth = Math.max(0.5, scale * 0.6);
730	  ctx.stroke();
731	
732	  // Support pillars
733	  var pillarW = Math.max(2, scale * 3);
734	  ctx.fillStyle = '#777777';
735	  ctx.fillRect(x + w * 0.05, y + roofH * 0.1, pillarW, h * 0.5);
736	  ctx.fillRect(x + w * 0.95 - pillarW, y + roofH * 0.1, pillarW, h * 0.5);
737	}
