739	// ---------------------------------------------------------------------------
740	// R.renderCrowd — draw crowd dots in grandstand
741	// ---------------------------------------------------------------------------
742	R.renderCrowd = function (grandstandX, grandstandY) {
743	  var ctx = R.ctx;
744	  var cam = R.camera;
745	  var screen = R.worldToScreen
746	    ? R.worldToScreen(grandstandX, grandstandY, 0)
747	    : defaultWorldToScreen(grandstandX, grandstandY, 0, cam.x, cam.y, cam.zoom);
748	
749	  if (!screen || !screen.visible) return;
750	  if (screen.x < -200 || screen.x > R.canvas.width + 200 ||
751	      screen.y < -200 || screen.y > R.canvas.height + 200) return;
752	
753	  // Find main grandstand object for dimensions
754	  var gs = null;
755	  for (var i = 0; i < R.sceneryObjects.length; i++) {
756	    if (R.sceneryObjects[i].type === 'grandstand') {
757	      gs = R.sceneryObjects[i];
758	      break;
759	    }
760	  }
761	  if (!gs) return;
762	
763	  var scale = screen.scale;
764	  var w = gs.width * scale;
765	  var h = gs.height * scale;
766	  var x = screen.x - w * 0.5;
767	  var y = screen.y - h;
768	  var roofH = h * 0.45;
769	  var tiers = 6;
770	  var tierH = h * 0.55 / tiers;
771	  var tierOffset = w * 0.03;
772	  var baseY = y + roofH;
773	
774	  // Crowd dots per tier
775	  for (var t = 0; t < tiers; t++) {
776	    var tw = w - t * tierOffset * 2;
777	    var tx = x + t * tierOffset;
778	    var ty = baseY + t * tierH;
779	    var peoplePerRow = Math.floor(tw / Math.max(3, 4 * scale));
780	    if (peoplePerRow < 1) peoplePerRow = 1;
781	
782	    // Seed based on tier
783	    var seed = t * 137 + 42;
784	
785	    for (var p = 0; p < peoplePerRow; p++) {
786	      var px = tx + tw * (p + 0.5) / peoplePerRow;
787	      var py = ty + tierH * 0.35;
788	      // Skip some seats for natural look
789	      if (((seed + p * 11) % 7) === 0) continue;
790	
791	      // Small person dot
792	      var skin = SKIN_TONES[(seed + p * 3) % SKIN_TONES.length];
793	      var shirt = SHIRT_COLORS[(seed + p * 7) % SHIRT_COLORS.length];
794	      var dotR = Math.max(1.2, scale * 1.8);
795	
796	      // Head
797	      ctx.fillStyle = skin;
798	      ctx.beginPath();
799	      ctx.arc(px, py - dotR * 0.4, dotR * 0.6, 0, Math.PI * 2);
800	      ctx.fill();
801	
802	      // Body
803	      ctx.fillStyle = shirt;
804	      ctx.fillRect(px - dotR * 0.4, py, dotR * 0.8, dotR * 0.9);
805	    }
806	  }
807	};
