809	// ---------------------------------------------------------------------------
810	// Helper: shade a hex color darker or lighter
811	// ---------------------------------------------------------------------------
812	function shadeColor(color, percent) {
813	  var num = parseInt(color.replace('#', ''), 16);
814	  var amt = Math.round(2.55 * percent);
815	  var R = (num >> 16) + amt;
816	  var G = ((num >> 8) & 0x00ff) + amt;
817	  var B = (num & 0x0000ff) + amt;
818	  R = R < 0 ? 0 : R > 255 ? 255 : R;
819	  G = G < 0 ? 0 : G > 255 ? 255 : G;
820	  B = B < 0 ? 0 : B > 255 ? 255 : B;
821	  return '#' + (0x1000000 + R * 0x10000 + G * 0x100 + B).toString(16).slice(1);
822	}
