824	// ---------------------------------------------------------------------------
825	// Helper: default world-to-screen projection (fallback if R.worldToScreen is
826	// not yet defined). Uses simple perspective projection with camera offset.
827	// ---------------------------------------------------------------------------
828	function defaultWorldToScreen(wx, wy, wz, camX, camY, zoom) {
829	  var canvasW = R.canvas.width;
830	  var canvasH = R.canvas.height;
831	  var cx = canvasW * 0.5;
832	  var cy = canvasH * 0.4; // horizon line
833	
834	  // World offset relative to camera
835	  var rx = wx - camX;
836	  var ry = wy - camY;
837	  var rz = wz; // elevation
838	
839	  // Simple perspective: farther objects appear higher and smaller
840	  var perspectiveFactor = 1;
841	  if (ry > 1) {
842	    perspectiveFactor = 300 / ry;
843	  } else {
844	    perspectiveFactor = 1;
845	  }
846	
847	  var scale = perspectiveFactor * zoom;
848	  var sx = cx + rx * perspectiveFactor * zoom;
849	  var sy = cy - rz * perspectiveFactor * zoom + perspectiveFactor * zoom * 50;
850	
851	  // Visibility check
852	  var visible = perspectiveFactor > 0.01 && perspectiveFactor < 2.0;
853	  if (ry <= 0) visible = false;
854	
855	  return { x: sx, y: sy, scale: scale, visible: visible };
856	}
