60	/**
61	 * Draw a rounded rectangle path (must be wrapped in beginPath/fill/stroke by caller).
62	 * @param {CanvasRenderingContext2D} ctx
63	 * @param {number} x
64	 * @param {number} y
65	 * @param {number} w
66	 * @param {number} h
67	 * @param {number} r - corner radius
68	 */
69	function _roundRect(ctx, x, y, w, h, r) {
70	  ctx.beginPath();
71	  ctx.moveTo(x + r, y);
72	  ctx.lineTo(x + w - r, y);
73	  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
74	  ctx.lineTo(x + w, y + h - r);
75	  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
76	  ctx.lineTo(x + r, y + h);
77	  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
78	  ctx.lineTo(x, y + r);
79	  ctx.quadraticCurveTo(x, y, x + r, y);
80	  ctx.closePath();
81	}
