83	/**
84	 * Format seconds into MM:SS.ms display string.
85	 * @param {number} totalSec
86	 * @returns {string}
87	 */
88	function _formatRaceTime(totalSec) {
89	  if (totalSec == null || !isFinite(totalSec)) return '--:--.--';
90	  const min = Math.floor(totalSec / 60);
91	  const sec = Math.floor(totalSec % 60);
92	  const ms = Math.floor((totalSec % 1) * 100);
93	  return String(min).padStart(2, '0') + ':' +
94	         String(sec).padStart(2, '0') + '.' +
95	         String(ms).padStart(2, '0');
96	}
