160	/**
161	 * R.drawButton(x, y, w, h, text, color)
162	 * Draw a styled button: rounded rect, gradient fill, border highlight, centered text.
163	 * @param {number} x
164	 * @param {number} y
165	 * @param {number} w
166	 * @param {number} h
167	 * @param {string} text
168	 * @param {string} [color='#445577'] - base fill color
169	 */
170	R.drawButton = function(x, y, w, h, text, color) {
171	  const ctx = R.ctx;
172	  const baseColor = color || '#445577';
173	
174	  ctx.save();
175	  _roundRect(ctx, x, y, w, h, MC.BUTTON_ROUND);
176	
177	  // Gradient fill (lighter top, darker bottom)
178	  const grad = ctx.createLinearGradient(x, y, x, y + h);
179	  grad.addColorStop(0, baseColor);
180	  grad.addColorStop(1, _darkenColor(baseColor, 0.45));
181	  ctx.fillStyle = grad;
182	  ctx.fill();
183	
184	  // Border highlight (top edge lighter)
185	  ctx.strokeStyle = _lightenColor(baseColor, 0.3);
186	  ctx.lineWidth = 2;
187	  ctx.stroke();
188	
189	  // Inner top highlight line
190	  ctx.save();
191	  ctx.beginPath();
192	  ctx.rect(x + MC.BUTTON_ROUND, y + 1, w - MC.BUTTON_ROUND * 2, 2);
193	  ctx.clip();
194	  ctx.fillStyle = 'rgba(255,255,255,0.18)';
195	  ctx.fillRect(x, y, w, 3);
196	  ctx.restore();
197	
198	  // Text centered
199	  const fontSize = Math.max(12, Math.min(h * 0.45, 22));
200	  ctx.fillStyle = '#ffffff';
201	  ctx.font = 'bold ' + fontSize + 'px "Segoe UI",Arial,sans-serif';
202	  ctx.textAlign = 'center';
203	  ctx.textBaseline = 'middle';
204	  ctx.shadowColor = 'rgba(0,0,0,0.5)';
205	  ctx.shadowBlur = 2;
206	  ctx.fillText(text, x + w / 2, y + h / 2);
207	  ctx.shadowBlur = 0;
208	
209	  ctx.restore();
210	};
