212	/**
213	 * R.drawGradientText(text, x, y, colorTop, colorBottom, font)
214	 * Draw text with a vertical gradient fill using clip region + gradient.
215	 * @param {string} text
216	 * @param {number} x - center-x of the text
217	 * @param {number} y - baseline-y of the text
218	 * @param {string} colorTop - top gradient color (e.g. '#ffffff')
219	 * @param {string} colorBottom - bottom gradient color (e.g. '#667799')
220	 * @param {string} font - CSS font string (e.g. 'bold 96px Arial')
221	 */
222	R.drawGradientText = function(text, x, y, colorTop, colorBottom, font) {
223	  const ctx = R.ctx;
224	
225	  ctx.save();
226	  ctx.font = font;
227	  ctx.textAlign = 'center';
228	  ctx.textBaseline = 'alphabetic';
229	
230	  // Measure text to build clip region
231	  const metrics = ctx.measureText(text);
232	  const tw = metrics.width;
233	  const th = metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent;
234	  // Fallback if actualBoundingBox not supported: estimate from font size
235	  const fontSize = parseInt(font, 10) || 48;
236	  const textH = th > 0 ? th : fontSize * 1.2;
237	  const clipX = x - tw / 2 - 4;
238	  const clipY = y - textH;
239	
240	  // Clip to text bounding box
241	  ctx.beginPath();
242	  ctx.rect(clipX, clipY, tw + 8, textH + 4);
243	  ctx.clip();
244	
245	  // Vertical gradient
246	  const grad = ctx.createLinearGradient(0, clipY, 0, clipY + textH);
247	  grad.addColorStop(0, colorTop);
248	  grad.addColorStop(1, colorBottom);
249	  ctx.fillStyle = grad;
250	  ctx.fillText(text, x, y);
251	
252	  ctx.restore();
253	};
