256	
257	/**
258	 * Draw a sports-car silhouette (side-ish view) that can be positioned and scaled.
259	 * Used by the title screen animation.
260	 * @param {CanvasRenderingContext2D} ctx
261	 * @param {number} cx - center x
262	 * @param {number} cy - center y (bottom of wheels)
263	 * @param {number} scale - size multiplier
264	 */
265	function _drawCarSilhouette(ctx, cx, cy, scale) {
266	  const s = scale;
267	  ctx.save();
268	  ctx.translate(cx, cy);
269	
270	  // Car body dimensions (in base units, multiplied by scale)
271	  const bodyLen = 180 * s;
272	  const bodyH   = 32 * s;
273	  const cabinW  = 55 * s;
274	  const cabinH  = 28 * s;
275	  const wheelR  = 16 * s;
276	  const wheelW  = 10 * s;
277	  const groundY = 0;
278	
279	  ctx.fillStyle = '#d0d8e8';
280	
281	  // --- Main body (low, wide) ---
282	  ctx.beginPath();
283	  ctx.moveTo(-bodyLen * 0.48, groundY - bodyH * 0.35);                // front bumper top
284	  ctx.lineTo(-bodyLen * 0.38, groundY - bodyH * 0.7);                 // hood rise
285	  ctx.lineTo(-bodyLen * 0.10, groundY - bodyH * 0.75);                // windshield base
286	  ctx.lineTo(bodyLen * 0.08, groundY - bodyH * 0.75);                 // rear window base
287	  ctx.lineTo(bodyLen * 0.35, groundY - bodyH * 0.4);                  // trunk slope
288	  ctx.lineTo(bodyLen * 0.45, groundY - bodyH * 0.25);                 // rear bumper top
289	  ctx.lineTo(bodyLen * 0.45, groundY - bodyH * 0.05);                 // rear lower
290	  ctx.lineTo(-bodyLen * 0.48, groundY - bodyH * 0.05);                // front lower
291	  ctx.closePath();
292	  ctx.fill();
293	
294	  // --- Cabin / roof ---
295	  ctx.fillStyle = '#c0c8d8';
296	  ctx.beginPath();
297	  ctx.moveTo(-bodyLen * 0.12, groundY - bodyH * 0.75);                // windshield top
298	  ctx.quadraticCurveTo(-bodyLen * 0.02, groundY - bodyH - cabinH * 0.25, bodyLen * 0.06, groundY - bodyH - cabinH * 0.15); // roof front
299	  ctx.lineTo(bodyLen * 0.22, groundY - bodyH - cabinH * 0.15);       // roof rear
300	  ctx.quadraticCurveTo(bodyLen * 0.30, groundY - bodyH - cabinH * 0.1, bodyLen * 0.33, groundY - bodyH * 0.6); // rear window
301	  ctx.lineTo(-bodyLen * 0.08, groundY - bodyH * 0.7);                // back to windshield
302	  ctx.closePath();
303	  ctx.fill();
304	
305	  // --- Spoiler ---
306	  ctx.fillStyle = '#b0b8c8';
307	  ctx.beginPath();
308	  ctx.moveTo(bodyLen * 0.40, groundY - bodyH * 0.45);
309	  ctx.lineTo(bodyLen * 0.48, groundY - bodyH * 0.50);
310	  ctx.lineTo(bodyLen * 0.48, groundY - bodyH * 0.15);
311	  ctx.lineTo(bodyLen * 0.43, groundY - bodyH * 0.18);
312	  ctx.closePath();
313	  ctx.fill();
314	
315	  // --- Front splitter ---
316	  ctx.fillStyle = '#c8d0e0';
317	  ctx.beginPath();
318	  ctx.moveTo(-bodyLen * 0.48, groundY - bodyH * 0.08);
319	  ctx.lineTo(-bodyLen * 0.44, groundY - bodyH * 0.08);
320	  ctx.lineTo(-bodyLen * 0.46, groundY + bodyH * 0.02);
321	  ctx.lineTo(-bodyLen * 0.50, groundY + bodyH * 0.02);
322	  ctx.closePath();
323	  ctx.fill();
324	
325	  // --- Rear wheel ---
326	  ctx.fillStyle = '#1a1a1a';
327	  ctx.beginPath();
328	  ctx.arc(bodyLen * 0.28, groundY - wheelR * 0.1, wheelR, 0, Math.PI * 2);
329	  ctx.fill();
330	  ctx.fillStyle = '#333';
331	  ctx.beginPath();
332	  ctx.arc(bodyLen * 0.28, groundY - wheelR * 0.1, wheelR * 0.55, 0, Math.PI * 2);
333	  ctx.fill();
334	  // Rim cross
335	  ctx.strokeStyle = '#555';
336	  ctx.lineWidth = 1.5 * s;
337	  ctx.beginPath();
338	  ctx.moveTo(bodyLen * 0.28 - wheelR * 0.5, groundY - wheelR * 0.1);
339	  ctx.lineTo(bodyLen * 0.28 + wheelR * 0.5, groundY - wheelR * 0.1);
340	  ctx.moveTo(bodyLen * 0.28, groundY - wheelR * 0.1 - wheelR * 0.5);
341	  ctx.lineTo(bodyLen * 0.28, groundY - wheelR * 0.1 + wheelR * 0.5);
342	  ctx.stroke();
343	
344	  // --- Front wheel ---
345	  ctx.fillStyle = '#1a1a1a';
346	  ctx.beginPath();
347	  ctx.arc(-bodyLen * 0.30, groundY - wheelR * 0.1, wheelR, 0, Math.PI * 2);
348	  ctx.fill();
349	  ctx.fillStyle = '#333';
350	  ctx.beginPath();
351	  ctx.arc(-bodyLen * 0.30, groundY - wheelR * 0.1, wheelR * 0.55, 0, Math.PI * 2);
352	  ctx.fill();
353	  ctx.strokeStyle = '#555';
354	  ctx.lineWidth = 1.5 * s;
355	  ctx.beginPath();
356	  ctx.moveTo(-bodyLen * 0.30 - wheelR * 0.5, groundY - wheelR * 0.1);
357	  ctx.lineTo(-bodyLen * 0.30 + wheelR * 0.5, groundY - wheelR * 0.1);
358	  ctx.moveTo(-bodyLen * 0.30, groundY - wheelR * 0.1 - wheelR * 0.5);
359	  ctx.lineTo(-bodyLen * 0.30, groundY - wheelR * 0.1 + wheelR * 0.5);
360	  ctx.stroke();
361	
362	  // --- Window tint (dark) ---
363	  ctx.fillStyle = 'rgba(20, 25, 40, 0.6)';
364	  ctx.beginPath();
365	  ctx.moveTo(-bodyLen * 0.10, groundY - bodyH * 0.73);
366	  ctx.quadraticCurveTo(-bodyLen * 0.01, groundY - bodyH - cabinH * 0.28, bodyLen * 0.06, groundY - bodyH - cabinH * 0.18);
367	  ctx.lineTo(bodyLen * 0.20, groundY - bodyH - cabinH * 0.18);
368	  ctx.quadraticCurveTo(bodyLen * 0.28, groundY - bodyH - cabinH * 0.12, bodyLen * 0.31, groundY - bodyH * 0.62);
369	  ctx.lineTo(-bodyLen * 0.06, groundY - bodyH * 0.72);
370	  ctx.closePath();
371	  ctx.fill();
372	
373	  // --- Headlight (front) ---
374	  ctx.fillStyle = '#ffe8c0';
375	  ctx.beginPath();
376	  ctx.ellipse(-bodyLen * 0.47, groundY - bodyH * 0.40, 5 * s, 3 * s, -0.2, 0, Math.PI * 2);
377	  ctx.fill();
378	
379	  // --- Tail light (rear) ---
380	  ctx.fillStyle = '#ff3333';
381	  ctx.beginPath();
382	  ctx.ellipse(bodyLen * 0.44, groundY - bodyH * 0.38, 4 * s, 2.5 * s, 0.1, 0, Math.PI * 2);
383	  ctx.fill();
384	
385	  // --- Exhaust pipes ---
386	  ctx.fillStyle = '#444';
387	  ctx.fillRect(bodyLen * 0.42, groundY - bodyH * 0.12, 8 * s, 5 * s);
388	  ctx.fillRect(bodyLen * 0.42, groundY - bodyH * 0.22, 8 * s, 5 * s);
389	
390	  // --- Racing stripe ---
391	  ctx.fillStyle = 'rgba(255,255,255,0.12)';
392	  ctx.fillRect(-bodyLen * 0.15, groundY - bodyH * 0.68, bodyLen * 0.42, 5 * s);
393	
394	  ctx.restore();
395	}
