397	/* =========================== Color Utilities ======================== */
398	
399	/**
400	 * Darken a hex color by a factor (0 = no change, 1 = black).
401	 * @param {string} hex - e.g. '#445577'
402	 * @param {number} factor - 0..1
403	 * @returns {string}
404	 */
405	function _darkenColor(hex, factor) {
406	  const r = parseInt(hex.slice(1, 3), 16);
407	  const g = parseInt(hex.slice(3, 5), 16);
408	  const b = parseInt(hex.slice(5, 7), 16);
409	  const f = 1 - factor;
410	  return 'rgb(' + Math.floor(r * f) + ',' + Math.floor(g * f) + ',' + Math.floor(b * f) + ')';
411	}
412	
413	/**
414	 * Lighten a hex color by a factor.
415	 * @param {string} hex
416	 * @param {number} factor - 0..1
417	 * @returns {string}
418	 */
419	function _lightenColor(hex, factor) {
420	  const r = parseInt(hex.slice(1, 3), 16);
421	  const g = parseInt(hex.slice(3, 5), 16);
422	  const b = parseInt(hex.slice(5, 7), 16);
423	  const f = 1 - factor;
424	  return 'rgb(' +
425	    Math.floor(r + (255 - r) * factor) + ',' +
426	    Math.floor(g + (255 - g) * factor) + ',' +
427	    Math.floor(b + (255 - b) * factor) + ')';
428	}
