458	  ctx.fillStyle = glowGrad;
459	  ctx.fillRect(0, 0, W, H);
460	
461	  // --- 2. Title: "ASPHALT LEGENDS" with chrome/gradient effect ---
462	  const titleY = H * 0.24;
463	  // Shadow first (drawn behind the gradient text)
464	  ctx.save();
465	  ctx.font = MC.TITLE_FONT;
466	  ctx.textAlign = 'center';
467	  ctx.textBaseline = 'alphabetic';
