471	
472	  // Main chrome gradient text
473	  R.drawGradientText(
474	    'ASPHALT LEGENDS',
475	    W / 2,
476	    titleY,
477	    MC.TITLE_COLOR_TOP,
478	    MC.TITLE_COLOR_BOTTOM,
479	    MC.TITLE_FONT
480	  );
481	
482	  // Secondary highlight pass: lighter thin stroke at top for chrome effect
483	  ctx.save();
484	  ctx.font = MC.TITLE_FONT;
485	  ctx.textAlign = 'center';
486	  ctx.textBaseline = 'alphabetic';
487	  // Clip to top half of text area
488	  const titleMetrics = ctx.measureText('ASPHALT LEGENDS');
489	  const titleH = titleMetrics.actualBoundingBoxAscent + titleMetrics.actualBoundingBoxDescent;
490	  const estTitleH = titleH > 0 ? titleH : MC.TITLE_FONT_SIZE * 1.2;
491	  const clipTop = titleY - estTitleH;
492	  ctx.beginPath();
493	  ctx.rect(0, clipTop, W, estTitleH * 0.45);
494	  ctx.clip();
495	  ctx.fillStyle = 'rgba(255, 255, 255, 0.25)';
496	  ctx.fillText('ASPHALT LEGENDS', W / 2, titleY);
497	  ctx.restore();
498	
499	  // --- 3. Subtitle ---
500	  const subtitleY = titleY + MC.TITLE_FONT_SIZE * 0.5;
501	  ctx.fillStyle = MC.SUBTITLE_COLOR;
502	  ctx.font = MC.SUBTITLE_FONT;
503	  ctx.textAlign = 'center';
504	  ctx.textBaseline = 'top';
505	  ctx.shadowColor = 'rgba(0, 0, 0, 0.4)';
506	  ctx.shadowBlur = 3;
507	  ctx.fillText('CANVAS RACING CHAMPIONSHIP', W / 2, subtitleY);
508	  ctx.shadowBlur = 0;
509	
510	  // Decorative line under subtitle
511	  const lineY = subtitleY + MC.SUBTITLE_FONT_SIZE + 14;
512	  const lineW = W * 0.25;
513	  const lineGrad = ctx.createLinearGradient(W / 2 - lineW / 2, 0, W / 2 + lineW / 2, 0);
514	  lineGrad.addColorStop(0, 'rgba(136, 153, 187, 0)');
515	  lineGrad.addColorStop(0.5, 'rgba(136, 153, 187, 0.5)');
516	  lineGrad.addColorStop(1, 'rgba(136, 153, 187, 0)');
517	  ctx.strokeStyle = lineGrad;
518	  ctx.lineWidth = 1.5;
519	  ctx.beginPath();
520	  ctx.moveTo(W / 2 - lineW / 2, lineY);
521	  ctx.lineTo(W / 2 + lineW / 2, lineY);
522	  ctx.stroke();
523	
524	  // --- 4. Animated car silhouette ---
525	  const elapsed = time - _menuEntranceTime;
526	  const carSlideT = Math.max(0, Math.min(1, (elapsed - MC.CAR_SLIDE_DELAY) / MC.CAR_SLIDE_DURATION));
527	  const carEasedT = _easeOutCubic(carSlideT);
528	  const carTargetX = W / 2;
529	  const carStartX = W + 200;
530	  const carX = carStartX + (carTargetX - carStartX) * carEasedT;
531	  const carY = H * 0.80;
532	  const carScale = 0.9 + 0.1 * carEasedT; // slight scale pop at end
533	
534	  // Road line behind car
535	  ctx.strokeStyle = 'rgba(255, 255, 255, 0.06)';
536	  ctx.lineWidth = 2;
537	  ctx.beginPath();
538	  ctx.moveTo(0, carY + 22 * carScale);
539	  ctx.lineTo(W, carY + 22 * carScale);
540	  ctx.stroke();
541	
542	  // Draw car with slight alpha fade during slide
543	  ctx.globalAlpha = 0.5 + 0.5 * carEasedT;
544	  _drawCarSilhouette(ctx, carX, carY, carScale);
545	  ctx.globalAlpha = 1;
546	
547	  // Speed lines behind the car during entrance
548	  if (carSlideT < 1 && carSlideT > 0.05) {
549	    const lineAlpha = (1 - carSlideT) * 0.5;
550	    ctx.strokeStyle = 'rgba(200, 210, 230, ' + lineAlpha + ')';
551	    ctx.lineWidth = 1;
552	    const lineCount = 8;
553	    for (let i = 0; i < lineCount; i++) {
554	      const lx = carX + 140 * carScale + Math.random() * 300;
555	      const ly = carY - 20 * carScale + (Math.random() - 0.5) * 40 * carScale;
556	      const ll = 30 + Math.random() * 80;
557	      ctx.beginPath();
558	      ctx.moveTo(lx, ly);
559	      ctx.lineTo(lx + ll, ly);
560	      ctx.stroke();
561	    }
562	  }
563	
564	  // --- 5. Blinking prompt ---
565	  const promptY = H * 0.90;
566	  const pulseAlpha = 0.5 + 0.5 * Math.sin(time * MC.PULSE_SPEED);
567	  ctx.fillStyle = 'rgba(255, 255, 255, ' + (0.6 + pulseAlpha * 0.4) + ')';
568	  ctx.font = MC.PROMPT_FONT;
569	  ctx.textAlign = 'center';
570	  ctx.textBaseline = 'middle';
571	  ctx.shadowColor = 'rgba(255, 255, 255, ' + (pulseAlpha * 0.4) + ')';
572	  ctx.shadowBlur = 8 + pulseAlpha * 6;
573	  ctx.fillText('PRESS ENTER TO RACE', W / 2, promptY);
574	  ctx.shadowBlur = 0;
575	
576	  // --- 6. Controls hint ---
577	  const hintY = H * 0.945;
578	  ctx.fillStyle = MC.HINT_COLOR;
579	  ctx.font = MC.HINT_FONT;
580	  ctx.textAlign = 'center';
581	  ctx.textBaseline = 'middle';
582	  ctx.fillText('↑↓←→ or WASD to drive | SHIFT for boost | ESC to pause', W / 2, hintY);
583	
584	  // --- 7. Version number ---
585	  ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
586	  ctx.font = MC.VERSION_FONT;
587	  ctx.textAlign = 'right';
588	  ctx.textBaseline = 'bottom';
589	  ctx.fillText('v1.0', W - 16, H - 12);
590	};
