656	/* =====================================================================
657	   R.renderCountdownScreen(number) — Countdown Numbers
658	   Called each frame with the current number (3, 2, 1, or "GO!").
659	   Scale animation with cubic ease-out.
660	   ===================================================================== */
661	
662	R.renderCountdownScreen = function(number) {
663	  const ctx = R.ctx;
664	  const W = R.canvas.width;
665	  const H = R.canvas.height;
666	  const time = R.state.time;
667	
668	  // Detect count change
669	  if (_lastCountNumber !== number) {
670	    _lastCountNumber = number;
671	    _countChangeTime = time;
672	  }
673	
674	  // Compute scale with cubic ease-out
675	  const elapsed = time - _countChangeTime;
676	  const duration = MC.COUNTDOWN_DURATION;
677	  const t = Math.min(elapsed / duration, 1);
678	  const scale = 1 + (MC.COUNTDOWN_START_SCALE - 1) * Math.pow(1 - t, 3);
679	  const alpha = number === 'GO!' ? 1 : 0.5 + 0.5 * Math.pow(1 - t, 2); // fade in as it shrinks
680	
681	  ctx.save();
682	
683	  // Semi-transparent backdrop
684	  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
685	  ctx.fillRect(0, 0, W, H);
686	
687	  // Text color: white for numbers, gold for GO!
688	  const isGo = (number === 'GO!');
689	  const textColor = isGo ? '#ffdd44' : '#ffffff';
690	  const glowColor = isGo ? 'rgba(255, 200, 50, 0.5)' : 'rgba(255, 255, 255, 0.35)';
691	
692	  ctx.textAlign = 'center';
693	  ctx.textBaseline = 'middle';
694	  ctx.font = MC.COUNTDOWN_FONT;
695	
696	  // Apply scale transform around center
697	  ctx.translate(W / 2, H * 0.42);
698	  ctx.scale(scale, scale);
699	  ctx.globalAlpha = alpha;
700	
701	  // Glow
702	  ctx.shadowColor = glowColor;
703	  ctx.shadowBlur = 18 * scale;
704	  ctx.fillStyle = textColor;
705	  ctx.fillText(String(number), 0, 0);
706	
707	  // Second pass: brighter core
708	  ctx.shadowBlur = 0;
709	  ctx.fillStyle = textColor;
710	  ctx.fillText(String(number), 0, 0);
711	
712	  ctx.restore();
713	};
