715	/* =====================================================================
716	   R.renderFinishScreen() — Race Results Overlay
717	   ===================================================================== */
718	
719	R.renderFinishScreen = function() {
720	  const ctx = R.ctx;
721	  const W = R.canvas.width;
722	  const H = R.canvas.height;
723	
724	  // --- 1. Dark semi-transparent background ---
725	  ctx.fillStyle = 'rgba(0, 0, 0, ' + MC.OVERLAY_ALPHA + ')';
726	  ctx.fillRect(0, 0, W, H);
727	
728	  // --- 2. "RACE COMPLETE!" title with golden gradient ---
729	  const finishTitleY = H * 0.12;
730	  R.drawGradientText(
731	    'RACE COMPLETE!',
732	    W / 2,
733	    finishTitleY,
734	    MC.GOLD_TOP,
735	    MC.GOLD_BOTTOM,
736	    MC.FINISH_TITLE_FONT
737	  );
738	
739	  // Add subtle glow behind title
740	  ctx.save();
741	  ctx.font = MC.FINISH_TITLE_FONT;
742	  ctx.textAlign = 'center';
743	  ctx.textBaseline = 'alphabetic';
744	  ctx.shadowColor = 'rgba(255, 200, 50, 0.4)';
745	  ctx.shadowBlur = 20;
746	  ctx.fillStyle = 'rgba(0, 0, 0, 0)';
747	  ctx.fillText('RACE COMPLETE!', W / 2, finishTitleY);
748	  ctx.shadowBlur = 0;
749	  ctx.restore();
750	
751	  // --- Gather race results ---
752	  // Try R.raceResults first, otherwise build from R.cars.
753	  /** @type {Array<{name:string, time:number, color:string, isPlayer:boolean}>} */
754	  let results = [];
755	  let playerName = 'You';
756	  let playerIndex = -1;
757	
758	  if (R.raceResults && R.raceResults.length > 0) {
759	    // Pre-computed results array
760	    results = R.raceResults.map(function(r, i) {
761	      return {
762	        name: r.name || r.driver || ('Racer ' + (i + 1)),
763	        time: r.time || r.raceTime || r.finishTime || 0,
764	        color: r.color || '#888888',
765	        isPlayer: r.isPlayer || false,
766	      };
767	    });
768	    for (let i = 0; i < results.length; i++) {
769	      if (results[i].isPlayer) { playerIndex = i; break; }
770	    }
771	  } else if (R.cars && R.cars.length > 0) {
772	    // Build from car objects: sort by raceTime, then by laps descending for DNF
773	    const cars = R.cars.slice();
774	    cars.sort(function(a, b) {
775	      // Finished cars first, sorted by time
776	      if (a.finished && b.finished) return (a.raceTime || 0) - (b.raceTime || 0);
777	      if (a.finished && !b.finished) return -1;
778	      if (!a.finished && b.finished) return 1;
779	      // Both unfinished: more laps = better position
780	      const lapDiff = (b.lap || 0) - (a.lap || 0);
781	      if (lapDiff !== 0) return lapDiff;
782	      return (b.checkpointIdx || 0) - (a.checkpointIdx || 0);
783	    });
784	    results = cars.map(function(car, i) {
785	      return {
786	        name: car.name || car.driverName || (i === 0 ? 'You' : 'AI ' + i),
787	        time: car.raceTime != null ? car.raceTime : null,
788	        color: car.color || '#888888',
789	        isPlayer: car.isPlayer || (i === 0),
790	      };
791	    });
792	    for (let i = 0; i < results.length; i++) {
793	      if (results[i].isPlayer) { playerIndex = i; break; }
794	    }
795	  }
796	
797	  // If still no results, show a placeholder
798	  if (results.length === 0) {
799	    results = [{ name: 'You', time: R.state.time || 0, color: '#ff6644', isPlayer: true }];
800	    playerIndex = 0;
801	  }
802	
803	  // --- 3. Results table ---
804	  const tableTop = H * 0.25;
805	  const headerY = tableTop;
806	  const rowH = 36;
807	  const colPad = 16;
808	  const tableW = Math.min(W * 0.72, 600);
809	  const tableX = (W - tableW) / 2;
810	
811	  // Panel behind table
812	  const panelPad = 20;
813	  const panelH = headerY + (results.length + 1) * rowH + panelPad * 2 - tableTop + 10;
814	  R.drawPanel(tableX - panelPad, tableTop - panelPad, tableW + panelPad * 2, panelH, 0.85);
815	
816	  // Column layout
817	  const posColX = tableX + 30;
818	  const nameColX = tableX + 100;
819	  const timeColX = tableX + tableW - 40;
820	
821	  // --- Header row ---
822	  ctx.fillStyle = '#8899aa';
823	  ctx.font = 'bold ' + MC.RESULTS_HEADER_SIZE + 'px ' + MC.RESULTS_FONT;
824	  ctx.textBaseline = 'middle';
825	
826	  ctx.textAlign = 'left';
827	  ctx.fillText('POS', posColX, headerY);
828	  ctx.fillText('DRIVER', nameColX, headerY);
829	  ctx.textAlign = 'right';
